select app.sync_content($content${"tracks":[{"slug":"fundamentos","title":"Fundamentos","description":"Lógica, algoritmos, estruturas de dados, Git e terminal: a base de qualquer carreira em programação.","required":true,"position":0},{"slug":"web-base","title":"Web base","description":"HTML, CSS, JavaScript, TypeScript, HTTP e acessibilidade: o alicerce da plataforma web.","required":true,"position":1},{"slug":"frontend-vue","title":"Front-end com Vue","description":"Vue 3, Composition API, Router, Pinia, Vite, testes e performance.","required":true,"position":2},{"slug":"backend-php-laravel","title":"Back-end com PHP e Laravel","description":"PHP moderno, POO, Composer, rotas, Eloquent, validação, autenticação, filas, cache, eventos e testes com Pest.","required":true,"position":3},{"slug":"banco-de-dados-sql","title":"Banco de dados e SQL","description":"Modelagem, normalização, índices, transações e otimização de queries.","required":true,"position":4},{"slug":"qualidade","title":"Qualidade","description":"Testes, CI/CD, code review, refatoração e clean code.","required":true,"position":5},{"slug":"arquitetura-system-design","title":"Arquitetura e System Design","description":"Padrões, DDD básico, escalabilidade e análise de trade-offs.","required":true,"position":6},{"slug":"devops-observabilidade","title":"DevOps e Observabilidade","description":"Linux, Docker, deploy, logs, métricas e operação em produção.","required":true,"position":7},{"slug":"seguranca","title":"Segurança","description":"OWASP, autenticação, autorização e boas práticas de segurança.","required":true,"position":8},{"slug":"carreira-soft-skills","title":"Carreira e Soft Skills","description":"Comunicação, estimativas, documentação, feedback e mentoria.","required":false,"position":9}],"topics":[{"track":"fundamentos","slug":"fund-logica-de-programacao","title":"Lógica de programação","description":"Decompor um problema em passos claros e sem ambiguidade antes de escrever código: algoritmos, pseudocódigo, fluxogramas e os três blocos básicos (sequência, decisão e repetição). É o raciocínio que sustenta todo o resto da carreira, em qualquer linguagem.","level":"beginner","difficulty":1,"position":0,"prerequisites":[],"resources":[{"name":"CS50x — Introdução à Ciência da Computação (Harvard)","url":"https://cs50.harvard.edu/x/"},{"name":"Livro: Lógica de Programação: A Construção de Algoritmos e Estruturas de Dados — Forbellone e Eberspächer"},{"name":"Livro: Think Like a Programmer — V. Anton Spraul"},{"name":"Exercism — exercícios práticos de programação","url":"https://exercism.org/"}],"checklist":[{"key":"explicar-algoritmo","text":"Consigo explicar com minhas palavras o que é um algoritmo e quais propriedades ele precisa ter (finito, não ambíguo, com entrada e saída definidas)."},{"key":"pseudocodigo-e-fluxograma","text":"Sei escrever o pseudocódigo ou desenhar o fluxograma de um problema simples (ex.: calcular a média de notas e dizer se o aluno foi aprovado) antes de codar."},{"key":"sequencia-decisao-repeticao","text":"Consigo identificar, em uma solução, quais trechos são sequência, decisão e repetição e combinar os três para resolver um problema."},{"key":"teste-de-mesa","text":"Sei fazer um teste de mesa: simular o algoritmo à mão, passo a passo, anotando o valor de cada variável."},{"key":"decompor-problemas","text":"Consigo quebrar um problema maior em subproblemas menores e resolver um de cada vez."},{"key":"exercicios-resolvidos","text":"Já resolvi pelo menos 10 exercícios de lógica (ex.: no Exercism) sem consultar a solução pronta."}]},{"track":"fundamentos","slug":"fund-variaveis-e-tipos","title":"Variáveis e tipos","description":"Como os programas guardam e manipulam dados: variáveis, constantes, tipos primitivos (inteiros, ponto flutuante, strings, booleanos, null), conversões de tipo e a diferença entre tipagem estática e dinâmica. Inclui armadilhas clássicas, como a precisão de ponto flutuante e a comparação entre tipos diferentes.","level":"beginner","difficulty":1,"position":1,"prerequisites":["fund-logica-de-programacao"],"resources":[{"name":"MDN — Gramática e tipos (Guia JavaScript)","url":"https://developer.mozilla.org/pt-BR/docs/Web/JavaScript/Guide/Grammar_and_types"},{"name":"Manual do PHP — Tipos","url":"https://www.php.net/manual/pt_BR/language.types.php"},{"name":"Manual do PHP — Manipulação de tipos (type juggling)","url":"https://www.php.net/manual/pt_BR/language.types.type-juggling.php"},{"name":"0.30000000000000004.com — por que 0.1 + 0.2 não é 0.3","url":"https://0.30000000000000004.com/"}],"checklist":[{"key":"declarar-variaveis-e-constantes","text":"Sei declarar variáveis e constantes na linguagem que estou estudando e explicar quando usar cada uma (ex.: const e let em JavaScript)."},{"key":"tipos-primitivos","text":"Consigo listar os tipos primitivos (inteiro, ponto flutuante, string, booleano, null) e dar um exemplo de valor de cada um."},{"key":"conversao-de-tipos","text":"Sei converter valores entre tipos de forma explícita e prever o resultado de conversões implícitas, como '5' + 3 e '5' - 3 em JavaScript."},{"key":"igualdade-e-valores-falsos","text":"Sei comparar valores corretamente, entendendo a diferença entre == e === e quais valores são tratados como falsos na linguagem que uso (ex.: 0, string vazia, null)."},{"key":"precisao-ponto-flutuante","text":"Consigo explicar por que 0.1 + 0.2 não resulta exatamente em 0.3 e como evitar esse problema com dinheiro (guardar centavos como inteiros ou usar tipos decimais)."},{"key":"tipagem-estatica-vs-dinamica","text":"Sei diferenciar tipagem estática de dinâmica e tipagem forte de fraca, citando uma linguagem de cada tipo."}]},{"track":"fundamentos","slug":"fund-condicionais-e-lacos","title":"Condicionais e laços","description":"Controle de fluxo: decisões com if/else, switch/match e operadores lógicos, e repetições com for, while e do-while, incluindo break e continue. Aprenda a escolher o laço certo, evitar laços infinitos e erros de off-by-one e simplificar condições aninhadas com retorno antecipado.","level":"beginner","difficulty":1,"position":2,"prerequisites":["fund-variaveis-e-tipos"],"resources":[{"name":"MDN — Controle de fluxo e tratamento de erros (Guia JavaScript)","url":"https://developer.mozilla.org/pt-BR/docs/Web/JavaScript/Guide/Control_flow_and_error_handling"},{"name":"MDN — Laços e iteração (Guia JavaScript)","url":"https://developer.mozilla.org/pt-BR/docs/Web/JavaScript/Guide/Loops_and_iteration"},{"name":"Manual do PHP — Estruturas de controle","url":"https://www.php.net/manual/pt_BR/language.control-structures.php"},{"name":"Manual do PHP — match (PHP 8)","url":"https://www.php.net/manual/pt_BR/control-structures.match.php"}],"checklist":[{"key":"if-else-e-operadores-logicos","text":"Sei escrever decisões com if/else if/else combinando operadores lógicos (&&, || e !) e explicar em que condições cada ramo executa."},{"key":"switch-ou-match","text":"Sei quando usar switch ou match em vez de uma cadeia de if/else e por que um switch sem break causa fall-through."},{"key":"escolher-o-laco-certo","text":"Consigo escolher entre for, while, do-while e foreach/for...of e justificar a escolha para cada problema."},{"key":"laco-infinito-e-off-by-one","text":"Sei identificar e corrigir um laço infinito e erros de off-by-one (um passo a mais ou a menos) usando teste de mesa."},{"key":"break-continue-e-guard-clauses","text":"Uso break, continue e retorno antecipado (guard clauses) para reduzir o aninhamento de condições."},{"key":"fizzbuzz-tabuada-e-primos","text":"Já implementei sozinho FizzBuzz, tabuada e verificação de número primo usando apenas condicionais e laços."}]},{"track":"fundamentos","slug":"fund-funcoes","title":"Funções","description":"Como encapsular lógica reutilizável: parâmetros e retorno, escopo de variáveis, funções puras versus efeitos colaterais, funções anônimas e arrow functions, funções como valores (callbacks) e noções de closure. Funções pequenas e bem nomeadas são a base de código legível e testável.","level":"beginner","difficulty":2,"position":3,"prerequisites":["fund-condicionais-e-lacos"],"resources":[{"name":"MDN — Funções (Guia JavaScript)","url":"https://developer.mozilla.org/pt-BR/docs/Web/JavaScript/Guide/Functions"},{"name":"MDN — Closures","url":"https://developer.mozilla.org/pt-BR/docs/Web/JavaScript/Guide/Closures"},{"name":"Manual do PHP — Funções","url":"https://www.php.net/manual/pt_BR/language.functions.php"},{"name":"Livro: Código Limpo (Clean Code) — Robert C. Martin, capítulo sobre funções"}],"checklist":[{"key":"parametros-e-retorno","text":"Sei definir funções com parâmetros, valores padrão e retorno, inclusive devolvendo mais de um valor (array ou objeto)."},{"key":"escopo-de-variaveis","text":"Consigo explicar escopo local, de função e global e prever a saída de um código com variáveis de mesmo nome em escopos diferentes."},{"key":"funcao-pura-vs-efeito-colateral","text":"Sei diferenciar função pura de função com efeito colateral e reescrever uma função impura para que fique pura."},{"key":"funcoes-como-valores","text":"Sei passar uma função como argumento (callback) e usar funções anônimas e arrow functions, como em map, filter e reduce."},{"key":"closure-basica","text":"Consigo explicar o que é uma closure com um exemplo simples (ex.: uma função que cria contadores independentes)."},{"key":"funcao-pequena-e-bem-nomeada","text":"Consigo dividir uma função grande em funções menores, cada uma com um único propósito e um nome que revele a intenção."}]},{"track":"fundamentos","slug":"fund-terminal-e-shell","title":"Terminal e shell","description":"Trabalhar pela linha de comando: navegar e manipular arquivos, ler e buscar conteúdo, permissões, variáveis de ambiente, pipes e redirecionamento e scripts simples. Dominar o shell acelera o dia a dia de qualquer dev, de Git e Composer a Docker e deploy.","level":"beginner","difficulty":2,"position":4,"prerequisites":[],"resources":[{"name":"The Missing Semester of Your CS Education (MIT) — aula sobre o shell","url":"https://missing.csail.mit.edu/2020/course-shell/"},{"name":"Linux man pages online (man7.org)","url":"https://man7.org/linux/man-pages/"},{"name":"explainshell — explica comandos de shell trecho a trecho","url":"https://explainshell.com/"},{"name":"Documentação do PowerShell — Microsoft Learn","url":"https://learn.microsoft.com/pt-br/powershell/"}],"checklist":[{"key":"navegar-e-manipular-arquivos","text":"Consigo navegar entre diretórios e criar, copiar, mover e remover arquivos e pastas apenas pelo terminal (cd, ls, mkdir, cp, mv, rm)."},{"key":"ler-e-buscar-conteudo","text":"Sei ler arquivos com cat, less, head e tail e buscar texto com grep e arquivos com find."},{"key":"pipes-e-redirecionamento","text":"Sei combinar comandos com pipe (|) e redirecionar saída e erros (>, >> e 2>), por exemplo filtrando um log e salvando o resultado em um arquivo."},{"key":"variaveis-de-ambiente-e-path","text":"Entendo o que são variáveis de ambiente e o PATH e sei definir uma variável para um comando e exportá-la na sessão."},{"key":"permissoes-de-arquivo","text":"Sei ler permissões (rwx) e alterá-las com chmod, e explico por que um script pode falhar com 'permission denied'."},{"key":"script-simples","text":"Já escrevi um script de shell simples (com argumentos, condicional e laço) que automatiza uma tarefa repetitiva."}]},{"track":"fundamentos","slug":"fund-git-basico","title":"Git básico","description":"Controle de versão com Git no dia a dia: repositório, working tree, staging e commits, branches e merge, repositórios remotos (clone, fetch, pull, push), .gitignore e resolução de conflitos simples. Inclui boas mensagens de commit e o fluxo básico de trabalho com pull requests.","level":"beginner","difficulty":2,"position":5,"prerequisites":["fund-terminal-e-shell"],"resources":[{"name":"Pro Git (livro oficial, em português)","url":"https://git-scm.com/book/pt-br/v2"},{"name":"Documentação de referência do Git","url":"https://git-scm.com/docs"},{"name":"Learn Git Branching — tutorial interativo","url":"https://learngitbranching.js.org/"},{"name":"Conventional Commits 1.0.0","url":"https://www.conventionalcommits.org/pt-br/v1.0.0/"}],"checklist":[{"key":"working-tree-staging-commit","text":"Consigo explicar a diferença entre working tree, staging area (index) e repositório e o caminho de uma alteração até virar um commit."},{"key":"init-add-commit-status-log","text":"Sei criar um repositório e usar git init, status, add, commit, diff e log no dia a dia."},{"key":"branches-e-merge","text":"Sei criar branches, alternar entre elas e fazer merge, e explico a diferença entre fast-forward e merge commit."},{"key":"remotos-clone-fetch-pull-push","text":"Sei clonar um repositório e sincronizar com o remoto usando fetch, pull e push, e explico a diferença entre fetch e pull."},{"key":"resolver-conflito-de-merge","text":"Já resolvi um conflito de merge manualmente, entendendo os marcadores <<<<<<<, ======= e >>>>>>>."},{"key":"gitignore-e-mensagens-de-commit","text":"Uso .gitignore corretamente (sem versionar .env, node_modules ou vendor) e escrevo mensagens de commit claras, no padrão Conventional Commits."}]},{"track":"fundamentos","slug":"fund-git-avancado","title":"Git avançado (rebase, bisect)","description":"Reescrever e investigar o histórico com segurança: rebase (inclusive interativo), cherry-pick, reset versus revert, stash, reflog para recuperar trabalho perdido e bisect para achar o commit que introduziu um bug. Também cobre estratégias de integração (merge, squash e rebase) e por que não reescrever histórico compartilhado.","level":"junior","difficulty":3,"position":6,"prerequisites":["fund-git-basico"],"resources":[{"name":"Pro Git — Git Branching: Rebasing","url":"https://git-scm.com/book/en/v2/Git-Branching-Rebasing"},{"name":"Pro Git — Git Tools: Rewriting History","url":"https://git-scm.com/book/en/v2/Git-Tools-Rewriting-History"},{"name":"Pro Git — Git Tools: Debugging with Git (bisect)","url":"https://git-scm.com/book/en/v2/Git-Tools-Debugging-with-Git"},{"name":"Documentação do git reflog","url":"https://git-scm.com/docs/git-reflog"}],"checklist":[{"key":"rebase-vs-merge","text":"Consigo explicar a diferença entre merge e rebase, o efeito de cada um no histórico e por que não devo reescrever commits já publicados em branches compartilhadas."},{"key":"rebase-interativo","text":"Já usei git rebase -i para fazer squash, reword e reordenar commits antes de abrir um pull request, e sei publicar o resultado com git push --force-with-lease."},{"key":"reset-revert-restore","text":"Sei diferenciar reset (--soft, --mixed e --hard), revert e restore e escolher o certo para desfazer um commit local ou já publicado."},{"key":"reflog-recuperar-trabalho","text":"Já recuperei commits ou uma branch 'perdida' (após um reset --hard ou um rebase errado) usando git reflog."},{"key":"bisect-achar-bug","text":"Já usei git bisect (manual ou com git bisect run) para localizar o commit que introduziu um bug."},{"key":"cherry-pick-e-stash","text":"Sei usar git cherry-pick para levar um commit a outra branch e git stash para guardar trabalho em andamento e retomá-lo depois."}]},{"track":"fundamentos","slug":"fund-arrays-listas-e-mapas","title":"Arrays, listas e mapas","description":"As estruturas de dados do dia a dia: arrays/listas, mapas (dicionários e arrays associativos) e conjuntos. Veja como percorrer, buscar, inserir e remover elementos, transformar coleções com map, filter e reduce e escolher a estrutura certa para cada problema.","level":"junior","difficulty":2,"position":7,"prerequisites":["fund-variaveis-e-tipos","fund-condicionais-e-lacos"],"resources":[{"name":"MDN — Array (JavaScript)","url":"https://developer.mozilla.org/pt-BR/docs/Web/JavaScript/Reference/Global_Objects/Array"},{"name":"MDN — Coleções com chave: Map e Set (Guia JavaScript)","url":"https://developer.mozilla.org/pt-BR/docs/Web/JavaScript/Guide/Keyed_collections"},{"name":"Manual do PHP — Arrays","url":"https://www.php.net/manual/pt_BR/language.types.array.php"},{"name":"Manual do PHP — Funções de array","url":"https://www.php.net/manual/pt_BR/ref.array.php"}],"checklist":[{"key":"criar-acessar-e-modificar-arrays","text":"Sei criar arrays/listas, acessar elementos por índice e adicionar, remover e alterar itens (push/pop, shift/unshift, splice ou equivalentes)."},{"key":"percorrer-colecoes","text":"Consigo percorrer arrays e mapas com laços e iteradores (for...of, foreach) e sei quando preciso do índice."},{"key":"map-filter-reduce","text":"Sei transformar coleções com map, filter e reduce (ou array_map, array_filter e array_reduce) sem escrever laços manuais."},{"key":"mapas-e-conjuntos","text":"Sei usar mapas (chave e valor) e conjuntos para contar ocorrências, agrupar itens e remover duplicados."},{"key":"escolher-a-estrutura-certa","text":"Consigo justificar quando usar array, mapa ou conjunto em um problema (ex.: busca por id, lista ordenada, garantia de unicidade)."},{"key":"copia-rasa-vs-profunda","text":"Entendo a diferença entre copiar a referência, fazer uma cópia rasa e uma cópia profunda de um array ou objeto, e o risco de mutação inesperada."}]},{"track":"fundamentos","slug":"fund-recursao","title":"Recursão","description":"Resolver problemas fazendo uma função chamar a si mesma: caso base, caso recursivo, pilha de chamadas e risco de estouro de pilha. Inclui exemplos clássicos (fatorial, Fibonacci, soma de listas, permutações, estruturas aninhadas), memoização e quando preferir iteração.","level":"junior","difficulty":3,"position":8,"prerequisites":["fund-funcoes","fund-arrays-listas-e-mapas"],"resources":[{"name":"Python Tutor — visualize a execução do código e a pilha de chamadas","url":"https://pythontutor.com/"},{"name":"Khan Academy — Algoritmos (algoritmos recursivos)","url":"https://pt.khanacademy.org/computing/computer-science/algorithms"},{"name":"Livro: Entendendo Algoritmos — Aditya Bhargava (capítulo sobre recursão)"},{"name":"MDN — Recursão (glossário)","url":"https://developer.mozilla.org/pt-BR/docs/Glossary/Recursion"}],"checklist":[{"key":"caso-base-e-caso-recursivo","text":"Consigo identificar o caso base e o caso recursivo de uma função e explicar por que, sem o caso base, ela nunca termina."},{"key":"pilha-de-chamadas","text":"Sei desenhar a pilha de chamadas de uma função recursiva simples (ex.: fatorial de 4) e explicar o que é um estouro de pilha (stack overflow)."},{"key":"recursao-classica","text":"Já implementei recursivamente fatorial, Fibonacci, soma dos elementos de uma lista e inversão de uma string, sem consultar a solução."},{"key":"estruturas-aninhadas","text":"Sei usar recursão para percorrer estruturas aninhadas (ex.: achatar um array de arrays ou listar os arquivos de um diretório)."},{"key":"memoizacao","text":"Sei aplicar memoização para evitar recálculos (ex.: Fibonacci) e explicar o ganho de desempenho."},{"key":"recursao-vs-iteracao","text":"Consigo converter uma recursão simples em iteração (e o contrário) e decidir qual é mais adequada em cada caso."}]},{"track":"fundamentos","slug":"fund-complexidade-big-o","title":"Complexidade (Big-O)","description":"Medir como o tempo e a memória de um algoritmo crescem com o tamanho da entrada: notação Big-O, classes comuns (O(1), O(log n), O(n), O(n log n), O(n²) e O(2^n)), pior caso versus caso médio e complexidade de espaço. O objetivo é comparar soluções antes de implementá-las e justificar trade-offs entre tempo e memória.","level":"junior","difficulty":3,"position":9,"prerequisites":["fund-arrays-listas-e-mapas","fund-recursao"],"resources":[{"name":"Big-O Cheat Sheet","url":"https://www.bigocheatsheet.com/"},{"name":"Algorithms, 4th Edition — Sedgewick e Wayne (análise de algoritmos)","url":"https://algs4.cs.princeton.edu/14analysis/"},{"name":"Livro: Entendendo Algoritmos — Aditya Bhargava (introdução e notação Big O)"},{"name":"VisuAlgo — visualização de algoritmos e estruturas de dados","url":"https://visualgo.net/en"}],"checklist":[{"key":"explicar-big-o","text":"Consigo explicar com minhas palavras o que o Big-O mede (crescimento em função de n) e por que ignoramos constantes e termos menores."},{"key":"analisar-codigo-com-lacos","text":"Sei determinar a complexidade de tempo de um trecho de código com laços simples, laços aninhados e laços que dividem o espaço de busca pela metade."},{"key":"comparar-classes-de-crescimento","text":"Consigo ordenar O(1), O(log n), O(n), O(n log n), O(n²) e O(2^n) por crescimento e estimar o que cada uma significa para n = 1 milhão."},{"key":"complexidade-de-espaco","text":"Sei analisar a complexidade de espaço (memória extra e pilha de recursão) de um algoritmo."},{"key":"custo-das-operacoes-comuns","text":"Sei de cabeça o custo típico das operações em array, mapa (hash) e conjunto: acesso, busca, inserção e remoção."},{"key":"otimizar-solucao-ingenua","text":"Já otimizei uma solução O(n²) para O(n) (ex.: soma de dois números com um mapa) e expliquei o ganho."}]},{"track":"fundamentos","slug":"fund-pilhas-filas-e-listas-ligadas","title":"Pilhas, filas e listas ligadas","description":"Estruturas de dados lineares fundamentais: pilha (LIFO), fila (FIFO), deque e lista ligada (simples e dupla), com seus custos de operação e usos reais (pilha de chamadas, desfazer/refazer, filas de tarefas, cache LRU). Aprenda a implementá-las do zero e a decidir quando usar cada uma.","level":"junior","difficulty":3,"position":10,"prerequisites":["fund-arrays-listas-e-mapas","fund-complexidade-big-o"],"resources":[{"name":"Manual do PHP — Estruturas de dados da SPL (SplStack, SplQueue)","url":"https://www.php.net/manual/pt_BR/spl.datastructures.php"},{"name":"VisuAlgo — Linked List, Stack, Queue e Deque","url":"https://visualgo.net/en/list"},{"name":"Algorithms, 4th Edition — Sedgewick e Wayne (pilhas, filas e bags)","url":"https://algs4.cs.princeton.edu/13stacks/"},{"name":"Livro: Entendendo Algoritmos — Aditya Bhargava (arrays e listas ligadas)"}],"checklist":[{"key":"lifo-e-fifo","text":"Consigo explicar LIFO e FIFO e dar um exemplo real de cada (ex.: desfazer/refazer em um editor; fila de jobs)."},{"key":"implementar-pilha-e-fila","text":"Já implementei uma pilha e uma fila do zero, com inserção e remoção em O(1)."},{"key":"implementar-lista-ligada","text":"Já implementei uma lista ligada simples com inserção, remoção e busca, e sei invertê-la."},{"key":"lista-ligada-vs-array","text":"Sei comparar lista ligada e array em acesso por índice, inserção no meio e uso de memória, e justificar a escolha."},{"key":"problemas-classicos-com-pilha","text":"Sei resolver com pilha o problema dos parênteses balanceados e avaliar uma expressão em notação pós-fixa."},{"key":"deque-e-fila-de-prioridade","text":"Conheço deque e fila de prioridade e sei dizer quando usá-los (ex.: janela deslizante, agendador de tarefas)."}]},{"track":"fundamentos","slug":"fund-arvores-e-grafos","title":"Árvores e grafos","description":"Estruturas não lineares para modelar hierarquias e redes: árvores binárias e de busca (BST), heaps e grafos (direcionados ou não, com ou sem pesos). Cobre representações (lista e matriz de adjacência), percursos em profundidade (DFS) e em largura (BFS), detecção de ciclos, ordenação topológica e noções de caminho mínimo.","level":"mid","difficulty":4,"position":11,"prerequisites":["fund-recursao","fund-pilhas-filas-e-listas-ligadas"],"resources":[{"name":"VisuAlgo — Binary Search Tree, Heap e Graph Traversal","url":"https://visualgo.net/en/bst"},{"name":"Algorithms, 4th Edition — Sedgewick e Wayne (árvores de busca e grafos)","url":"https://algs4.cs.princeton.edu/home/"},{"name":"CP-Algorithms — algoritmos de grafos e estruturas de dados","url":"https://cp-algorithms.com/"},{"name":"Livro: Entendendo Algoritmos — Aditya Bhargava (busca em largura e algoritmo de Dijkstra)"}],"checklist":[{"key":"arvores-e-bst","text":"Consigo explicar o que é uma árvore binária de busca e por que a busca é O(log n) quando ela está balanceada e O(n) quando degenera em uma lista."},{"key":"implementar-bst-e-percursos","text":"Já implementei uma BST com inserção, busca e os percursos in-order, pre-order e post-order de forma recursiva."},{"key":"heap-e-fila-de-prioridade","text":"Sei explicar o que é um heap e usá-lo como fila de prioridade (ex.: obter os k maiores elementos de uma lista)."},{"key":"representar-grafos","text":"Sei representar um grafo com lista e com matriz de adjacência e escolher entre elas conforme a densidade."},{"key":"bfs-e-dfs","text":"Já implementei BFS e DFS e sei dizer quando usar cada uma (ex.: menor caminho sem pesos versus detecção de ciclos)."},{"key":"problemas-classicos-de-grafos","text":"Sei resolver problemas clássicos como contar componentes conectados, detectar ciclos e ordenar tarefas por dependência (ordenação topológica)."}]},{"track":"fundamentos","slug":"fund-ordenacao-e-busca","title":"Ordenação e busca","description":"Algoritmos clássicos de ordenação (bubble, selection, insertion, merge e quick sort) e de busca (linear e binária), com análise de complexidade, estabilidade e uso de memória. Mostra também como usar a ordenação das bibliotecas padrão com comparadores e por que a busca binária resolve problemas além de achar um valor.","level":"mid","difficulty":3,"position":12,"prerequisites":["fund-complexidade-big-o","fund-recursao"],"resources":[{"name":"VisuAlgo — animações de algoritmos de ordenação","url":"https://visualgo.net/en/sorting"},{"name":"Algorithms, 4th Edition — Sedgewick e Wayne (ordenação)","url":"https://algs4.cs.princeton.edu/20sorting/"},{"name":"Manual do PHP — Ordenando arrays","url":"https://www.php.net/manual/pt_BR/array.sorting.php"},{"name":"MDN — Array.prototype.sort","url":"https://developer.mozilla.org/pt-BR/docs/Web/JavaScript/Reference/Global_Objects/Array/sort"}],"checklist":[{"key":"ordenacoes-quadraticas","text":"Já implementei bubble, selection e insertion sort e sei explicar por que são O(n²) no pior caso (e por que o insertion sort vai bem em listas quase ordenadas)."},{"key":"merge-sort-e-quick-sort","text":"Sei implementar merge sort e quick sort e explicar a estratégia de dividir e conquistar, o custo O(n log n) e o pior caso do quick sort."},{"key":"estabilidade-e-in-place","text":"Sei explicar o que significa um algoritmo de ordenação ser estável e in-place e dar exemplos de cada tipo."},{"key":"busca-binaria","text":"Já implementei busca binária (iterativa e recursiva) sem erros de limites e sei que ela exige dados ordenados."},{"key":"sort-da-biblioteca-com-comparador","text":"Sei usar o sort da linguagem com comparador personalizado (ex.: ordenar objetos por vários campos) e explico por que [10, 9, 1].sort() em JavaScript retorna [1, 10, 9]."},{"key":"busca-binaria-na-resposta","text":"Sei aplicar a ideia da busca binária além de achar um valor (ex.: primeiro elemento maior ou igual a x, ou o menor valor que satisfaz uma condição)."}]},{"track":"fundamentos","slug":"fund-programacao-dinamica-e-greedy","title":"Programação dinâmica e greedy","description":"Duas técnicas para problemas de otimização. Programação dinâmica resolve subproblemas sobrepostos com memoização (top-down) ou tabulação (bottom-up); algoritmos gulosos (greedy) fazem a melhor escolha local e exigem argumentar que ela leva ao ótimo global. Você aprende a reconhecer o padrão de cada problema (mochila, subsequência comum, troco de moedas, agendamento de intervalos) e a analisar o custo.","level":"senior","difficulty":5,"position":13,"prerequisites":["fund-recursao","fund-ordenacao-e-busca","fund-arvores-e-grafos"],"resources":[{"name":"Algorithms — Jeff Erickson (programação dinâmica e algoritmos gulosos)","url":"https://jeffe.cs.illinois.edu/teaching/algorithms/"},{"name":"MIT OpenCourseWare — 6.006 Introduction to Algorithms","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/"},{"name":"AtCoder — Educational DP Contest (problemas graduais de DP)","url":"https://atcoder.jp/contests/dp"},{"name":"Livro: Entendendo Algoritmos — Aditya Bhargava (algoritmos gulosos e programação dinâmica)"}],"checklist":[{"key":"subproblemas-sobrepostos","text":"Consigo identificar subestrutura ótima e subproblemas sobrepostos em um problema e explicar por que a recursão ingênua é exponencial (ex.: Fibonacci)."},{"key":"dp-top-down-com-memoizacao","text":"Sei transformar uma recursão em uma solução top-down com memoização (mapa ou array de cache)."},{"key":"dp-bottom-up-com-tabulacao","text":"Sei escrever a versão bottom-up (tabulação) e reduzir o uso de memória quando só preciso da linha ou do valor anterior."},{"key":"dp-problemas-classicos","text":"Já resolvi sozinho pelo menos três problemas clássicos de DP (ex.: troco de moedas, mochila 0/1, maior subsequência comum, subida de escada)."},{"key":"quando-o-greedy-funciona","text":"Sei explicar quando o greedy funciona (escolha gulosa e subestrutura ótima) e dar um contraexemplo em que ele falha (ex.: troco com moedas de 1, 3 e 4)."},{"key":"greedy-problemas-classicos","text":"Já implementei um problema guloso clássico (ex.: agendamento de intervalos, código de Huffman ou Dijkstra) e analisei seu custo."}]},{"track":"web-base","slug":"web-html-semantico","title":"HTML semântico","description":"Estruturar documentos com a tag certa para cada significado: landmarks (header, nav, main, section, article, aside e footer), títulos hierárquicos, listas, links, imagens com texto alternativo e formulários básicos. HTML semântico melhora acessibilidade, SEO e manutenção, e é a base sobre a qual CSS e JavaScript trabalham.","level":"beginner","difficulty":1,"position":0,"prerequisites":[],"resources":[{"name":"MDN — HTML: Linguagem de marcação de hipertexto","url":"https://developer.mozilla.org/pt-BR/docs/Web/HTML"},{"name":"web.dev — Learn HTML","url":"https://web.dev/learn/html"},{"name":"MDN — Referência de elementos HTML","url":"https://developer.mozilla.org/pt-BR/docs/Web/HTML/Reference/Elements"},{"name":"W3C Markup Validation Service","url":"https://validator.w3.org/"}],"checklist":[{"key":"estrutura-basica-do-documento","text":"Sei escrever do zero a estrutura de um documento HTML5 (doctype, html com lang, head com charset e viewport e body)."},{"key":"landmarks-semanticos","text":"Consigo usar header, nav, main, section, article, aside e footer de forma adequada, em vez de div para tudo."},{"key":"hierarquia-de-titulos","text":"Sei montar uma hierarquia de títulos (h1 a h6) coerente, sem pular níveis, e explico por que isso importa para leitores de tela e SEO."},{"key":"imagens-links-e-listas","text":"Sei usar img com alt significativo (e alt vazio em imagens decorativas), links com texto descritivo e listas ul, ol e dl corretamente."},{"key":"formularios-basicos","text":"Consigo criar um formulário básico com label associado a cada campo, tipos de input apropriados e botão de envio."},{"key":"validar-html","text":"Sei validar meu HTML (ex.: com o W3C Validator) e corrigir os erros apontados."}]},{"track":"web-base","slug":"web-css-basico-e-box-model","title":"CSS básico e box model","description":"Estilizar páginas com CSS: seletores, especificidade, cascata e herança, unidades (px, rem, em, %, vw), cores e tipografia, e o box model (content, padding, border e margin, com box-sizing). Entender como o navegador calcula tamanhos e espaçamentos evita a maioria dos bugs de layout.","level":"beginner","difficulty":1,"position":1,"prerequisites":["web-html-semantico"],"resources":[{"name":"MDN — CSS: Cascading Style Sheets","url":"https://developer.mozilla.org/pt-BR/docs/Web/CSS"},{"name":"web.dev — Learn CSS","url":"https://web.dev/learn/css"},{"name":"MDN — Modelo de caixa CSS (box model)","url":"https://developer.mozilla.org/pt-BR/docs/Web/CSS/Guides/Box_model"},{"name":"MDN — Especificidade (Specificity)","url":"https://developer.mozilla.org/en-US/docs/Web/CSS/Guides/Cascade/Specificity"}],"checklist":[{"key":"seletores-e-especificidade","text":"Sei usar seletores de tag, classe, id, atributo e pseudo-classes e calcular qual regra vence pela especificidade."},{"key":"cascata-e-heranca","text":"Consigo explicar a cascata e a herança e dizer quais propriedades são herdadas (ex.: color e font-family sim; margin e border não)."},{"key":"box-model-e-box-sizing","text":"Sei desenhar o box model (content, padding, border e margin), calcular a largura total de um elemento e explicar o efeito de box-sizing: border-box."},{"key":"colapso-de-margens","text":"Entendo o colapso de margens verticais e sei em que situações ele acontece."},{"key":"unidades-e-tipografia","text":"Sei escolher entre px, rem, em, % e vw/vh e configurar tipografia (font-family, tamanho e line-height) de forma escalável."},{"key":"inspecionar-no-devtools","text":"Sei usar o DevTools para inspecionar um elemento, ver o box model calculado e testar mudanças de CSS ao vivo."}]},{"track":"web-base","slug":"web-flexbox-e-grid","title":"Flexbox e Grid","description":"Layouts modernos e responsivos com Flexbox (eixos, justify/align, wrap, grow, shrink e basis) e CSS Grid (tracks, unidade fr, áreas nomeadas, auto-fit com minmax e gap). Veja quando usar cada um, como combiná-los e como adaptá-los a telas diferentes com media queries e abordagem mobile-first.","level":"beginner","difficulty":2,"position":2,"prerequisites":["web-css-basico-e-box-model"],"resources":[{"name":"MDN — Layout flexível (CSS Flexible Box Layout)","url":"https://developer.mozilla.org/pt-BR/docs/Web/CSS/Guides/Flexible_box_layout"},{"name":"MDN — Layout em grade (CSS Grid Layout)","url":"https://developer.mozilla.org/pt-BR/docs/Web/CSS/Guides/Grid_layout"},{"name":"Flexbox Froggy — jogo para praticar Flexbox","url":"https://flexboxfroggy.com/"},{"name":"CSS Grid Garden — jogo para praticar Grid","url":"https://cssgridgarden.com/"}],"checklist":[{"key":"flex-eixos-e-alinhamento","text":"Sei explicar os eixos principal e transversal do Flexbox e usar justify-content, align-items e gap para alinhar itens."},{"key":"flex-grow-shrink-basis","text":"Consigo controlar o tamanho dos itens com flex-grow, flex-shrink e flex-basis (e com a abreviação flex)."},{"key":"grid-tracks-e-areas","text":"Sei criar um grid com grid-template-columns e grid-template-rows, unidade fr, gap e grid-template-areas."},{"key":"grid-responsivo-sem-media-query","text":"Consigo montar uma galeria responsiva com repeat(auto-fit, minmax(...)) sem usar media queries."},{"key":"flex-ou-grid","text":"Sei decidir entre Flexbox (uma dimensão) e Grid (duas dimensões) e combinar os dois (ex.: grid para o layout da página e flex dentro dos componentes)."},{"key":"layout-mobile-first","text":"Já construí um layout completo (header, menu lateral, conteúdo e footer) responsivo, partindo do mobile e adicionando media queries."}]},{"track":"web-base","slug":"web-javascript-essencial","title":"JavaScript essencial","description":"A linguagem da web: tipos e coerção, variáveis (let e const), funções e arrow functions, objetos e arrays, desestruturação, spread e rest, template strings, escopo e closures, this, classes e tratamento de erros. Foco em ES2015+ e nos comportamentos que mais causam bugs em quem está começando.","level":"beginner","difficulty":2,"position":3,"prerequisites":["fund-condicionais-e-lacos","fund-funcoes"],"resources":[{"name":"MDN — Guia JavaScript","url":"https://developer.mozilla.org/pt-BR/docs/Web/JavaScript/Guide"},{"name":"javascript.info — The Modern JavaScript Tutorial","url":"https://javascript.info/"},{"name":"Livro: Eloquent JavaScript — Marijn Haverbeke (gratuito online)","url":"https://eloquentjavascript.net/"},{"name":"Livro: You Don't Know JS Yet — Kyle Simpson","url":"https://github.com/getify/You-Dont-Know-JS"}],"checklist":[{"key":"tipos-let-const-e-igualdade","text":"Sei usar let e const (e por que evito var), os tipos primitivos, a diferença entre == e === e quais valores são truthy ou falsy."},{"key":"objetos-arrays-e-desestruturacao","text":"Sei manipular objetos e arrays com desestruturação, spread e rest e com métodos como map, filter, reduce, find, some e every."},{"key":"arrow-functions-e-this","text":"Sei a diferença entre function e arrow function quanto ao this e explico o que acontece ao passar um método como callback."},{"key":"escopo-e-closures","text":"Consigo explicar escopo léxico e closures com um exemplo e o clássico bug de var em laços com setTimeout."},{"key":"classes-e-prototipos","text":"Sei criar classes (campos, métodos, extends e static) e entendo, em alto nível, que por baixo existe herança por protótipos."},{"key":"tratamento-de-erros","text":"Sei lançar e capturar erros com try/catch/finally e criar erros personalizados."}]},{"track":"web-base","slug":"web-dom-e-eventos","title":"DOM e eventos","description":"Como o JavaScript lê e altera a página: a árvore DOM, seleção de elementos, criação e remoção de nós, atributos e classes, e o modelo de eventos (captura, bubbling, delegação e preventDefault). Também cobre formulários, armazenamento no navegador (localStorage) e cuidados para não prejudicar performance e acessibilidade.","level":"beginner","difficulty":2,"position":4,"prerequisites":["web-html-semantico","web-javascript-essencial"],"resources":[{"name":"MDN — Document Object Model (DOM)","url":"https://developer.mozilla.org/pt-BR/docs/Web/API/Document_Object_Model"},{"name":"MDN — Interface Event (referência de eventos)","url":"https://developer.mozilla.org/pt-BR/docs/Web/API/Event"},{"name":"javascript.info — Browser: Document, Events, Interfaces","url":"https://javascript.info/document"},{"name":"MDN — Web Storage API","url":"https://developer.mozilla.org/pt-BR/docs/Web/API/Web_Storage_API"}],"checklist":[{"key":"selecionar-e-alterar-elementos","text":"Sei selecionar elementos com querySelector e querySelectorAll e alterar texto, atributos, classes (classList) e estilos."},{"key":"criar-e-remover-nos","text":"Sei criar, inserir e remover elementos dinamicamente (createElement, append e remove) e explico por que evitar innerHTML com conteúdo não confiável."},{"key":"eventos-e-listeners","text":"Sei registrar e remover listeners com addEventListener e usar o objeto do evento (target, currentTarget, key e preventDefault)."},{"key":"bubbling-captura-e-delegacao","text":"Consigo explicar bubbling e captura e implementar delegação de eventos em uma lista com itens adicionados dinamicamente."},{"key":"formularios-e-validacao-nativa","text":"Sei tratar o submit de um formulário, ler valores com FormData e usar a validação nativa (required, pattern e setCustomValidity)."},{"key":"mini-projeto-com-dom","text":"Já construí um mini projeto interativo só com DOM e JavaScript puro (ex.: lista de tarefas persistida em localStorage)."}]},{"track":"web-base","slug":"web-assincronismo-promises-async","title":"Assincronismo (Promises/async)","description":"Lidar com operações demoradas sem travar a aplicação: callbacks e o 'callback hell', Promises (estados, then, catch e finally), async/await, tratamento de erros, execução em paralelo (Promise.all, allSettled, race e any), timeouts e cancelamento com AbortController. É a base para consumir APIs e usar qualquer biblioteca moderna.","level":"junior","difficulty":3,"position":5,"prerequisites":["web-javascript-essencial","web-dom-e-eventos"],"resources":[{"name":"MDN — Usando Promises","url":"https://developer.mozilla.org/pt-BR/docs/Web/JavaScript/Guide/Using_promises"},{"name":"MDN — Funções assíncronas (async/await)","url":"https://developer.mozilla.org/pt-BR/docs/Web/JavaScript/Reference/Statements/async_function"},{"name":"javascript.info — Promises, async/await","url":"https://javascript.info/async"},{"name":"MDN — AbortController","url":"https://developer.mozilla.org/en-US/docs/Web/API/AbortController"}],"checklist":[{"key":"callbacks-e-callback-hell","text":"Consigo explicar por que callbacks aninhados são difíceis de manter e refatorar um exemplo para Promises ou async/await."},{"key":"estados-de-uma-promise","text":"Sei descrever os estados de uma Promise (pending, fulfilled e rejected) e criar uma com new Promise (ex.: uma função sleep(ms))."},{"key":"async-await-e-erros","text":"Sei usar async/await com try/catch e entendo que uma função async sempre retorna uma Promise."},{"key":"promise-all-allsettled-race-any","text":"Sei quando usar Promise.all, allSettled, race e any e o que acontece com os resultados quando uma das Promises falha."},{"key":"paralelo-vs-sequencial","text":"Consigo identificar awaits em sequência que poderiam rodar em paralelo e corrigi-los (ex.: await dentro de um for versus Promise.all)."},{"key":"cancelamento-e-timeout","text":"Sei cancelar uma requisição ou impor um timeout usando AbortController e AbortSignal.timeout."}]},{"track":"web-base","slug":"web-fetch-e-http","title":"Fetch e HTTP","description":"Como o navegador conversa com servidores: o ciclo de requisição e resposta, métodos (GET, POST, PUT, PATCH e DELETE), códigos de status, cabeçalhos e corpo em JSON. Pratique a Fetch API para consumir APIs REST, tratar erros de rede e de HTTP e enviar dados de formulário, usando async/await de forma introdutória.","level":"junior","difficulty":2,"position":6,"prerequisites":["web-javascript-essencial","web-dom-e-eventos","fund-terminal-e-shell"],"resources":[{"name":"MDN — Fetch API","url":"https://developer.mozilla.org/pt-BR/docs/Web/API/Fetch_API"},{"name":"MDN — HTTP","url":"https://developer.mozilla.org/pt-BR/docs/Web/HTTP"},{"name":"MDN — Códigos de status de resposta HTTP","url":"https://developer.mozilla.org/pt-BR/docs/Web/HTTP/Reference/Status"},{"name":"JSONPlaceholder — API pública para praticar requisições","url":"https://jsonplaceholder.typicode.com/"}],"checklist":[{"key":"ciclo-requisicao-resposta","text":"Consigo descrever o ciclo de uma requisição HTTP (URL, método, cabeçalhos, corpo e status) e inspecioná-lo na aba Network do DevTools."},{"key":"metodos-e-codigos-de-status","text":"Sei quando usar GET, POST, PUT, PATCH e DELETE e interpretar as famílias de status (2xx, 3xx, 4xx e 5xx) e códigos comuns como 200, 201, 204, 400, 401, 403, 404, 422 e 500."},{"key":"fetch-get-e-post-com-json","text":"Sei fazer GET e POST com fetch, enviando JSON (Content-Type e JSON.stringify) e lendo a resposta com response.json()."},{"key":"erros-de-rede-vs-erros-http","text":"Sei que fetch só rejeita em falhas de rede e que preciso checar response.ok para erros 4xx e 5xx, e trato os dois casos."},{"key":"query-string-e-cabecalhos","text":"Sei montar query strings com URLSearchParams e enviar cabeçalhos como Authorization e Accept."},{"key":"tela-com-estados-de-requisicao","text":"Já construí uma tela que consome uma API pública mostrando os estados de carregando, erro e sucesso."}]},{"track":"web-base","slug":"web-typescript-basico","title":"TypeScript básico","description":"Adicionar tipos estáticos ao JavaScript: anotações e inferência, tipos primitivos, arrays e objetos, interfaces e type aliases, unions e literais, narrowing, funções tipadas e a configuração do tsconfig com strict. Os tipos capturam bugs durante o desenvolvimento e servem como documentação viva do código.","level":"junior","difficulty":3,"position":7,"prerequisites":["web-javascript-essencial"],"resources":[{"name":"TypeScript Handbook","url":"https://www.typescriptlang.org/docs/handbook/intro.html"},{"name":"TypeScript — Everyday Types","url":"https://www.typescriptlang.org/docs/handbook/2/everyday-types.html"},{"name":"TypeScript — Narrowing","url":"https://www.typescriptlang.org/docs/handbook/2/narrowing.html"},{"name":"TypeScript — referência do TSConfig","url":"https://www.typescriptlang.org/tsconfig"}],"checklist":[{"key":"anotar-e-inferir-tipos","text":"Sei anotar variáveis, parâmetros e retornos de função e sei quando posso deixar o TypeScript inferir o tipo."},{"key":"interface-vs-type-alias","text":"Sei criar interfaces e type aliases para objetos e explicar quando usar cada um."},{"key":"unions-literais-e-narrowing","text":"Sei usar union types, tipos literais e narrowing (typeof, in e checagem de igualdade) e escrever uma discriminated union simples."},{"key":"unknown-vs-any","text":"Sei por que evitar any e usar unknown para valores externos (ex.: resposta de uma API), validando antes de usar."},{"key":"strict-e-tsconfig","text":"Sei ativar strict no tsconfig.json e corrigir erros comuns, como valores possivelmente null ou undefined."},{"key":"migrar-js-para-ts","text":"Já converti um pequeno projeto ou módulo de JavaScript para TypeScript sem recorrer a any nem a @ts-ignore."}]},{"track":"web-base","slug":"web-acessibilidade-wcag-aria","title":"Acessibilidade (WCAG, ARIA)","description":"Construir interfaces utilizáveis por todos: os princípios POUR da WCAG (perceptível, operável, compreensível e robusto) e seus níveis A, AA e AAA, navegação por teclado e gerenciamento de foco, contraste e texto alternativo, formulários acessíveis e quando (e quando não) usar ARIA. Inclui testar com leitores de tela e ferramentas automatizadas.","level":"junior","difficulty":3,"position":8,"prerequisites":["web-html-semantico","web-css-basico-e-box-model","web-dom-e-eventos"],"resources":[{"name":"W3C — WCAG 2 Quick Reference","url":"https://www.w3.org/WAI/WCAG22/quickref/"},{"name":"W3C — ARIA Authoring Practices Guide (APG)","url":"https://www.w3.org/WAI/ARIA/apg/"},{"name":"web.dev — Learn Accessibility","url":"https://web.dev/learn/accessibility"},{"name":"MDN — Acessibilidade","url":"https://developer.mozilla.org/pt-BR/docs/Web/Accessibility"}],"checklist":[{"key":"principios-pour-e-niveis","text":"Consigo explicar os quatro princípios da WCAG (perceptível, operável, compreensível e robusto) e a diferença entre os níveis A, AA e AAA."},{"key":"teclado-e-foco","text":"Consigo usar uma página inteira só com o teclado, com foco sempre visível e ordem lógica, e sei por que evitar tabindex com valor positivo."},{"key":"contraste-e-texto-alternativo","text":"Sei verificar o contraste de cores (mínimo de 4,5:1 para texto normal no nível AA) e escrever alt útil para imagens informativas e vazio para decorativas."},{"key":"formularios-acessiveis","text":"Sei tornar um formulário acessível: label associado, mensagens de erro vinculadas ao campo (aria-describedby), agrupamento com fieldset e legend e indicação de campos obrigatórios."},{"key":"aria-quando-usar","text":"Sei a primeira regra do ARIA (usar HTML nativo sempre que possível) e aplicar roles, estados (aria-expanded, aria-live) e aria-label corretamente em um componente como menu ou modal."},{"key":"testar-acessibilidade","text":"Já auditei uma página com Lighthouse ou axe e testei com um leitor de tela (NVDA, VoiceOver ou TalkBack), corrigindo os problemas encontrados."}]},{"track":"web-base","slug":"web-typescript-avancado-generics","title":"TypeScript avançado (generics)","description":"Tipos que se adaptam ao uso: generics com restrições (extends) e valores padrão, keyof e indexed access, mapped e conditional types, infer, template literal types, utility types (Partial, Pick, Omit, Record, ReturnType e Awaited) e type guards personalizados. Foco em escrever APIs tipadas reutilizáveis (hooks, clientes HTTP, stores) e em ler tipos complexos de bibliotecas.","level":"mid","difficulty":4,"position":9,"prerequisites":["web-typescript-basico"],"resources":[{"name":"TypeScript Handbook — Generics","url":"https://www.typescriptlang.org/docs/handbook/2/generics.html"},{"name":"TypeScript Handbook — Creating Types from Types","url":"https://www.typescriptlang.org/docs/handbook/2/types-from-types.html"},{"name":"TypeScript — Utility Types","url":"https://www.typescriptlang.org/docs/handbook/utility-types.html"},{"name":"Livro: Effective TypeScript — Dan Vanderkam"}],"checklist":[{"key":"generics-em-funcoes-e-interfaces","text":"Sei escrever funções, interfaces e classes genéricas (ex.: um tipo Result<T, E> ou um fetchJson<T>) em vez de duplicar código ou usar any."},{"key":"constraints-e-keyof","text":"Sei restringir parâmetros de tipo com extends e usar keyof para escrever uma função segura como getProp<T, K extends keyof T>(obj: T, key: K)."},{"key":"utility-types","text":"Sei usar Partial, Required, Pick, Omit, Record, ReturnType e Awaited e explico o que cada um faz."},{"key":"mapped-e-conditional-types","text":"Consigo escrever um mapped type (ex.: tornar todas as propriedades opcionais ou readonly) e um conditional type simples com infer."},{"key":"discriminated-unions-e-type-guards","text":"Sei modelar estados com discriminated unions, garantir exaustividade com never e escrever type guards (x is T)."},{"key":"ler-tipos-de-bibliotecas","text":"Consigo ler a assinatura de tipos genéricos de bibliotecas (ex.: Promise<T> ou Ref<T> do Vue) e usar as mensagens do compilador para corrigir meu código."}]},{"track":"web-base","slug":"web-http-em-profundidade","title":"HTTP em profundidade (cache, CORS)","description":"O protocolo além do básico: cache HTTP (Cache-Control, ETag, Last-Modified, validação condicional, stale-while-revalidate), CORS (origem, preflight e credenciais), cookies e SameSite, compressão e diferenças entre HTTP/1.1, HTTP/2 e HTTP/3, com HTTPS/TLS em alto nível. Permite diagnosticar erros misteriosos do navegador e projetar APIs mais rápidas.","level":"mid","difficulty":3,"position":10,"prerequisites":["web-fetch-e-http"],"resources":[{"name":"MDN — Cache HTTP","url":"https://developer.mozilla.org/pt-BR/docs/Web/HTTP/Guides/Caching"},{"name":"MDN — Cross-Origin Resource Sharing (CORS)","url":"https://developer.mozilla.org/pt-BR/docs/Web/HTTP/Guides/CORS"},{"name":"web.dev — Prevent unnecessary network requests with the HTTP Cache","url":"https://web.dev/articles/http-cache"},{"name":"RFC 9110 — HTTP Semantics (IETF)","url":"https://datatracker.ietf.org/doc/html/rfc9110"}],"checklist":[{"key":"cache-control-e-diretivas","text":"Sei configurar Cache-Control (max-age, no-cache, no-store, public, private e immutable) e explicar a diferença entre no-cache e no-store."},{"key":"etag-e-requisicoes-condicionais","text":"Consigo explicar como ETag com If-None-Match (e Last-Modified com If-Modified-Since) geram respostas 304 e economizam banda."},{"key":"assets-com-hash-e-cache-longo","text":"Sei por que arquivos com hash no nome (ex.: app.3f9a1c.js) podem ter cache longo enquanto o HTML tem cache curto."},{"key":"cors-e-preflight","text":"Consigo explicar a Same-Origin Policy, quando o navegador faz um preflight (OPTIONS) e quais cabeçalhos Access-Control-* o servidor deve enviar, e diagnosticar um erro de CORS no console."},{"key":"cookies-e-samesite","text":"Sei os atributos de cookie (HttpOnly, Secure, SameSite, Domain, Path e Max-Age) e como interagem com requisições cross-site e com credentials: 'include'."},{"key":"http2-http3-e-tls","text":"Consigo explicar, em alto nível, o que HTTP/2 e HTTP/3 melhoram em relação ao HTTP/1.1 (multiplexação, compressão de cabeçalhos e QUIC) e o que o TLS garante."}]},{"track":"web-base","slug":"web-performance-core-web-vitals","title":"Performance web (Core Web Vitals)","description":"Medir e melhorar a experiência de carregamento e interação: Core Web Vitals (LCP, INP e CLS), caminho crítico de renderização, otimização de imagens e fontes, lazy loading, code splitting, uso de CDN e cache, e medição com Lighthouse, DevTools e dados de campo (RUM). O foco é priorizar o que realmente impacta o usuário, sempre com métricas antes e depois.","level":"mid","difficulty":4,"position":11,"prerequisites":["web-http-em-profundidade","web-dom-e-eventos"],"resources":[{"name":"web.dev — Web Vitals","url":"https://web.dev/articles/vitals"},{"name":"web.dev — Learn Performance","url":"https://web.dev/learn/performance"},{"name":"Chrome DevTools — Performance","url":"https://developer.chrome.com/docs/devtools/performance"},{"name":"PageSpeed Insights","url":"https://pagespeed.web.dev/"}],"checklist":[{"key":"explicar-lcp-inp-cls","text":"Consigo explicar o que LCP, INP e CLS medem, os limiares de 'bom' (LCP até 2,5 s, INP até 200 ms e CLS até 0,1) e o que costuma piorar cada um."},{"key":"medir-com-lighthouse-e-devtools","text":"Sei medir uma página com Lighthouse, PageSpeed Insights e o painel Performance do DevTools e diferenciar dados de laboratório de dados de campo (CrUX/RUM)."},{"key":"otimizar-imagens-e-fontes","text":"Sei otimizar imagens (formatos modernos, srcset e sizes, width e height, loading='lazy') e fontes (font-display, preload e subset)."},{"key":"recursos-bloqueantes-e-code-splitting","text":"Sei identificar recursos que bloqueiam a renderização (CSS e JS no head) e usar defer, async, preload e code splitting para reduzi-los."},{"key":"layout-shift-e-long-tasks","text":"Sei evitar layout shifts (reservando espaço para mídia e anúncios) e quebrar long tasks para melhorar o INP."},{"key":"melhoria-medida-antes-e-depois","text":"Já otimizei uma página real e documentei a melhoria com métricas antes e depois."}]},{"track":"web-base","slug":"web-event-loop-e-modulos","title":"Event loop e módulos","description":"Como o JavaScript executa código: call stack, Web APIs, fila de macrotarefas e de microtarefas (Promises e queueMicrotask), ordem de execução, bloqueio da thread principal e workers. Também cobre o sistema de módulos (ES Modules versus CommonJS), import e export, imports dinâmicos, tree shaking e dependências circulares.","level":"mid","difficulty":4,"position":12,"prerequisites":["web-javascript-essencial","web-assincronismo-promises-async"],"resources":[{"name":"MDN — Modelo de execução do JavaScript (event loop)","url":"https://developer.mozilla.org/pt-BR/docs/Web/JavaScript/Reference/Execution_model"},{"name":"Jake Archibald — Tasks, microtasks, queues and schedules","url":"https://jakearchibald.com/2015/tasks-microtasks-queues-and-schedules/"},{"name":"MDN — Módulos JavaScript","url":"https://developer.mozilla.org/pt-BR/docs/Web/JavaScript/Guide/Modules"},{"name":"Vídeo: What the heck is the event loop anyway? — Philip Roberts (JSConf EU)"}],"checklist":[{"key":"call-stack-e-filas","text":"Consigo explicar o papel da call stack, das Web APIs, da fila de macrotarefas e da fila de microtarefas na execução de um programa JavaScript."},{"key":"prever-ordem-de-execucao","text":"Sei prever a ordem de saída de um código que mistura console.log síncrono, setTimeout com 0, Promise.then e queueMicrotask e explicar o porquê."},{"key":"nao-bloquear-a-thread-principal","text":"Sei identificar o que bloqueia a thread principal (laço pesado, processamento de JSON gigante) e mitigar com divisão em partes, requestIdleCallback ou Web Workers."},{"key":"esm-vs-commonjs","text":"Sei a diferença entre ES Modules (import e export) e CommonJS (require e module.exports) e configurar um projeto para usar ESM (type: module)."},{"key":"import-dinamico-e-tree-shaking","text":"Sei usar import() dinâmico para carregar código sob demanda e explico por que exports nomeados ajudam o tree shaking."},{"key":"dependencia-circular","text":"Já reproduzi uma dependência circular entre módulos e sei reorganizar o código para eliminá-la."}]},{"track":"web-base","slug":"web-pwa-e-service-workers","title":"PWA e Service Workers","description":"Transformar um site em aplicação instalável e resiliente: Web App Manifest, ciclo de vida do Service Worker (install, activate e fetch), estratégias de cache (cache-first, network-first e stale-while-revalidate), funcionamento offline e atualização de versões, além de noções de notificações push e background sync (com suporte desigual entre navegadores). Inclui os riscos: cache obsoleto, escopo e HTTPS obrigatório.","level":"senior","difficulty":4,"position":13,"prerequisites":["web-http-em-profundidade","web-event-loop-e-modulos","web-performance-core-web-vitals"],"resources":[{"name":"web.dev — Learn PWA","url":"https://web.dev/learn/pwa"},{"name":"MDN — Service Worker API","url":"https://developer.mozilla.org/pt-BR/docs/Web/API/Service_Worker_API"},{"name":"Workbox — Chrome for Developers","url":"https://developer.chrome.com/docs/workbox"},{"name":"vite-plugin-pwa — documentação oficial","url":"https://vite-pwa-org.netlify.app/"}],"checklist":[{"key":"manifest-e-instalabilidade","text":"Sei criar um Web App Manifest (name, icons, start_url, display e theme_color) e explicar os critérios para o app ser instalável."},{"key":"ciclo-de-vida-do-service-worker","text":"Consigo explicar o ciclo de vida do Service Worker (register, install, waiting e activate) e por que uma nova versão fica esperando até as abas antigas fecharem ou skipWaiting ser chamado."},{"key":"estrategias-de-cache","text":"Sei implementar e comparar as estratégias cache-first, network-first e stale-while-revalidate com a Cache API (ou Workbox), escolhendo a certa para HTML, API e assets."},{"key":"offline-e-fallback","text":"Já fiz uma página funcionar offline, com uma tela de fallback quando o recurso não está em cache."},{"key":"atualizacao-e-limpeza-de-caches","text":"Sei lançar uma nova versão do app limpando os caches antigos e avisando o usuário de que há uma atualização disponível."},{"key":"depurar-e-escopo-do-service-worker","text":"Sei depurar Service Workers na aba Application do DevTools e entendo escopo, a exigência de HTTPS (exceto em localhost) e os riscos de um SW com bug ou cache obsoleto."}]},{"track":"frontend-vue","slug":"vue-3-e-sfc","title":"Vue 3 e SFC","description":"Primeiro contato com o Vue 3: o que significa ser um framework progressivo, como criar um projeto com o `create-vue` e como um Single-File Component (`.vue`) é organizado em `<script setup>`, `<template>` e `<style scoped>`. Escopo: `createApp` e o componente raiz, Vue DevTools e a diferença entre Options API e Composition API.","level":"beginner","difficulty":2,"position":0,"prerequisites":["web-html-semantico","web-javascript-essencial"],"resources":[{"name":"Vue.js — Guia: Introdução","url":"https://vuejs.org/guide/introduction.html"},{"name":"Vue.js — Guia: Quick Start","url":"https://vuejs.org/guide/quick-start.html"},{"name":"Vue.js — Guia: Single-File Components","url":"https://vuejs.org/guide/scaling-up/sfc.html"},{"name":"Vue.js — Tutorial interativo","url":"https://vuejs.org/tutorial/"}],"checklist":[{"key":"criar-projeto-create-vue","text":"Já criei um projeto com `npm create vue@latest` e rodei o servidor de desenvolvimento com `npm run dev`."},{"key":"anatomia-sfc","text":"Consigo descrever o papel de cada bloco de um arquivo `.vue` (`<script setup>`, `<template>` e `<style scoped>`) e o que `scoped` faz com o CSS."},{"key":"createapp-mount","text":"Entendo o que `createApp(App).mount('#app')` faz no `main.ts` e como o componente raiz é montado no DOM."},{"key":"framework-progressivo","text":"Sei explicar o que significa o Vue ser um framework progressivo e quando usá-lo em uma página isolada versus como SPA completa."},{"key":"options-vs-composition","text":"Reconheço a diferença entre Options API e Composition API e sei por que este roadmap adota `<script setup>`."},{"key":"vue-devtools","text":"Sei usar o Vue DevTools para inspecionar a árvore de componentes e o estado reativo de cada um."}]},{"track":"frontend-vue","slug":"vue-template-e-reatividade","title":"Template e reatividade","description":"A sintaxe de template do Vue (interpolação, `v-bind`, `v-on`, `v-if`, `v-for`, `v-model`) e o modelo de reatividade que mantém o DOM sincronizado com o estado. Escopo: renderização condicional e de listas com `:key`, bindings de `class` e `style`, tratamento de eventos e a atualização assíncrona do DOM (`nextTick`).","level":"beginner","difficulty":2,"position":1,"prerequisites":["vue-3-e-sfc","web-dom-e-eventos"],"resources":[{"name":"Vue.js — Guia: Sintaxe de template","url":"https://vuejs.org/guide/essentials/template-syntax.html"},{"name":"Vue.js — Guia: Fundamentos de reatividade","url":"https://vuejs.org/guide/essentials/reactivity-fundamentals.html"},{"name":"Vue.js — Guia: Renderização de listas","url":"https://vuejs.org/guide/essentials/list.html"},{"name":"Vue.js — Guia: Tratamento de eventos","url":"https://vuejs.org/guide/essentials/event-handling.html"}],"checklist":[{"key":"interpolar-e-bindar","text":"Consigo exibir dados com `{{ }}`, ligar atributos com `v-bind` (`:href`, `:class`, `:style`) e tratar eventos com `v-on` (`@click`, `.prevent`)."},{"key":"condicional-v-if-v-show","text":"Sei quando usar `v-if`/`v-else-if`/`v-else` e quando usar `v-show`, e o custo de cada um."},{"key":"v-for-com-key","text":"Renderizo listas com `v-for` e uma `:key` estável (um id, não o índice) e sei explicar por que a key importa."},{"key":"v-model-basico","text":"Uso `v-model` em `<input>`, `<select>` e checkbox para criar ligação de duas vias com o estado."},{"key":"ref-e-value","text":"Entendo que um `ref` guarda o valor em `.value` no script e é desembrulhado automaticamente no template."},{"key":"atualizacao-assincrona","text":"Sei que o DOM é atualizado de forma assíncrona e uso `nextTick()` quando preciso ler o DOM depois de mudar o estado."}]},{"track":"frontend-vue","slug":"vue-props-e-emits","title":"Props e emits","description":"Como componentes pai e filho se comunicam: dados descem por props e eventos sobem por emits, mantendo o fluxo de dados unidirecional. Escopo: `defineProps` e `defineEmits` com tipos, valores padrão e validação, `v-model` em componentes com `defineModel` e herança de atributos (`$attrs`).","level":"junior","difficulty":2,"position":2,"prerequisites":["vue-template-e-reatividade"],"resources":[{"name":"Vue.js — Guia: Props","url":"https://vuejs.org/guide/components/props.html"},{"name":"Vue.js — Guia: Eventos de componente","url":"https://vuejs.org/guide/components/events.html"},{"name":"Vue.js — Guia: v-model em componentes","url":"https://vuejs.org/guide/components/v-model.html"},{"name":"Vue.js — Guia: Atributos herdados (fallthrough)","url":"https://vuejs.org/guide/components/attrs.html"}],"checklist":[{"key":"declarar-props","text":"Consigo declarar props com `defineProps` (tipos, `required` e valores padrão) e passá-las no template do pai."},{"key":"fluxo-unidirecional","text":"Sei explicar por que não devo alterar uma prop dentro do filho e como o fluxo de dados unidirecional guia o design dos componentes."},{"key":"emitir-eventos","text":"Já declarei eventos com `defineEmits` e os emiti (`emit('save', payload)`), escutando-os no pai com `@save`."},{"key":"v-model-componente","text":"Consigo implementar `v-model` em um componente próprio com `defineModel()`, inclusive com nome (`v-model:title`)."},{"key":"attrs-fallthrough","text":"Entendo como atributos não declarados (`class`, `id`, listeners) caem no elemento raiz e quando usar `defineOptions({ inheritAttrs: false })` com `$attrs`."},{"key":"props-destructure","text":"Sei que, desde o Vue 3.5, desestruturar `defineProps` mantém a reatividade (inclusive com valores padrão) e que, ao passar o valor a um `watch`, preciso usar um getter."}]},{"track":"frontend-vue","slug":"vue-composition-api-script-setup","title":"Composition API e <script setup>","description":"A Composition API organiza a lógica por funcionalidade (em vez de `data`/`methods`/`computed` separados) e o `<script setup>` é a sintaxe recomendada para usá-la em SFCs. Escopo: `ref` versus `reactive`, `toRef`/`toRefs`, hooks de ciclo de vida, template refs com `useTemplateRef` e os macros do compilador (`defineProps`, `defineEmits`, `defineExpose`).","level":"junior","difficulty":3,"position":3,"prerequisites":["vue-template-e-reatividade","vue-props-e-emits"],"resources":[{"name":"Vue.js — Guia: Composition API FAQ","url":"https://vuejs.org/guide/extras/composition-api-faq.html"},{"name":"Vue.js — API: SFC script setup","url":"https://vuejs.org/api/sfc-script-setup.html"},{"name":"Vue.js — Guia: Ciclo de vida","url":"https://vuejs.org/guide/essentials/lifecycle.html"},{"name":"Vue.js — Guia: Template refs","url":"https://vuejs.org/guide/essentials/template-refs.html"}],"checklist":[{"key":"ref-vs-reactive","text":"Consigo explicar a diferença entre `ref` e `reactive` (incluindo a perda de reatividade ao desestruturar um `reactive`) e quando usar cada um."},{"key":"script-setup-macros","text":"Sei usar os macros `defineProps`, `defineEmits`, `defineExpose` e `defineOptions`, e que não precisam ser importados."},{"key":"toref-torefs","text":"Extraio propriedades de um objeto reativo com `toRef`/`toRefs` sem perder a reatividade."},{"key":"ciclo-de-vida","text":"Já usei `onMounted`, `onUpdated` e `onBeforeUnmount` e limpo efeitos colaterais (timers, listeners) ao desmontar o componente."},{"key":"template-refs","text":"Acesso um elemento do DOM ou uma instância de componente com `useTemplateRef()` (Vue 3.5+) ou com um `ref` ligado no template."},{"key":"bindings-top-level","text":"Entendo que tudo o que é declarado no topo do `<script setup>` fica disponível no template e que esse código roda uma vez por instância do componente."}]},{"track":"frontend-vue","slug":"vue-computed-e-watch","title":"Computed e watch","description":"Estado derivado e reações a mudanças: `computed` calcula valores com cache a partir de dependências reativas, enquanto `watch` e `watchEffect` executam efeitos colaterais (requisições, persistência, sincronização) quando o estado muda. Escopo: computed gravável, `immediate`/`deep`/`flush`, limpeza de efeitos e como evitar watchers desnecessários.","level":"junior","difficulty":3,"position":4,"prerequisites":["vue-composition-api-script-setup"],"resources":[{"name":"Vue.js — Guia: Computed properties","url":"https://vuejs.org/guide/essentials/computed.html"},{"name":"Vue.js — Guia: Watchers","url":"https://vuejs.org/guide/essentials/watchers.html"},{"name":"Vue.js — Guia: Reatividade em profundidade","url":"https://vuejs.org/guide/extras/reactivity-in-depth.html"}],"checklist":[{"key":"computed-cache","text":"Consigo explicar por que `computed` é preferível a um método para valores derivados (cache por dependências) e por que o seu getter deve ser puro."},{"key":"computed-gravavel","text":"Já criei um `computed` gravável com `get` e `set` (por exemplo, para adaptar um `v-model`)."},{"key":"watch-vs-watcheffect","text":"Sei escolher entre `watch` (fonte explícita, valor novo e antigo) e `watchEffect` (dependências rastreadas automaticamente)."},{"key":"watch-opcoes","text":"Entendo as opções `immediate`, `deep`, `once` e `flush: 'post'` e quando cada uma é necessária."},{"key":"cleanup-requisicao","text":"Cancelo uma requisição obsoleta dentro de um watcher usando `onWatcherCleanup()` (3.5+) ou o `onCleanup` do callback, evitando condições de corrida."},{"key":"evitar-watch-desnecessario","text":"Prefiro `computed` ou eventos explícitos a um `watch` que apenas copia estado derivado de um ref para outro."}]},{"track":"frontend-vue","slug":"vue-router","title":"Vue Router","description":"Roteamento do lado do cliente com o Vue Router 4: mapear URLs para componentes, navegar sem recarregar a página e controlar o acesso às rotas. Escopo: rotas dinâmicas e aninhadas, `useRoute`/`useRouter`, navigation guards e `meta`, lazy loading de rotas e history mode (com o fallback do servidor).","level":"junior","difficulty":3,"position":5,"prerequisites":["vue-props-e-emits","vue-composition-api-script-setup"],"resources":[{"name":"Vue Router — Documentação","url":"https://router.vuejs.org/"},{"name":"Vue Router — Rotas dinâmicas","url":"https://router.vuejs.org/guide/essentials/dynamic-matching.html"},{"name":"Vue Router — Navigation guards","url":"https://router.vuejs.org/guide/advanced/navigation-guards.html"},{"name":"Vue Router — Lazy loading de rotas","url":"https://router.vuejs.org/guide/advanced/lazy-loading.html"}],"checklist":[{"key":"configurar-router","text":"Consigo configurar `createRouter` com `createWebHistory` e uma lista de rotas, e renderizar com `<RouterView>` e `<RouterLink>`."},{"key":"rotas-dinamicas","text":"Crio rotas dinâmicas (`/topicos/:slug`), leio os params com `useRoute()` e os recebo como props com `props: true`."},{"key":"rotas-aninhadas","text":"Implemento rotas aninhadas e layouts com `children` e um `<RouterView>` interno."},{"key":"navegacao-programatica","text":"Navego por código com `router.push`/`router.replace` usando rotas nomeadas, e sei ler e atualizar a query string."},{"key":"guards-e-meta","text":"Protejo rotas com `router.beforeEach` e `meta` (ex.: `requiresAuth`) e redireciono corretamente, sem criar loops."},{"key":"lazy-e-fallback","text":"Faço lazy loading de rotas com `() => import()` e configuro o fallback para `index.html` no servidor ao usar `createWebHistory`."}]},{"track":"frontend-vue","slug":"vue-pinia","title":"Pinia","description":"Pinia é a biblioteca oficial de gerenciamento de estado global do Vue: stores tipadas, integradas ao DevTools e compatíveis com SSR. Escopo: stores no estilo setup e options, `state`/`getters`/`actions`, `storeToRefs`, composição entre stores, plugins e quando não usar estado global.","level":"junior","difficulty":3,"position":6,"prerequisites":["vue-composition-api-script-setup","vue-computed-e-watch"],"resources":[{"name":"Pinia — Documentação","url":"https://pinia.vuejs.org/"},{"name":"Pinia — Core concepts","url":"https://pinia.vuejs.org/core-concepts/"},{"name":"Pinia — Plugins","url":"https://pinia.vuejs.org/core-concepts/plugins.html"},{"name":"Vue.js — Guia: State management","url":"https://vuejs.org/guide/scaling-up/state-management.html"}],"checklist":[{"key":"definir-store-setup","text":"Consigo criar uma store com `defineStore` no estilo setup (usando `ref`, `computed` e funções) e no estilo options."},{"key":"storetorefs","text":"Uso `storeToRefs` para desestruturar state e getters sem perder a reatividade (e sei que as actions podem ser desestruturadas diretamente)."},{"key":"actions-assincronas","text":"Implemento actions assíncronas que chamam uma API e controlam os estados de `loading` e `error`."},{"key":"stores-compostas","text":"Consigo usar uma store dentro de outra evitando dependências circulares."},{"key":"quando-usar-pinia","text":"Sei decidir entre estado local, composable com estado compartilhado e Pinia."},{"key":"devtools-plugins","text":"Inspeciono stores no Vue DevTools e sei escrever (ou usar) um plugin do Pinia, como persistência em `localStorage`."}]},{"track":"frontend-vue","slug":"vue-vite-e-build","title":"Vite e build","description":"O Vite é o servidor de desenvolvimento (módulos ES nativos e HMR) e a ferramenta de build usada pelo ecossistema Vue. Escopo: `vite.config.ts` e plugins (`@vitejs/plugin-vue`), alias `@`, proxy de API, variáveis de ambiente (`import.meta.env`, prefixo `VITE_`), build de produção com `vite build` e análise do tamanho do bundle.","level":"junior","difficulty":2,"position":7,"prerequisites":["vue-3-e-sfc","fund-terminal-e-shell"],"resources":[{"name":"Vite — Guia","url":"https://vite.dev/guide/"},{"name":"Vite — Build para produção","url":"https://vite.dev/guide/build.html"},{"name":"Vite — Variáveis de ambiente e modos","url":"https://vite.dev/guide/env-and-mode.html"},{"name":"Vite — Configuração","url":"https://vite.dev/config/"}],"checklist":[{"key":"por-que-vite-e-rapido","text":"Consigo explicar por que o Vite é rápido em desenvolvimento (módulos ES nativos, pré-bundling de dependências e HMR) e o que muda no build de produção."},{"key":"config-basica","text":"Sei configurar o `vite.config.ts` com `@vitejs/plugin-vue`, alias `@` apontando para `src` e `server.proxy` para a API."},{"key":"variaveis-ambiente","text":"Entendo `import.meta.env`, o prefixo `VITE_` e os arquivos `.env`/`.env.production`, e sei que nada embutido no bundle é secreto."},{"key":"build-e-preview","text":"Gerei o build com `vite build`, testei com `vite preview` e sei o que há em `dist/` (assets com hash no nome)."},{"key":"analisar-bundle","text":"Consigo analisar o tamanho do bundle (por exemplo, com `rollup-plugin-visualizer`) e identificar dependências pesadas."},{"key":"base-e-deploy","text":"Configuro a opção `base` e publico o build estático em um servidor ou CDN."}]},{"track":"frontend-vue","slug":"vue-composables","title":"Composables","description":"Composables são funções que encapsulam e reutilizam lógica com estado usando a Composition API (convenção `useXxx`), substituindo os mixins. Escopo: extrair lógica de componentes, aceitar argumentos reativos com `toValue`, limpar efeitos no ciclo de vida, compartilhar estado entre componentes e conhecer o VueUse.","level":"junior","difficulty":3,"position":8,"prerequisites":["vue-composition-api-script-setup","vue-computed-e-watch","web-assincronismo-promises-async"],"resources":[{"name":"Vue.js — Guia: Composables","url":"https://vuejs.org/guide/reusability/composables.html"},{"name":"VueUse — Coleção de composables","url":"https://vueuse.org/"},{"name":"Vue.js — API: Reactivity utilities (toValue, toRef)","url":"https://vuejs.org/api/reactivity-utilities.html"}],"checklist":[{"key":"extrair-composable","text":"Já extraí a lógica de um componente para um composable `useXxx` que devolve refs e funções."},{"key":"argumentos-reativos","text":"Sei aceitar argumentos que podem ser valor, `ref` ou getter usando `toValue()` e reagir às mudanças com `watchEffect`."},{"key":"limpeza-de-efeitos","text":"Registro e limpo efeitos (listeners, timers, `AbortController`) com `onMounted`/`onUnmounted` ou `onScopeDispose` dentro de um composable."},{"key":"estado-compartilhado","text":"Entendo a diferença entre estado criado a cada chamada (local) e estado em escopo de módulo (compartilhado), e os riscos do segundo em SSR."},{"key":"composable-assincrono","text":"Escrevi um composable assíncrono (como um `useFetch` próprio) que expõe `data`, `error` e `isLoading`."},{"key":"usar-vueuse","text":"Conheço o VueUse (ex.: `useLocalStorage`, `useDebounceFn`, `useEventListener`) e sei quando usá-lo em vez de reescrever a lógica."}]},{"track":"frontend-vue","slug":"vue-formularios-e-validacao","title":"Formulários e validação","description":"Formulários reativos com `v-model` e validação no cliente com feedback acessível, integrados aos erros devolvidos pela API. Escopo: modificadores de `v-model`, validação com `computed` ou com schemas (Zod/Valibot) via VeeValidate, estados `touched`/`dirty`/`submitting`, componentes de campo reutilizáveis e acessibilidade (`label`, `aria-invalid`, `aria-describedby`).","level":"junior","difficulty":3,"position":9,"prerequisites":["vue-props-e-emits","vue-computed-e-watch","web-dom-e-eventos"],"resources":[{"name":"Vue.js — Guia: Form input bindings","url":"https://vuejs.org/guide/essentials/forms.html"},{"name":"VeeValidate — Documentação","url":"https://vee-validate.logaretm.com/v4/"},{"name":"Zod — Documentação","url":"https://zod.dev/"},{"name":"web.dev — Learn Forms","url":"https://web.dev/learn/forms"}],"checklist":[{"key":"v-model-campos","text":"Ligo `v-model` a `text`, `checkbox` (booleano e array), `radio`, `select` e `textarea`, usando `.lazy`, `.number` e `.trim` quando fizer sentido."},{"key":"validacao-cliente","text":"Valido campos obrigatórios, formato e regras entre campos com `computed` ou com um schema (Zod/Valibot) integrado ao VeeValidate."},{"key":"estados-do-campo","text":"Controlo `touched`, `dirty` e `submitting` para mostrar erros no momento certo e impedir o envio duplicado."},{"key":"erros-422-da-api","text":"Exibo os erros de validação do servidor (resposta 422 com `errors` por campo) junto aos campos correspondentes."},{"key":"acessibilidade-formulario","text":"Aplico `<label for>` (com ids estáveis gerados por `useId()`), `aria-invalid`, `aria-describedby` e foco no primeiro campo inválido para tornar o formulário acessível."},{"key":"campo-reutilizavel","text":"Criei um componente de campo reutilizável (como `BaseInput`) com `defineModel`, rótulo e mensagem de erro."}]},{"track":"frontend-vue","slug":"vue-slots-e-provide-inject","title":"Slots e provide/inject","description":"Padrões de composição de componentes: slots (padrão, nomeados e com escopo) para delegar parte da renderização ao pai, e `provide`/`inject` para compartilhar contexto em uma árvore sem prop drilling. Escopo: componentes headless/renderless, componentes compostos (Tabs, Accordion), `InjectionKey` tipado e critérios para escolher entre props, slots, composables e Pinia.","level":"mid","difficulty":4,"position":10,"prerequisites":["vue-props-e-emits","vue-composition-api-script-setup"],"resources":[{"name":"Vue.js — Guia: Slots","url":"https://vuejs.org/guide/components/slots.html"},{"name":"Vue.js — Guia: Provide / inject","url":"https://vuejs.org/guide/components/provide-inject.html"},{"name":"Reka UI — Componentes headless para Vue","url":"https://reka-ui.com/"}],"checklist":[{"key":"slots-nomeados-fallback","text":"Crio componentes com slot padrão, slots nomeados (`#header`) e conteúdo de fallback dentro de `<slot>`."},{"key":"scoped-slots","text":"Exponho dados do filho para o pai com slots com escopo (props no `<slot>` e `#default` desestruturado no pai)."},{"key":"componente-composto","text":"Implementei um componente composto (como `Tabs`/`TabPanel` ou `Accordion`) em que os filhos compartilham estado do pai via `provide`/`inject`."},{"key":"injection-key-tipada","text":"Sei tipar `provide`/`inject` com `InjectionKey` e tratar o valor ausente (valor padrão ou erro explícito)."},{"key":"reatividade-no-provide","text":"Entendo que valores providos devem ser `ref`/`reactive` (ou getters) para manter a reatividade, e mantenho as mutações no provedor, expondo funções."},{"key":"escolher-estrategia","text":"Consigo decidir entre props, slots, `provide`/`inject`, composables e Pinia para compartilhar dados e comportamento em uma árvore profunda de componentes."}]},{"track":"frontend-vue","slug":"vue-testes-vitest-test-utils","title":"Testes com Vitest + Test Utils","description":"Testes automatizados de componentes e lógica Vue com o Vitest (runner integrado ao Vite) e o Vue Test Utils. Escopo: `mount`/`shallowMount`, props, eventos emitidos, interações assíncronas (`trigger`, `flushPromises`), mocks de API, testes com Pinia (`createTestingPinia`) e Router, e testes de composables, priorizando o comportamento observável pelo usuário.","level":"mid","difficulty":3,"position":11,"prerequisites":["vue-vite-e-build","vue-props-e-emits","vue-pinia","qual-testes-unitarios"],"resources":[{"name":"Vitest — Documentação","url":"https://vitest.dev/"},{"name":"Vue Test Utils — Documentação","url":"https://test-utils.vuejs.org/"},{"name":"Vue.js — Guia: Testing","url":"https://vuejs.org/guide/scaling-up/testing.html"},{"name":"Pinia — Testing","url":"https://pinia.vuejs.org/cookbook/testing.html"}],"checklist":[{"key":"configurar-vitest","text":"Sei configurar o Vitest em um projeto Vite (`environment: 'jsdom'` ou `happy-dom`, alias e arquivos de setup) e rodá-lo em modo watch e com cobertura."},{"key":"montar-componente","text":"Monto um componente com `mount` passando `props`, `slots` e `global.plugins`, e faço asserções no DOM renderizado."},{"key":"eventos-e-async","text":"Testo interações com `await wrapper.trigger('click')`, verifico `wrapper.emitted()` e aguardo efeitos assíncronos com `flushPromises`."},{"key":"mock-de-api","text":"Mocko chamadas HTTP (`vi.mock`, `vi.fn` ou MSW) para cobrir os estados de loading, sucesso e erro."},{"key":"pinia-e-router","text":"Testo componentes que usam Pinia (`createTestingPinia`) e Vue Router (router de teste ou `RouterLinkStub`)."},{"key":"comportamento-e-composables","text":"Prefiro testar o comportamento visível ao usuário a detalhes de implementação e sei testar um composable isoladamente."}]},{"track":"frontend-vue","slug":"vue-tailwind-e-design-system","title":"Tailwind e design system","description":"Estilização utility-first com Tailwind CSS integrada ao Vite e como evoluí-la para um design system consistente. Escopo: tokens de design com `@theme`, layouts responsivos e tema escuro com `dark:`, componentes base com variantes (CVA + `tailwind-merge`), acessibilidade visual e documentação de componentes.","level":"mid","difficulty":3,"position":12,"prerequisites":["vue-vite-e-build","vue-props-e-emits","web-flexbox-e-grid"],"resources":[{"name":"Tailwind CSS — Instalação com Vite","url":"https://tailwindcss.com/docs/installation/using-vite"},{"name":"Tailwind CSS — Theme variables","url":"https://tailwindcss.com/docs/theme"},{"name":"Atomic Design — Brad Frost","url":"https://atomicdesign.bradfrost.com/"},{"name":"Livro: Refactoring UI — Adam Wathan e Steve Schoger","url":"https://refactoringui.com/"}],"checklist":[{"key":"instalar-tailwind-vite","text":"Consigo instalar e configurar o Tailwind em um projeto Vue com Vite (plugin `@tailwindcss/vite` e `@import 'tailwindcss'` no CSS)."},{"key":"responsivo-e-dark","text":"Construo layouts responsivos mobile-first (`sm:`, `md:`, `lg:`) e implemento tema claro/escuro com `dark:`."},{"key":"tokens-com-theme","text":"Defino tokens de design (cores, fontes, espaçamentos) com `@theme` em vez de valores soltos nas classes."},{"key":"variantes-cva","text":"Criei um componente base (como `BaseButton`) com variantes e tamanhos usando CVA e `tailwind-merge` para mesclar classes sem conflito."},{"key":"extrair-componentes","text":"Sei quando extrair um componente Vue (em vez de abusar de `@apply`) para evitar repetição de classes utilitárias."},{"key":"acessibilidade-visual","text":"Garanto foco visível (`focus-visible:`), contraste adequado e áreas de toque suficientes nos componentes."}]},{"track":"frontend-vue","slug":"vue-typescript","title":"TypeScript com Vue","description":"TypeScript em projetos Vue 3 para tipar props, emits, slots, stores e composables, com checagem estática via `vue-tsc`. Escopo: `<script setup lang=\"ts\">`, `defineProps<T>()` e `defineEmits<T>()`, `ref<T>()`, `InjectionKey`, componentes genéricos (`generic`) e tipagem de Pinia e Vue Router.","level":"mid","difficulty":4,"position":13,"prerequisites":["vue-composables","vue-slots-e-provide-inject","web-typescript-basico"],"resources":[{"name":"Vue.js — Guia: TypeScript com Vue","url":"https://vuejs.org/guide/typescript/overview.html"},{"name":"Vue.js — Guia: TypeScript com Composition API","url":"https://vuejs.org/guide/typescript/composition-api.html"},{"name":"TypeScript — Documentação","url":"https://www.typescriptlang.org/docs/"},{"name":"Vue Language Tools (Volar e vue-tsc)","url":"https://github.com/vuejs/language-tools"}],"checklist":[{"key":"props-emits-tipados","text":"Tipo props e eventos com `defineProps<T>()` e `defineEmits<T>()` (sintaxe baseada em tipos) em um componente `<script setup lang=\"ts\">`."},{"key":"tipar-refs-e-computed","text":"Tipo `ref<T>()`, `computed<T>()` e template refs (`useTemplateRef<HTMLInputElement>('input')`) sem recorrer a `any`."},{"key":"injection-key-e-slots","text":"Tipo `provide`/`inject` com `InjectionKey<T>` e slots com `defineSlots`."},{"key":"componentes-genericos","text":"Crio um componente genérico (`<script setup lang=\"ts\" generic=\"T\">`) para listas ou selects reutilizáveis."},{"key":"vue-tsc-no-ci","text":"Rodo o `vue-tsc` (por exemplo, no script `type-check`) localmente e no CI, mantendo `strict` habilitado no `tsconfig`."},{"key":"tipar-ecossistema","text":"Tipo respostas de API (com schema ou interfaces), stores do Pinia e `meta` de rotas do Vue Router para que o editor autocomplete e acuse erros."}]},{"track":"frontend-vue","slug":"vue-performance","title":"Performance (lazy, virtual list)","description":"Otimização de apps Vue no carregamento e na renderização, sempre medindo antes de otimizar. Escopo: code splitting (rotas lazy e `defineAsyncComponent`), virtualização de listas longas, `shallowRef`/`v-memo`/`v-once`, estabilidade de props, `KeepAlive` e análise com Vue DevTools e Lighthouse (Core Web Vitals).","level":"senior","difficulty":4,"position":14,"prerequisites":["vue-computed-e-watch","vue-router","vue-vite-e-build","web-performance-core-web-vitals"],"resources":[{"name":"Vue.js — Guia: Performance","url":"https://vuejs.org/guide/best-practices/performance.html"},{"name":"Vue.js — Guia: Async components","url":"https://vuejs.org/guide/components/async.html"},{"name":"web.dev — Core Web Vitals","url":"https://web.dev/articles/vitals"},{"name":"TanStack Virtual — Documentação","url":"https://tanstack.com/virtual/latest"}],"checklist":[{"key":"medir-antes","text":"Meço antes de otimizar, usando a aba de performance do Vue DevTools/Chrome e o Lighthouse para achar o gargalo real e acompanhar LCP, INP e CLS."},{"key":"code-splitting","text":"Apliquei code splitting com rotas lazy (`() => import()`) e `defineAsyncComponent`, e confirmei a divisão de chunks no build."},{"key":"lista-virtual","text":"Renderizo uma lista com milhares de itens usando virtualização (por exemplo, TanStack Virtual ou `vue-virtual-scroller`) e sei explicar por que ela reduz o custo do DOM."},{"key":"reatividade-superficial","text":"Sei quando usar `shallowRef`/`shallowReactive`, `markRaw`, `v-memo`/`v-once` e `KeepAlive` para reduzir o custo de reatividade e de remontagem."},{"key":"props-estaveis","text":"Entendo como props instáveis (objetos e funções recriados a cada render) e `computed` que devolvem novos objetos causam re-renderizações desnecessárias."},{"key":"bundle-e-assets","text":"Reduzo o bundle (imports por módulo, tree-shaking, remoção de dependências pesadas) e otimizo imagens e fontes (`loading=\"lazy\"`, formatos modernos)."}]},{"track":"frontend-vue","slug":"vue-ssr-nuxt-e-arquitetura","title":"SSR/Nuxt e arquitetura de front","description":"Renderização no servidor (SSR), geração estática (SSG) e hidratação para melhorar SEO e métricas de carregamento, com o Nuxt como framework full-stack para Vue. Escopo: modos de renderização por rota, `useFetch`/`useAsyncData`, rotas de servidor (Nitro), armadilhas de estado e hidratação (incluindo a hidratação lazy do Vue 3.5), e como estruturar um front-end grande (módulos por feature, camada de API, fronteiras entre UI, estado e domínio).","level":"senior","difficulty":5,"position":15,"prerequisites":["vue-router","vue-pinia","vue-performance"],"resources":[{"name":"Vue.js — Guia: Server-Side Rendering (SSR)","url":"https://vuejs.org/guide/scaling-up/ssr.html"},{"name":"Nuxt — Documentação","url":"https://nuxt.com/docs"},{"name":"Nuxt — Modos de renderização","url":"https://nuxt.com/docs/guide/concepts/rendering"},{"name":"Feature-Sliced Design","url":"https://feature-sliced.design/"}],"checklist":[{"key":"comparar-modos","text":"Consigo comparar SPA, SSR, SSG e renderização híbrida em termos de SEO, TTFB/LCP, custo de servidor e complexidade, e escolher para um caso concreto."},{"key":"hidratacao","text":"Entendo o que é hidratação e por que ocorrem hydration mismatches (ex.: `Date.now()` ou `window` no render, HTML inválido), e conheço a hidratação lazy (`hydrateOnVisible`, `hydrateOnIdle`) para adiar componentes pesados."},{"key":"nuxt-paginas-e-dados","text":"Crio páginas e layouts no Nuxt (roteamento por arquivos) e busco dados com `useFetch`/`useAsyncData`, entendendo que rodam no servidor e no cliente."},{"key":"route-rules","text":"Defino o modo de renderização por rota com `routeRules` (`prerender`, `swr`, `ssr: false`) conforme a necessidade de cada página."},{"key":"estado-no-ssr","text":"Evito estado compartilhado entre requisições no servidor (singletons de módulo) e uso `useState` ou Pinia com hidratação correta."},{"key":"estrutura-por-feature","text":"Sei organizar um front-end grande por feature/domínio, com camada de API tipada e fronteiras claras entre UI, estado e serviços, e registrar a decisão em um ADR."}]},{"track":"backend-php-laravel","slug":"php-moderno-8x","title":"PHP moderno (8.x)","description":"Os recursos que definem o PHP moderno: tipagem estrita, tipos de união, enums, `readonly`, `match`, argumentos nomeados e promoção de propriedades no construtor. Escopo: fundamentos da linguagem (arrays, funções, closures) e as novidades do PHP 8.0 em diante, como property hooks e visibilidade assimétrica no 8.4.","level":"beginner","difficulty":2,"position":0,"prerequisites":["fund-variaveis-e-tipos","fund-funcoes"],"resources":[{"name":"PHP — Manual (pt_BR)","url":"https://www.php.net/manual/pt_BR/"},{"name":"Laracasts — PHP for Beginners","url":"https://laracasts.com/series/php-for-beginners-2023-edition"},{"name":"PHP: The Right Way","url":"https://phptherightway.com/"},{"name":"PHP.net — Novidades do PHP 8.4","url":"https://www.php.net/releases/8.4/pt_BR.php"}],"checklist":[{"key":"strict-types-e-tipos","text":"Uso `declare(strict_types=1);` e declaro tipos de parâmetros, retornos e propriedades (incluindo `?T`, `T|U` e `mixed`), entendendo o que muda no modo estrito."},{"key":"enums-e-readonly","text":"Modelo um conjunto fixo de valores com `enum` (puro e `backed`) e uma classe de valor imutável com propriedades `readonly`."},{"key":"match-e-named-args","text":"Sei usar `match` (e a diferença para `switch`), argumentos nomeados e o operador nullsafe `?->`."},{"key":"constructor-promotion","text":"Escrevo construtores com promoção de propriedades (`public function __construct(private string $name) {}`) e sei quando combinar com `readonly`."},{"key":"arrays-e-closures","text":"Domino arrays (spread `...`, `array_map`, `array_filter`), closures, arrow functions `fn` e a sintaxe de first-class callable (`strlen(...)`)."},{"key":"novidades-recentes","text":"Conheço as novidades das versões recentes, como property hooks e visibilidade assimétrica (`public private(set)`) no 8.4 e o operador pipe (`|>`) no 8.5."}]},{"track":"backend-php-laravel","slug":"php-composer-e-psr","title":"Composer e PSR","description":"Composer é o gerenciador de dependências do PHP, e as PSRs do PHP-FIG padronizam autoload, estilo de código e interfaces comuns entre bibliotecas e frameworks. Escopo: `composer.json` e `composer.lock`, versionamento semântico, autoload PSR-4, scripts, `composer audit` e as principais PSRs (4, 3, 7, 11, 15, 18) e o estilo PER/PSR-12.","level":"beginner","difficulty":2,"position":1,"prerequisites":["php-moderno-8x","fund-terminal-e-shell"],"resources":[{"name":"Composer — Documentação","url":"https://getcomposer.org/doc/"},{"name":"Composer — Versões e restrições de versão","url":"https://getcomposer.org/doc/articles/versions.md"},{"name":"PHP-FIG — PSR-4: Autoloader","url":"https://www.php-fig.org/psr/psr-4/"},{"name":"PHP-FIG — Lista de PSRs","url":"https://www.php-fig.org/psr/"}],"checklist":[{"key":"composer-json-e-lock","text":"Entendo a diferença entre `composer.json` e `composer.lock` e sei por que o `composer.lock` deve ir para o Git em aplicações."},{"key":"install-vs-update","text":"Sei quando usar `composer install` versus `composer update` e como funcionam as restrições de versão (`^`, `~`, `*`)."},{"key":"require-e-dev","text":"Adiciono e removo dependências com `composer require` e `composer remove`, separando as de desenvolvimento com `--dev`."},{"key":"autoload-psr4","text":"Configuro o autoload PSR-4 (`autoload.psr-4`), mapeando um namespace a um diretório, e regenero com `composer dump-autoload`."},{"key":"psrs-principais","text":"Sei explicar o propósito das principais PSRs (4, 3, 7, 11, 15 e 18) e que o estilo de código atual é o PER Coding Style, sucessor da PSR-12."},{"key":"audit-e-scripts","text":"Já usei `composer audit` para achar dependências vulneráveis e `scripts` no `composer.json` (por exemplo, atalhos para testes e lint)."}]},{"track":"backend-php-laravel","slug":"php-poo","title":"POO em PHP","description":"Programação orientada a objetos aplicada ao PHP moderno: classes, interfaces, traits, herança, polimorfismo e composição, base para entender o container, as facades e os models do Laravel. Escopo: namespaces, visibilidade, classes abstratas, `static`, injeção de dependência, exceções e composição sobre herança.","level":"junior","difficulty":3,"position":2,"prerequisites":["php-moderno-8x","php-composer-e-psr","fund-arrays-listas-e-mapas"],"resources":[{"name":"PHP — Manual: Classes e objetos","url":"https://www.php.net/manual/pt_BR/language.oop5.php"},{"name":"Refactoring Guru — Padrões de projeto","url":"https://refactoring.guru/pt-br/design-patterns"},{"name":"Livro: PHP Objects, Patterns, and Practice — Matt Zandstra"}],"checklist":[{"key":"classes-interfaces-abstratas","text":"Sei declarar classes, interfaces e classes abstratas e explico quando usar cada uma."},{"key":"heranca-vs-composicao","text":"Consigo justificar composição sobre herança e refatorar uma hierarquia frágil para composição."},{"key":"traits","text":"Entendo traits (`use`), a resolução de conflitos de métodos e quando evitá-las."},{"key":"visibilidade-e-static","text":"Uso `public`/`protected`/`private` e `static` com critério e explico a diferença entre `self` e `static` (late static binding)."},{"key":"injecao-de-dependencia","text":"Aplico injeção de dependência pelo construtor, dependendo de interfaces e não de classes concretas, e troco a implementação em um teste."},{"key":"excecoes","text":"Crio exceções de domínio (classes que estendem `Exception`), uso `try`/`catch`/`finally` e distingo `Exception` de `Error` e `Throwable`."}]},{"track":"backend-php-laravel","slug":"php-rotas-e-controllers","title":"Rotas e controllers","description":"Como o Laravel recebe uma requisição e a encaminha ao seu código: rotas, middleware e controllers. Escopo: `routes/web.php` e `routes/api.php`, parâmetros e route model binding, `Route::resource`/`apiResource`, grupos com prefixo e middleware, rotas nomeadas, rate limiting e `php artisan route:list`.","level":"junior","difficulty":2,"position":3,"prerequisites":["php-moderno-8x","php-composer-e-psr","web-fetch-e-http"],"resources":[{"name":"Laravel — Documentação: Routing","url":"https://laravel.com/docs/routing"},{"name":"Laravel — Documentação: Controllers","url":"https://laravel.com/docs/controllers"},{"name":"Laravel — Documentação: Middleware","url":"https://laravel.com/docs/middleware"},{"name":"Laracasts — 30 Days to Learn Laravel","url":"https://laracasts.com/series/30-days-to-learn-laravel-11"}],"checklist":[{"key":"rotas-e-verbos","text":"Defino rotas `GET`, `POST`, `PUT`, `PATCH` e `DELETE` e listo todas com `php artisan route:list`."},{"key":"route-model-binding","text":"Uso parâmetros de rota e route model binding implícito (`/posts/{post}`), inclusive por outra coluna (`{post:slug}`)."},{"key":"resource-controllers","text":"Criei controllers com `php artisan make:controller --resource` ou `--api` e os registrei com `Route::resource`/`Route::apiResource`."},{"key":"grupos-e-middleware","text":"Agrupo rotas com `Route::prefix()->middleware()->group()` e aplico middleware como `auth` e `throttle`."},{"key":"rotas-nomeadas","text":"Nomeio rotas com `->name()` e gero URLs com `route()` em vez de caminhos fixos."},{"key":"install-api","text":"Sei que, nas versões atuais, as rotas de API (`routes/api.php`, prefixo `/api`) são habilitadas com `php artisan install:api` e que os middlewares globais são configurados em `bootstrap/app.php`."}]},{"track":"backend-php-laravel","slug":"php-migrations-e-eloquent-basico","title":"Migrations e Eloquent básico","description":"Versionamento do schema do banco com migrations e acesso a dados com o Eloquent, o ORM do Laravel baseado no padrão Active Record. Escopo: `Schema::create`, tipos de coluna, índices e chaves estrangeiras, models, CRUD, mass assignment (`fillable`), casts, scopes, soft deletes, factories e seeders.","level":"junior","difficulty":3,"position":4,"prerequisites":["php-poo","php-rotas-e-controllers","sql-modelo-relacional","sql-select-e-join"],"resources":[{"name":"Laravel — Documentação: Migrations","url":"https://laravel.com/docs/migrations"},{"name":"Laravel — Documentação: Eloquent ORM","url":"https://laravel.com/docs/eloquent"},{"name":"Laravel — Documentação: Eloquent factories","url":"https://laravel.com/docs/eloquent-factories"},{"name":"Martin Fowler — Active Record","url":"https://martinfowler.com/eaaCatalog/activeRecord.html"}],"checklist":[{"key":"criar-e-rodar-migrations","text":"Crio e rodo migrations (`make:migration`, `migrate`, `migrate:rollback`, `migrate:fresh --seed`) com `Schema::create`, tipos de coluna e índices."},{"key":"chaves-estrangeiras","text":"Declaro chaves estrangeiras com `foreignId()->constrained()->cascadeOnDelete()` e entendo o efeito de cada regra de exclusão."},{"key":"crud-eloquent","text":"Executo CRUD com Eloquent (`create`, `find`, `update`, `delete`, `firstOrCreate`, `updateOrCreate`) e sei o que cada método devolve."},{"key":"mass-assignment","text":"Entendo mass assignment e configuro `$fillable` ou `$guarded` (ou os atributos `#[Fillable]`/`#[Guarded]` das versões mais novas) corretamente."},{"key":"casts-e-scopes","text":"Uso casts (datas, `array`, enums, pelo método `casts()`), accessors e mutators com `Attribute` e query scopes locais."},{"key":"soft-deletes-e-factories","text":"Já usei `SoftDeletes`, factories e seeders para gerar dados de desenvolvimento e de teste."}]},{"track":"backend-php-laravel","slug":"php-validacao-e-form-requests","title":"Validação e Form Requests","description":"Validar a entrada da requisição antes de tocar no domínio, com mensagens e respostas de erro padronizadas. Escopo: `$request->validate()`, regras (`required`, `unique`, `exists`, `Rule::`), Form Requests (`rules()`, `authorize()`, `prepareForValidation()`), mensagens customizadas, `validated()`/`safe()` e a resposta 422 em APIs.","level":"junior","difficulty":2,"position":5,"prerequisites":["php-rotas-e-controllers"],"resources":[{"name":"Laravel — Documentação: Validation","url":"https://laravel.com/docs/validation"},{"name":"Laravel — Documentação: Requests","url":"https://laravel.com/docs/requests"},{"name":"Laravel — Documentação: Localization","url":"https://laravel.com/docs/localization"}],"checklist":[{"key":"validate-inline","text":"Valido com `$request->validate([...])` e uso `$request->validated()` em vez de `all()` para persistir dados."},{"key":"form-request","text":"Crio um Form Request (`php artisan make:request`) com `rules()`, `authorize()` e `messages()`/`attributes()` e o injeto no controller."},{"key":"regras-de-banco","text":"Uso regras que consultam o banco (`unique`, `exists`) e `Rule::unique(...)->ignore($model)` na edição."},{"key":"prepare-e-aninhados","text":"Normalizo dados antes de validar com `prepareForValidation()` e valido arrays e campos aninhados (`items.*.quantity`)."},{"key":"resposta-422","text":"Entendo o formato da resposta 422 em APIs (`message` e `errors` por campo) e como o formulário web volta com `$errors` e `old()`."},{"key":"regras-custom-e-i18n","text":"Já criei uma regra customizada (`make:rule` ou closure) e traduzi as mensagens de validação para pt-BR (`php artisan lang:publish`)."}]},{"track":"backend-php-laravel","slug":"php-api-resources","title":"API Resources","description":"Camada de transformação que controla o JSON devolvido pela API, desacoplando o formato público do schema do banco. Escopo: `JsonResource` e coleções, atributos condicionais (`when`, `whenLoaded`), paginação (`links`/`meta`), envelope `data`, contrato estável e cuidado com N+1 e vazamento de campos; noções dos resources JSON:API do Laravel atual.","level":"junior","difficulty":3,"position":6,"prerequisites":["php-rotas-e-controllers","php-migrations-e-eloquent-basico"],"resources":[{"name":"Laravel — Documentação: Eloquent API resources","url":"https://laravel.com/docs/eloquent-resources"},{"name":"Laravel — Documentação: Paginação","url":"https://laravel.com/docs/pagination"},{"name":"Livro: Build APIs You Won't Hate — Phil Sturgeon"}],"checklist":[{"key":"resource-de-model","text":"Crio um `JsonResource` (`php artisan make:resource`) e devolvo `new PostResource($post)` (ou `$post->toResource()` nas versões atuais) controlando exatamente quais campos são expostos."},{"key":"colecoes-e-paginacao","text":"Devolvo coleções e páginas com `PostResource::collection($query->paginate())`, explico os blocos `data`, `links` e `meta` e sei desativar ou personalizar o envelope (`withoutWrapping()`, `$wrap`)."},{"key":"campos-condicionais","text":"Uso `when()`, `whenLoaded()` e `whenCounted()` para incluir campos e relações apenas quando disponíveis, evitando N+1."},{"key":"contrato-estavel","text":"Sei por que não devo devolver o model direto (vazamento de colunas e acoplamento ao schema) e como manter um contrato estável da API."},{"key":"status-http","text":"Devolvo os códigos HTTP corretos (`201` ao criar, `204` ao remover com `response()->noContent()`, `404` e `422` nos erros)."},{"key":"json-api","text":"Conheço os resources JSON:API do Laravel atual (`JsonApiResource`, sparse fieldsets e includes) e sei quando adotar o padrão em vez de um formato próprio."}]},{"track":"backend-php-laravel","slug":"php-relacionamentos-eloquent","title":"Relacionamentos Eloquent","description":"Modelagem de associações entre tabelas no Eloquent: um-para-um, um-para-muitos, muitos-para-muitos e relações polimórficas. Escopo: `hasMany`, `belongsTo`, `belongsToMany`, `morphTo`, `hasManyThrough`, tabelas pivot com atributos, criação e consulta via relações, `withCount`, `whereHas` e eager loading básico.","level":"junior","difficulty":3,"position":7,"prerequisites":["php-migrations-e-eloquent-basico","sql-modelagem-e-er"],"resources":[{"name":"Laravel — Documentação: Eloquent relationships","url":"https://laravel.com/docs/eloquent-relationships"},{"name":"Laravel — Documentação: Eloquent collections","url":"https://laravel.com/docs/eloquent-collections"},{"name":"Laravel — Documentação: Query builder","url":"https://laravel.com/docs/queries"}],"checklist":[{"key":"um-para-muitos","text":"Defino e uso relações um-para-muitos (`hasMany`/`belongsTo`) e crio registros pela relação (`$user->posts()->create([...])`)."},{"key":"muitos-para-muitos","text":"Modelo muitos-para-muitos com tabela pivot e uso `attach`, `detach`, `sync` e `withPivot`/`withTimestamps`."},{"key":"has-one-e-through","text":"Entendo `hasOne`, `hasOneThrough` e `hasManyThrough` e reconheço quando cada um aparece."},{"key":"polimorficas","text":"Implementei uma relação polimórfica (`morphTo`/`morphMany`) e sei o papel de `Relation::enforceMorphMap`."},{"key":"filtrar-e-contar","text":"Filtro e conto por relação com `has`, `whereHas`, `withCount` e `withExists`."},{"key":"lazy-vs-eager","text":"Sei a diferença entre acessar uma relação como propriedade (lazy) e carregá-la com `with()`/`load()` (eager), e reconheço a origem de um N+1."}]},{"track":"backend-php-laravel","slug":"php-autenticacao-sanctum","title":"Autenticação (Sanctum)","description":"Autenticação de APIs e SPAs com o Laravel Sanctum: tokens pessoais de API (com abilities) e autenticação por cookie de sessão para SPAs em domínios de primeira parte. Escopo: `HasApiTokens`, `createToken`, middleware `auth:sanctum`, fluxo do `csrf-cookie`, expiração e revogação de tokens, rate limiting no login e hash de senhas.","level":"mid","difficulty":3,"position":8,"prerequisites":["php-validacao-e-form-requests","php-migrations-e-eloquent-basico","seg-hash-senhas-criptografia-basica"],"resources":[{"name":"Laravel — Documentação: Sanctum","url":"https://laravel.com/docs/sanctum"},{"name":"Laravel — Documentação: Authentication","url":"https://laravel.com/docs/authentication"},{"name":"Laravel — Documentação: Hashing","url":"https://laravel.com/docs/hashing"},{"name":"OWASP — Authentication Cheat Sheet","url":"https://cheatsheetseries.owasp.org/cheatsheets/Authentication_Cheat_Sheet.html"}],"checklist":[{"key":"habilitar-sanctum","text":"Habilito a autenticação de API (`php artisan install:api`), preparo o model com `HasApiTokens` e protejo rotas com o middleware `auth:sanctum`."},{"key":"emitir-token","text":"Implementei um login que valida as credenciais (`Auth::attempt` ou `Hash::check`), emite um token com `createToken('nome', ['abilities'])` e o devolve uma única vez."},{"key":"abilities-do-token","text":"Restrinjo tokens com abilities e verifico com `tokenCan()` ou com os middlewares de abilities."},{"key":"logout-e-revogacao","text":"Faço logout revogando o token atual (`currentAccessToken()->delete()`) e sei revogar todos os tokens do usuário."},{"key":"spa-com-cookie","text":"Entendo o fluxo de SPA com cookie: `/sanctum/csrf-cookie`, `statefulApi()`, a opção `stateful` do `config/sanctum.php` e `withCredentials` no cliente."},{"key":"endurecer-login","text":"Aplico `throttle`/`RateLimiter` ao login, guardo senhas apenas com hash (`Hash::make`) e nunca registro tokens em logs."}]},{"track":"backend-php-laravel","slug":"php-autorizacao-policies-gates","title":"Autorização (Policies/Gates)","description":"Controle do que cada usuário autenticado pode fazer, centralizado em Gates (checagens avulsas) e Policies (regras por model). Escopo: `Gate::define`, policies (`make:policy`), `authorize`/`can`/`cannot`, middleware `can:`, respostas com `Response::deny()` e `denyAsNotFound()`, `before` para super admin e testes de autorização.","level":"mid","difficulty":3,"position":9,"prerequisites":["php-autenticacao-sanctum","php-relacionamentos-eloquent","seg-autorizacao-rbac-abac"],"resources":[{"name":"Laravel — Documentação: Authorization","url":"https://laravel.com/docs/authorization"},{"name":"OWASP — Authorization Cheat Sheet","url":"https://cheatsheetseries.owasp.org/cheatsheets/Authorization_Cheat_Sheet.html"},{"name":"Spatie — laravel-permission (papéis e permissões)","url":"https://spatie.be/docs/laravel-permission"}],"checklist":[{"key":"gates","text":"Defino e uso um Gate (`Gate::define`, `Gate::allows`/`denies`) para regras que não pertencem a um model."},{"key":"policies-de-model","text":"Gero uma policy (`make:policy --model=Post`) com métodos `view`, `update`, `delete` etc. e entendo como ela é descoberta (convenção, `Gate::policy` ou `#[UsePolicy]`)."},{"key":"autorizar-no-controller","text":"Autorizo ações com `Gate::authorize()`, `$request->user()->can()` ou o middleware `can:`, e não apenas escondendo botões no front-end."},{"key":"403-vs-404","text":"Sei usar `Response::deny()` e `denyAsNotFound()` e quando responder 404 em vez de 403 para não vazar a existência de um recurso."},{"key":"rbac-vs-ownership","text":"Diferencio RBAC (papéis e permissões) de regras por propriedade do recurso (ownership) e conheço o `spatie/laravel-permission`."},{"key":"testar-autorizacao","text":"Escrevo testes que garantem 403 para um usuário sem permissão (`actingAs($user)->putJson(...)->assertForbidden()`)."}]},{"track":"backend-php-laravel","slug":"php-testes-com-pest","title":"Testes com Pest","description":"Testes automatizados em Laravel com o Pest, framework de sintaxe fluente construído sobre o PHPUnit. Escopo: testes de feature (HTTP/JSON) e unitários, `RefreshDatabase`, factories, `actingAs`, expectations (`expect()`), datasets, fakes (`Http::fake`, `Event::fake`, `Queue::fake`, `Mail::fake`), testes de arquitetura (`arch()`), cobertura e execução em paralelo.","level":"mid","difficulty":3,"position":10,"prerequisites":["php-migrations-e-eloquent-basico","php-validacao-e-form-requests","qual-testes-unitarios"],"resources":[{"name":"Pest — Documentação","url":"https://pestphp.com/docs"},{"name":"Laravel — Documentação: Testing","url":"https://laravel.com/docs/testing"},{"name":"Laravel — Documentação: HTTP tests","url":"https://laravel.com/docs/http-tests"},{"name":"Laravel — Documentação: Mocking","url":"https://laravel.com/docs/mocking"}],"checklist":[{"key":"instalar-pest","text":"Instalo e configuro o Pest em um projeto Laravel (`pestphp/pest` e `pestphp/pest-plugin-laravel`) e rodo a suíte com `./vendor/bin/pest` ou `php artisan test`."},{"key":"feature-test-api","text":"Escrevo um teste de feature para um endpoint JSON (`postJson`, `assertCreated`, `assertJsonPath`, `assertDatabaseHas`)."},{"key":"banco-e-factories","text":"Uso `RefreshDatabase`, factories e `actingAs()` para preparar cenários isolados e repetíveis."},{"key":"expectations-e-datasets","text":"Uso a API `expect()` com expectativas encadeadas e datasets (`with()`) para cobrir vários casos em um único teste."},{"key":"fakes-de-efeitos","text":"Isolo efeitos colaterais com `Http::fake()`, `Event::fake()`, `Queue::fake()`, `Mail::fake()` e `Notification::fake()`, e faço asserções sobre eles."},{"key":"arch-e-cobertura","text":"Já usei `arch()` para impor regras de arquitetura e `--coverage` e `--parallel` para medir cobertura e acelerar a suíte."}]},{"track":"backend-php-laravel","slug":"php-filas-e-jobs","title":"Filas e Jobs","description":"Execução assíncrona de trabalho lento ou pesado (e-mails, relatórios, integrações) fora do ciclo da requisição, usando o sistema de filas do Laravel. Escopo: jobs (`ShouldQueue`), drivers (database, Redis, SQS), `queue:work`, tentativas, `backoff` e timeout, `failed_jobs`, chains e batches, jobs únicos, middleware de job (`WithoutOverlapping`, `RateLimited`), idempotência e testes com `Queue::fake()`.","level":"mid","difficulty":4,"position":11,"prerequisites":["php-poo","php-migrations-e-eloquent-basico"],"resources":[{"name":"Laravel — Documentação: Queues","url":"https://laravel.com/docs/queues"},{"name":"Laravel — Documentação: Task scheduling","url":"https://laravel.com/docs/scheduling"},{"name":"Livro: Laravel Queues in Action — Mohamed Said"},{"name":"Supervisor — Documentação","url":"https://supervisord.org/"}],"checklist":[{"key":"criar-e-despachar-job","text":"Crio um job (`make:job`) que implementa `ShouldQueue`, despacho com `Job::dispatch()` e o processo com `php artisan queue:work`."},{"key":"tentativas-e-backoff","text":"Configuro tentativas, `backoff` e timeout (propriedades ou atributos como `#[Tries]` e `#[Backoff]` nas versões novas), trato falhas em `failed()` e reprocesso com `queue:retry`."},{"key":"idempotencia","text":"Entendo que um job pode executar mais de uma vez e escrevo handlers idempotentes, usando `ShouldBeUnique` ou `WithoutOverlapping` quando preciso."},{"key":"chains-e-batches","text":"Já usei `Bus::chain()` e `Bus::batch()` para encadear ou agrupar jobs, tratando `then`, `catch` e `finally`."},{"key":"after-commit","text":"Evito a corrida com transações usando `afterCommit()` (ou `after_commit` na conexão) e passo models e IDs de forma segura para o job."},{"key":"testar-jobs","text":"Testo o despacho com `Queue::fake()` e `Queue::assertPushed()`, e a lógica do job chamando `handle()` diretamente."}]},{"track":"backend-php-laravel","slug":"php-cache","title":"Cache","description":"Uso do cache para reduzir latência e carga no banco, com a API unificada do Laravel sobre vários drivers. Escopo: `Cache::remember`, TTL e invalidação, tags, locks atômicos, stale-while-revalidate (`Cache::flexible`), cache de configuração/rotas/views e armadilhas como dados desatualizados e cache stampede.","level":"mid","difficulty":3,"position":12,"prerequisites":["php-rotas-e-controllers","php-migrations-e-eloquent-basico"],"resources":[{"name":"Laravel — Documentação: Cache","url":"https://laravel.com/docs/cache"},{"name":"Laravel — Documentação: Redis","url":"https://laravel.com/docs/redis"},{"name":"Redis — Documentação","url":"https://redis.io/docs/latest/"}],"checklist":[{"key":"remember-e-ttl","text":"Cacheio o resultado de uma consulta com `Cache::remember`, definindo um TTL adequado."},{"key":"invalidar-cache","text":"Invalido o cache quando o dado muda (`Cache::forget`, eventos ou observers) e explico o trade-off entre TTL curto e invalidação explícita."},{"key":"drivers-e-tags","text":"Conheço os drivers (`file`, `database`, `redis`, `memcached`, `array`) e sei que as tags de cache não funcionam nos drivers `file`, `database` e DynamoDB."},{"key":"locks-e-stampede","text":"Entendo o cache stampede e sei mitigá-lo com `Cache::lock()` ou com `Cache::flexible()` (stale-while-revalidate)."},{"key":"chaves-e-escopo","text":"Defino chaves previsíveis, com namespace e versão (ex.: `posts:{id}:v2`), e nunca cacheio dados específicos de um usuário em uma chave compartilhada."},{"key":"cache-do-framework","text":"Uso `php artisan optimize` (config, rotas, views e eventos em cache) em produção e sei por que `env()` só deve ser lido nos arquivos de `config`."}]},{"track":"backend-php-laravel","slug":"php-eventos-e-listeners","title":"Eventos e listeners","description":"Mecanismo de eventos do Laravel (padrão observer) para desacoplar a reação a algo que aconteceu (como `OrderPlaced`) da ação que o disparou. Escopo: eventos e listeners com auto-descoberta, `dispatch()`, listeners enfileirados (`ShouldQueue`), subscribers, eventos de model e observers, `ShouldDispatchAfterCommit` e `Event::fake()`.","level":"mid","difficulty":3,"position":13,"prerequisites":["php-poo","php-migrations-e-eloquent-basico"],"resources":[{"name":"Laravel — Documentação: Events","url":"https://laravel.com/docs/events"},{"name":"Laravel — Documentação: Notifications","url":"https://laravel.com/docs/notifications"},{"name":"Refactoring Guru — Observer","url":"https://refactoring.guru/pt-br/design-patterns/observer"}],"checklist":[{"key":"evento-e-listener","text":"Crio um evento e um listener (`make:event`, `make:listener`), disparo com `OrderPlaced::dispatch($order)` e entendo a auto-descoberta de listeners."},{"key":"evento-vs-chamada-direta","text":"Sei justificar quando um evento realmente desacopla e quando uma chamada direta (ou uma Action) é mais clara."},{"key":"listeners-enfileirados","text":"Criei um listener que implementa `ShouldQueue` e uso `ShouldDispatchAfterCommit` ou `ShouldQueueAfterCommit` para só agir depois do commit da transação."},{"key":"observers-e-model-events","text":"Uso eventos de model (`creating`, `created`, `updated`...) e Observers (`#[ObservedBy]`), e conheço os riscos (efeitos ocultos, `saveQuietly`)."},{"key":"subscribers","text":"Conheço subscribers e sei interromper a propagação retornando `false` de um listener."},{"key":"testar-eventos","text":"Testo eventos com `Event::fake()`, `Event::assertDispatched()` e `Event::assertListening()`."}]},{"track":"backend-php-laravel","slug":"php-n-plus-1-e-otimizacao-eloquent","title":"N+1 e otimização Eloquent","description":"Diagnosticar e eliminar o problema de N+1 queries e outros gargalos comuns do Eloquent. Escopo: eager loading (`with`, `load`, `withCount`), `Model::preventLazyLoading()` e eager loading automático, seleção de colunas, `chunkById`/`lazy`/`cursor`, `exists()` versus `count()`, uso de índices e ferramentas de diagnóstico (`DB::listen`, Debugbar, Telescope, Pulse).","level":"mid","difficulty":4,"position":14,"prerequisites":["php-relacionamentos-eloquent","php-api-resources","sql-indices"],"resources":[{"name":"Laravel — Documentação: Eloquent relationships (eager loading)","url":"https://laravel.com/docs/eloquent-relationships"},{"name":"Laravel — Documentação: Database (query log e DB::listen)","url":"https://laravel.com/docs/database"},{"name":"Laracasts — Eloquent Performance Patterns","url":"https://laracasts.com/series/eloquent-performance-patterns"},{"name":"Use The Index, Luke","url":"https://use-the-index-luke.com/"}],"checklist":[{"key":"detectar-n-mais-1","text":"Reconheço um N+1 (query dentro de um loop ou accessor) e confirmo com `DB::listen`, Debugbar/Telescope ou contando queries em um teste."},{"key":"eager-loading","text":"Corrijo N+1 com `with()`, `load()` e `loadMissing()`, inclusive relações aninhadas (`with('posts.comments')`) e colunas limitadas (`with('user:id,name')`)."},{"key":"prevent-lazy-loading","text":"Ativo `Model::preventLazyLoading(! app()->isProduction())` para falhar cedo em desenvolvimento e conheço o eager loading automático (`Model::automaticallyEagerLoadRelationships()`)."},{"key":"agregar-no-banco","text":"Prefiro `withCount`, `exists()` e agregações no banco a carregar coleções inteiras só para contar ou verificar."},{"key":"processar-em-lotes","text":"Processo grandes volumes com `chunkById`, `lazy()` ou `cursor()` sem estourar a memória e sei quando cada um se aplica."},{"key":"indices-e-explain","text":"Leio o SQL gerado (`toSql()` ou `dumpRawSql()`) e o plano de execução (`EXPLAIN`), identifico a falta de um índice e proponho a migration com o índice certo."}]},{"track":"backend-php-laravel","slug":"php-actions-services-e-arquitetura","title":"Actions/Services e arquitetura","description":"Como organizar a regra de negócio para que os controllers fiquem finos e o código seja testável e evolua sem virar bagunça. Escopo: classes Action de responsabilidade única, Services, DTOs imutáveis, injeção de dependência e container de serviços (bind, singleton, interfaces), transações (`DB::transaction`), organização por domínio/módulo e quando a abstração é excessiva (repositories, over-engineering).","level":"mid","difficulty":4,"position":15,"prerequisites":["php-poo","php-validacao-e-form-requests","php-testes-com-pest","arq-principios-solid","qual-clean-code"],"resources":[{"name":"Laravel — Documentação: Service container","url":"https://laravel.com/docs/container"},{"name":"Livro: Laravel Beyond CRUD — Brent Roose","url":"https://laravel-beyond-crud.com/"},{"name":"Spatie — laravel-data (DTOs)","url":"https://spatie.be/docs/laravel-data"},{"name":"Livro: Clean Architecture — Robert C. Martin"}],"checklist":[{"key":"controller-fino","text":"Refatoro um controller gordo extraindo a regra de negócio para uma Action (como `CreateOrder` com um método `handle`) ou Service, deixando no controller só o que é HTTP."},{"key":"dtos","text":"Uso DTOs imutáveis (`readonly class`) para trafegar dados entre camadas, em vez de arrays soltos ou do objeto `Request`."},{"key":"container-e-interfaces","text":"Entendo o container de serviços: auto-resolução por type-hint, `bind`/`singleton`/`scoped` e como vincular uma interface a uma implementação em um Service Provider."},{"key":"transacoes","text":"Envolvo operações multi-tabela em `DB::transaction()` e sei posicionar `afterCommit` para eventos e jobs."},{"key":"testar-isolado","text":"Testo Actions e Services de forma isolada, trocando dependências por fakes ou mocks."},{"key":"quando-abstrair","text":"Sei argumentar quando uma abstração (repository, service) compensa e quando é over-engineering para o tamanho do projeto."}]},{"track":"backend-php-laravel","slug":"php-reverb-e-broadcasting","title":"Reverb e broadcasting","description":"Comunicação em tempo real com WebSockets usando o Laravel Reverb (servidor WebSocket de primeira parte) e o sistema de broadcasting, com o Laravel Echo no cliente. Escopo: eventos `ShouldBroadcast`, canais públicos, privados e presence, autorização de canais, client events (whisper), configuração e operação do Reverb, escala com Redis e testes.","level":"senior","difficulty":4,"position":16,"prerequisites":["php-eventos-e-listeners","php-filas-e-jobs","php-autorizacao-policies-gates"],"resources":[{"name":"Laravel — Documentação: Broadcasting","url":"https://laravel.com/docs/broadcasting"},{"name":"Laravel — Documentação: Reverb","url":"https://laravel.com/docs/reverb"},{"name":"MDN — WebSockets API","url":"https://developer.mozilla.org/pt-BR/docs/Web/API/WebSockets_API"}],"checklist":[{"key":"instalar-reverb","text":"Instalo o broadcasting e o Reverb (`php artisan install:broadcasting`) e subo o servidor com `php artisan reverb:start`."},{"key":"evento-broadcast","text":"Crio um evento `ShouldBroadcast`, defino `broadcastOn()`, `broadcastAs()` e `broadcastWith()` e entendo que o envio passa pela fila (ou uso `ShouldBroadcastNow`)."},{"key":"canais-e-autorizacao","text":"Diferencio canais públicos, privados e presence e autorizo canais privados em `routes/channels.php` com `Broadcast::channel`."},{"key":"echo-no-vue","text":"Consumi eventos no front-end com o Laravel Echo (`Echo.private(...).listen(...)` ou o composable `useEcho` do `@laravel/echo-vue`) em um componente Vue, liberando o canal ao desmontar."},{"key":"escala-e-producao","text":"Entendo como operar o Reverb em produção: limite de arquivos abertos, `wss://` atrás de proxy reverso, Supervisor e escala horizontal com Redis."},{"key":"testar-broadcast","text":"Testo o disparo do broadcast com `Event::fake()` e `Event::assertDispatched()`, e depuro as mensagens com `php artisan reverb:start --debug` (lembrando de `reverb:restart` após mudar o código)."}]},{"track":"backend-php-laravel","slug":"php-laravel-em-producao","title":"Laravel em produção (Horizon, Octane)","description":"Levar uma aplicação Laravel para produção com desempenho, confiabilidade e operabilidade. Escopo: filas gerenciadas com Horizon, servidores de aplicação de alta performance com Octane (FrankenPHP, Swoole, RoadRunner), caches do framework (`php artisan optimize`), OPcache, agendador, health check, observabilidade (Pulse) e deploy com rollback (Forge, Laravel Cloud ou servidor próprio).","level":"senior","difficulty":5,"position":17,"prerequisites":["php-filas-e-jobs","php-cache","php-n-plus-1-e-otimizacao-eloquent","ops-deploy-php-node","ops-logs-estruturados"],"resources":[{"name":"Laravel — Documentação: Deployment","url":"https://laravel.com/docs/deployment"},{"name":"Laravel — Documentação: Horizon","url":"https://laravel.com/docs/horizon"},{"name":"Laravel — Documentação: Octane","url":"https://laravel.com/docs/octane"},{"name":"The Twelve-Factor App (pt-BR)","url":"https://12factor.net/pt_br/"}],"checklist":[{"key":"otimizar-no-deploy","text":"Preparo um deploy com `composer install --no-dev --optimize-autoloader` e `php artisan optimize`, rodando `php artisan migrate --force` de forma segura."},{"key":"workers-supervisionados","text":"Mantenho workers de fila vivos com Supervisor/systemd (ou Horizon) e os reinicio a cada deploy com `queue:restart` ou `horizon:terminate`."},{"key":"configurar-horizon","text":"Configuro o Horizon (supervisors, estratégia de balanceamento, processos, tags e métricas), protejo o dashboard e interpreto o tempo de espera das filas."},{"key":"riscos-do-octane","text":"Entendo o modelo do Octane (aplicação mantida em memória) e seus riscos: singletons e estado estático vazando entre requisições, injeção de container/request e vazamentos de memória."},{"key":"opcache-e-fpm","text":"Sei dimensionar o PHP-FPM e habilitar o OPcache, medindo o ganho antes e depois."},{"key":"operacao-e-rollback","text":"Configuro logs estruturados, health check (`/up`), monitoramento (Pulse), o agendador (`schedule:run` a cada minuto) e uma estratégia de deploy com rollback."}]},{"track":"banco-de-dados-sql","slug":"sql-modelo-relacional","title":"Modelo relacional","description":"O modelo relacional organiza os dados em tabelas (relações) de linhas e colunas ligadas por chaves primárias e estrangeiras, com constraints que mantêm a integridade. É a base conceitual de PostgreSQL, MySQL e SQLite e o ponto de partida para modelar, consultar e otimizar qualquer banco SQL.","level":"beginner","difficulty":2,"position":0,"prerequisites":[],"resources":[{"name":"PostgreSQL — Tutorial: Conceitos de bancos de dados relacionais","url":"https://www.postgresql.org/docs/current/tutorial-concepts.html"},{"name":"SQLite — Documentação (banco local para praticar)","url":"https://sqlite.org/docs.html"},{"name":"Artigo: A Relational Model of Data for Large Shared Data Banks (E. F. Codd, 1970)"},{"name":"Livro: Database System Concepts (Silberschatz, Korth e Sudarshan)"}],"checklist":[{"key":"explicar-relacao-tupla-atributo","text":"Consigo explicar a diferença entre tabela, linha e coluna usando os termos relação, tupla e atributo."},{"key":"diferenciar-tipos-de-chave","text":"Sei diferenciar chave primária, chave candidata, chave natural e chave substituta (surrogate key) e escolher entre elas em um exemplo."},{"key":"criar-tabelas-com-constraints","text":"Já criei, em um banco local (por exemplo SQLite ou PostgreSQL), tabelas relacionadas usando PRIMARY KEY, FOREIGN KEY, NOT NULL, UNIQUE e CHECK."},{"key":"explicar-integridade-referencial","text":"Consigo explicar o que é integridade referencial e o que acontece em ON DELETE CASCADE, SET NULL e RESTRICT."},{"key":"entender-null","text":"Sei explicar o que NULL representa e por que NULL = NULL não resulta em verdadeiro (lógica de três valores)."}]},{"track":"banco-de-dados-sql","slug":"sql-select-e-join","title":"SELECT/JOIN","description":"Consultar dados com SELECT, WHERE, ORDER BY e LIMIT e combinar tabelas com INNER, LEFT, RIGHT, FULL e CROSS JOIN, incluindo subconsultas com IN e EXISTS. É a habilidade mais usada no dia a dia com SQL, e erros aqui (linhas duplicadas, NULLs em junções) geram relatórios silenciosamente incorretos.","level":"beginner","difficulty":2,"position":1,"prerequisites":["sql-modelo-relacional"],"resources":[{"name":"PostgreSQL — Tutorial: Joins Between Tables","url":"https://www.postgresql.org/docs/current/tutorial-join.html"},{"name":"PostgreSQL — Documentação: Queries","url":"https://www.postgresql.org/docs/current/queries.html"},{"name":"SQLite — SELECT","url":"https://www.sqlite.org/lang_select.html"},{"name":"Livro: Learning SQL (Alan Beaulieu)"}],"checklist":[{"key":"escrever-consultas-basicas","text":"Consigo escrever consultas com SELECT, WHERE, ORDER BY, LIMIT e DISTINCT sem consultar a documentação."},{"key":"diferenciar-inner-left-join","text":"Consigo explicar, com um exemplo, quais linhas INNER JOIN e LEFT JOIN retornam e quando cada um é o correto."},{"key":"ordem-logica-da-consulta","text":"Sei a ordem lógica de avaliação de uma consulta (FROM, WHERE, SELECT, ORDER BY) e por que um alias do SELECT geralmente não funciona no WHERE."},{"key":"evitar-duplicacao-em-joins","text":"Sei identificar quando um JOIN multiplica linhas (relações 1:N e N:N) e como evitar duplicações indesejadas."},{"key":"reescrever-subconsultas","text":"Consigo reescrever uma subconsulta usando IN, EXISTS ou JOIN e explicar por que NOT IN se comporta mal quando há NULLs."},{"key":"emular-full-join","text":"Sei que nem todo SGBD suporta FULL JOIN (como o MySQL) e consigo emulá-lo com LEFT JOIN, RIGHT JOIN e UNION."}]},{"track":"banco-de-dados-sql","slug":"sql-agregacoes-e-group-by","title":"Agregações e GROUP BY","description":"Resumir dados com COUNT, SUM, AVG, MIN e MAX, agrupar com GROUP BY e filtrar grupos com HAVING, tratando corretamente NULLs e COUNT(DISTINCT). É essencial para relatórios e métricas e prepara o terreno para window functions. Inclui noções de ROLLUP e GROUPING SETS para subtotais, cujo suporte varia entre SGBDs.","level":"junior","difficulty":2,"position":2,"prerequisites":["sql-select-e-join"],"resources":[{"name":"PostgreSQL — Tutorial: Aggregate Functions","url":"https://www.postgresql.org/docs/current/tutorial-agg.html"},{"name":"PostgreSQL — Documentação: Aggregate Functions","url":"https://www.postgresql.org/docs/current/functions-aggregate.html"},{"name":"SQLite — Aggregate Functions","url":"https://www.sqlite.org/lang_aggfunc.html"}],"checklist":[{"key":"usar-funcoes-de-agregacao","text":"Consigo calcular totais, médias, mínimos, máximos e contagens com SUM, AVG, MIN, MAX e COUNT em consultas reais."},{"key":"diferenciar-where-having","text":"Sei explicar a diferença entre WHERE e HAVING e em que etapa da consulta cada um filtra."},{"key":"nulls-em-agregacoes","text":"Sei como NULL afeta COUNT(*), COUNT(coluna), SUM e AVG e uso COALESCE quando preciso de um valor padrão."},{"key":"regra-do-group-by","text":"Consigo explicar por que toda coluna não agregada do SELECT precisa constar no GROUP BY e corrigir o erro quando isso falta."},{"key":"agregar-apos-join","text":"Já montei um relatório que agrega dados de duas ou mais tabelas com JOIN e sei evitar contagens infladas pela multiplicação de linhas."},{"key":"subtotais-com-rollup","text":"Conheço ROLLUP e GROUPING SETS, sei quando usá-los para gerar subtotais e como suprir sua falta no meu SGBD."}]},{"track":"banco-de-dados-sql","slug":"sql-modelagem-e-er","title":"Modelagem e ER","description":"Traduzir requisitos de negócio em um diagrama entidade-relacionamento (entidades, atributos, cardinalidades) e depois em tabelas, chaves e constraints, com relações 1:1, 1:N e N:N via tabelas associativas. Um bom modelo evita retrabalho caro e dados inconsistentes; o escopo inclui escolha de tipos de dados e antipadrões como EAV e associações polimórficas.","level":"junior","difficulty":3,"position":3,"prerequisites":["sql-modelo-relacional"],"resources":[{"name":"PostgreSQL — Documentação: Constraints","url":"https://www.postgresql.org/docs/current/ddl-constraints.html"},{"name":"PostgreSQL — Tutorial: Foreign Keys","url":"https://www.postgresql.org/docs/current/tutorial-fk.html"},{"name":"Livro: SQL Antipatterns (Bill Karwin)"},{"name":"Livro: Projeto de Banco de Dados (Carlos Alberto Heuser)"}],"checklist":[{"key":"desenhar-diagrama-er","text":"Consigo desenhar um diagrama ER (entidades, atributos, relacionamentos e cardinalidades) a partir de uma descrição de negócio."},{"key":"modelar-relacao-n-para-n","text":"Sei modelar relacionamentos N:N com tabela associativa e colocar nela os atributos do relacionamento (como quantidade ou data)."},{"key":"escolher-chaves-e-tipos","text":"Sei escolher chaves primárias (identity/serial ou UUID) e tipos de dados adequados (NUMERIC/DECIMAL para dinheiro, timestamps com fuso, texto) justificando a escolha."},{"key":"aplicar-constraints-de-negocio","text":"Já usei constraints (NOT NULL, UNIQUE, CHECK, FOREIGN KEY) para impor regras de negócio no próprio banco, e não só na aplicação."},{"key":"evitar-antipadroes","text":"Consigo reconhecer e evitar antipadrões de modelagem, como EAV (entity-attribute-value), colunas multivaloradas e associações polimórficas sem integridade referencial."},{"key":"modelar-historico-e-soft-delete","text":"Sei modelar histórico de alterações e exclusão lógica (soft delete) e explicar os custos de cada abordagem."}]},{"track":"banco-de-dados-sql","slug":"sql-normalizacao","title":"Normalização","description":"Aplicar as formas normais (1FN, 2FN, 3FN e BCNF) a partir de dependências funcionais para eliminar redundância e as anomalias de inserção, atualização e exclusão. Inclui saber quando desnormalizar de forma consciente, por desempenho de leitura ou relatórios, e quais riscos de consistência isso traz.","level":"junior","difficulty":3,"position":4,"prerequisites":["sql-modelo-relacional","sql-modelagem-e-er"],"resources":[{"name":"Wikipedia — Database normalization","url":"https://en.wikipedia.org/wiki/Database_normalization"},{"name":"Artigo: A Simple Guide to Five Normal Forms in Relational Database Theory (Kent, 1983)"},{"name":"Livro: Database System Concepts (Silberschatz, Korth e Sudarshan)"}],"checklist":[{"key":"identificar-dependencias-funcionais","text":"Consigo identificar dependências funcionais (parciais e transitivas) em uma tabela e apontar quais colunas dependem de quais."},{"key":"levar-tabela-ate-3fn","text":"Consigo levar uma tabela desnormalizada até a 3FN, explicando cada passo e a forma normal atingida."},{"key":"explicar-anomalias","text":"Sei dar exemplos de anomalias de inserção, atualização e exclusão causadas por redundância."},{"key":"diferenciar-3fn-bcnf","text":"Sei explicar a diferença entre 3FN e BCNF e em que situação elas divergem."},{"key":"desnormalizar-com-criterio","text":"Consigo justificar quando desnormalizar (por exemplo, coluna calculada, contador ou tabela de relatório) e quais riscos de consistência isso traz."}]},{"track":"banco-de-dados-sql","slug":"sql-indices","title":"Índices","description":"Entender como índices B-tree aceleram buscas, ordenações e junções ao custo de escritas mais lentas e mais espaço em disco, e como projetar índices compostos, parciais e de cobertura. É a ferramenta que mais impacta o desempenho de um banco, e escolhas ruins (ordem das colunas, baixa seletividade) levam o otimizador a ignorar o índice.","level":"junior","difficulty":3,"position":5,"prerequisites":["sql-select-e-join","fund-complexidade-big-o"],"resources":[{"name":"PostgreSQL — Documentação: Indexes","url":"https://www.postgresql.org/docs/current/indexes.html"},{"name":"Use The Index, Luke (guia online gratuito)","url":"https://use-the-index-luke.com/"},{"name":"PostgreSQL — Documentação: Multicolumn Indexes","url":"https://www.postgresql.org/docs/current/indexes-multicolumn.html"},{"name":"SQLite — Query Planning","url":"https://www.sqlite.org/queryplanner.html"}],"checklist":[{"key":"explicar-btree","text":"Consigo explicar como um índice B-tree acelera uma consulta e qual o custo nas escritas."},{"key":"ordem-colunas-indice-composto","text":"Sei definir a ordem das colunas em um índice composto e explicar a regra do prefixo mais à esquerda."},{"key":"diagnosticar-indice-ignorado","text":"Consigo identificar por que uma consulta não usa um índice (função aplicada à coluna, tipos incompatíveis, LIKE '%texto', baixa seletividade)."},{"key":"indices-parciais-e-cobertura","text":"Sei quando usar índice parcial (filtrado), índice de cobertura (covering) e índice UNIQUE, e o que cada um resolve."},{"key":"medir-ganho-do-indice","text":"Já criei um índice para uma consulta lenta (incluindo colunas de chave estrangeira) e medi o ganho antes e depois."},{"key":"custo-de-indices-em-excesso","text":"Sei listar os custos de indexar demais (escrita mais lenta, espaço em disco, manutenção) e como encontrar índices não utilizados."}]},{"track":"banco-de-dados-sql","slug":"sql-transacoes-e-acid","title":"Transações e ACID","description":"Entender o que é uma transação e como atomicidade, consistência, isolamento e durabilidade protegem os dados contra falhas e concorrência. Cobre BEGIN/COMMIT/ROLLBACK, savepoints, o papel do WAL (write-ahead log) na durabilidade e por que manter as transações curtas.","level":"mid","difficulty":4,"position":6,"prerequisites":["sql-modelo-relacional","sql-select-e-join"],"resources":[{"name":"PostgreSQL — Tutorial: Transactions","url":"https://www.postgresql.org/docs/current/tutorial-transactions.html"},{"name":"PostgreSQL — Documentação: Concurrency Control (MVCC)","url":"https://www.postgresql.org/docs/current/mvcc.html"},{"name":"SQLite — Atomic Commit In SQLite","url":"https://www.sqlite.org/atomiccommit.html"},{"name":"Livro: Designing Data-Intensive Applications (Kleppmann) — Transações"}],"checklist":[{"key":"explicar-acid","text":"Consigo explicar cada propriedade do ACID com um exemplo prático, como a transferência entre duas contas bancárias."},{"key":"usar-begin-commit-rollback","text":"Já usei BEGIN, COMMIT, ROLLBACK e SAVEPOINT e sei o que acontece com a transação quando um erro ocorre no meio dela."},{"key":"explicar-wal","text":"Sei explicar como o write-ahead log (WAL/redo log) garante a durabilidade e permite a recuperação após uma falha."},{"key":"autocommit-e-ddl","text":"Sei como o autocommit funciona no meu SGBD e se comandos DDL são transacionais (no PostgreSQL e no SQLite o DDL pode ser revertido; no MySQL ele confirma a transação implicitamente)."},{"key":"transacoes-curtas","text":"Consigo explicar por que transações longas, ou com chamadas externas (HTTP, filas) dentro delas, causam problemas de locks e de desempenho."}]},{"track":"banco-de-dados-sql","slug":"sql-isolamento-e-locks","title":"Isolamento e locks","description":"Estudar os níveis de isolamento (READ COMMITTED, REPEATABLE READ, SERIALIZABLE), as anomalias que cada um previne e como MVCC e locks de linha implementam isso. Inclui SELECT ... FOR UPDATE, SKIP LOCKED, deadlocks e controle de concorrência otimista versus pessimista, essenciais para evitar condições de corrida em sistemas com muitos acessos simultâneos.","level":"mid","difficulty":4,"position":7,"prerequisites":["sql-transacoes-e-acid","sql-indices"],"resources":[{"name":"PostgreSQL — Documentação: Transaction Isolation","url":"https://www.postgresql.org/docs/current/transaction-iso.html"},{"name":"PostgreSQL — Documentação: Explicit Locking","url":"https://www.postgresql.org/docs/current/explicit-locking.html"},{"name":"MySQL — Documentação oficial (InnoDB Locking e níveis de isolamento)","url":"https://dev.mysql.com/doc/"},{"name":"Jepsen — Consistency Models","url":"https://jepsen.io/consistency"}],"checklist":[{"key":"descrever-anomalias","text":"Consigo descrever dirty read, non-repeatable read, phantom read e write skew, com um exemplo de cada."},{"key":"nivel-de-isolamento-padrao","text":"Sei qual é o nível de isolamento padrão do meu SGBD (por exemplo, READ COMMITTED no PostgreSQL e REPEATABLE READ no MySQL/InnoDB) e o que ele garante."},{"key":"explicar-mvcc","text":"Consigo explicar como o MVCC permite que leituras não bloqueiem escritas e o que são versões de linha."},{"key":"usar-for-update","text":"Já usei SELECT ... FOR UPDATE (e SKIP LOCKED em filas de trabalho) para evitar uma condição de corrida em um fluxo real."},{"key":"diagnosticar-deadlock","text":"Consigo reproduzir e diagnosticar um deadlock lendo o log ou as views de locks do banco, e sei reduzir sua ocorrência (por exemplo, acessando linhas sempre na mesma ordem)."},{"key":"otimista-vs-pessimista","text":"Sei comparar controle de concorrência otimista (coluna de versão) e pessimista (locks) e escolher entre eles para um caso concreto."}]},{"track":"banco-de-dados-sql","slug":"sql-explain-e-otimizacao","title":"EXPLAIN e otimização","description":"Ler planos de execução com EXPLAIN e EXPLAIN ANALYZE para descobrir por que uma consulta é lenta (varreduras sequenciais, estimativas erradas, ordenações e junções custosas). Cobre estatísticas do otimizador, reescrita de consultas e o ciclo medir, alterar e medir de novo, para otimizar com evidências em vez de palpites.","level":"mid","difficulty":4,"position":8,"prerequisites":["sql-select-e-join","sql-indices"],"resources":[{"name":"PostgreSQL — Documentação: Using EXPLAIN","url":"https://www.postgresql.org/docs/current/using-explain.html"},{"name":"PostgreSQL — Documentação: Performance Tips","url":"https://www.postgresql.org/docs/current/performance-tips.html"},{"name":"explain.depesz.com — visualizador de planos do PostgreSQL","url":"https://explain.depesz.com/"},{"name":"Livro: High Performance MySQL (Schwartz, Zaitsev e Tkachenko)"}],"checklist":[{"key":"ler-plano-de-execucao","text":"Consigo ler a saída de EXPLAIN e identificar os principais tipos de nó do plano (varredura sequencial, varredura por índice, nested loop, hash join, sort)."},{"key":"usar-explain-analyze","text":"Sei usar EXPLAIN ANALYZE com cuidado (ele executa a consulta) e comparar linhas estimadas e reais para encontrar estatísticas desatualizadas."},{"key":"otimizar-consulta-lenta","text":"Já otimizei uma consulta lenta medindo o tempo antes e depois (índice, reescrita ou ajuste de JOIN) e registrei o ganho."},{"key":"atualizar-estatisticas","text":"Sei qual o papel das estatísticas do otimizador e quando executar ANALYZE (ou o equivalente no meu SGBD)."},{"key":"paginacao-e-n-mais-um","text":"Consigo identificar o problema N+1 e a paginação ineficiente com OFFSET grande, e propor alternativas (consulta em lote, paginação por keyset)."},{"key":"encontrar-consultas-custosas","text":"Sei encontrar as consultas mais custosas usando o slow query log, o pg_stat_statements ou o Performance Schema do MySQL."}]},{"track":"banco-de-dados-sql","slug":"sql-migracoes-seguras","title":"Migrações seguras","description":"Evoluir o esquema do banco sem derrubar a aplicação, usando migrações versionadas e o padrão expandir/contrair (expand-contract). Cobre operações que travam tabelas grandes, criação de índices online, backfills em lotes e planos de rollback, que evitam indisponibilidade durante os deploys.","level":"mid","difficulty":3,"position":9,"prerequisites":["sql-modelagem-e-er","sql-indices"],"resources":[{"name":"PostgreSQL — Documentação: ALTER TABLE","url":"https://www.postgresql.org/docs/current/sql-altertable.html"},{"name":"PostgreSQL — Documentação: CREATE INDEX (opção CONCURRENTLY)","url":"https://www.postgresql.org/docs/current/sql-createindex.html"},{"name":"Martin Fowler — Evolutionary Database Design","url":"https://martinfowler.com/articles/evodb.html"},{"name":"Strong Migrations — operações perigosas e alternativas seguras (README)","url":"https://github.com/ankane/strong_migrations"}],"checklist":[{"key":"versionar-esquema","text":"Já versionei o esquema com uma ferramenta de migrações (Flyway, Liquibase, Alembic ou similar) e sei por que não se altera uma migração já aplicada."},{"key":"aplicar-expandir-contrair","text":"Consigo executar uma mudança incompatível (como renomear uma coluna) em etapas de expandir e contrair, mantendo as versões antiga e nova do código funcionando."},{"key":"identificar-ddl-bloqueante","text":"Sei identificar quais comandos ALTER TABLE reescrevem a tabela ou seguram locks longos no meu SGBD e como contorná-los."},{"key":"criar-indice-sem-bloqueio","text":"Sei criar índices sem bloquear escritas (CREATE INDEX CONCURRENTLY no PostgreSQL, DDL online no MySQL)."},{"key":"backfill-em-lotes","text":"Já fiz um backfill de dados em lotes pequenos, sem manter uma transação gigante aberta, acompanhando o progresso."},{"key":"plano-de-rollback","text":"Sei escrever um plano de rollback e de validação para cada migração e reconhecer quando a reversão não é possível (como ao descartar uma coluna)."}]},{"track":"banco-de-dados-sql","slug":"sql-window-functions-e-ctes","title":"Window functions e CTEs","description":"Usar funções de janela (ROW_NUMBER, RANK, LAG/LEAD, SUM OVER) para rankings, totais acumulados e comparações entre linhas sem colapsar o resultado, e CTEs (WITH) para organizar consultas complexas. Inclui CTEs recursivas para hierarquias e a disponibilidade de window functions em MySQL (8.0+) e SQLite (3.25+).","level":"mid","difficulty":4,"position":10,"prerequisites":["sql-select-e-join","sql-agregacoes-e-group-by"],"resources":[{"name":"PostgreSQL — Tutorial: Window Functions","url":"https://www.postgresql.org/docs/current/tutorial-window.html"},{"name":"PostgreSQL — Documentação: Window Functions (referência)","url":"https://www.postgresql.org/docs/current/functions-window.html"},{"name":"PostgreSQL — Documentação: WITH Queries (CTEs)","url":"https://www.postgresql.org/docs/current/queries-with.html"},{"name":"SQLite — Window Functions","url":"https://www.sqlite.org/windowfunctions.html"}],"checklist":[{"key":"diferenciar-janela-de-group-by","text":"Consigo explicar a diferença entre agregar com GROUP BY e usar uma função de janela com OVER."},{"key":"top-n-por-grupo","text":"Já resolvi um problema de top N por grupo usando ROW_NUMBER() ou RANK() com PARTITION BY."},{"key":"lag-lead-e-acumulados","text":"Sei usar LAG, LEAD e somas acumuladas (SUM OVER com ORDER BY) para comparar períodos e calcular totais correntes."},{"key":"frames-de-janela","text":"Sei explicar como o frame (ROWS ou RANGE, UNBOUNDED PRECEDING) altera o resultado de uma função de janela."},{"key":"refatorar-com-ctes","text":"Consigo refatorar uma consulta aninhada em CTEs legíveis e sei que a materialização de CTEs varia entre SGBDs e versões."},{"key":"cte-recursiva","text":"Já escrevi uma CTE recursiva (por exemplo, árvore de categorias ou organograma) com condição de parada."}]},{"track":"banco-de-dados-sql","slug":"sql-nosql-e-redis","title":"NoSQL e Redis (quando usar)","description":"Conhecer as famílias de bancos NoSQL (chave-valor, documento, colunar e grafo) e seus trade-offs frente ao relacional em esquema, escala, consistência e consultas. O foco prático é Redis (cache, sessões, rate limit e filas leves) e saber decidir quando o banco relacional ainda é a melhor escolha.","level":"mid","difficulty":3,"position":11,"prerequisites":["sql-modelagem-e-er","sql-normalizacao"],"resources":[{"name":"Redis — Documentação oficial","url":"https://redis.io/docs/"},{"name":"MongoDB — Documentação oficial","url":"https://www.mongodb.com/docs/"},{"name":"PostgreSQL — Documentação: JSON Types","url":"https://www.postgresql.org/docs/current/datatype-json.html"},{"name":"Livro: Designing Data-Intensive Applications (Kleppmann) — Modelos de dados"}],"checklist":[{"key":"classificar-familias-nosql","text":"Consigo citar as famílias de bancos NoSQL (chave-valor, documento, colunar e grafo) e um caso de uso típico de cada uma."},{"key":"justificar-escolha-sql-vs-nosql","text":"Consigo justificar a escolha entre banco relacional e NoSQL usando critérios como padrão de acesso, consistência, volume e necessidade de JOINs e transações."},{"key":"cache-aside-com-redis","text":"Já implementei cache com Redis (cache-aside) definindo TTL e estratégia de invalidação, e sei descrever o risco de cache stampede."},{"key":"estruturas-de-dados-redis","text":"Sei quando usar as estruturas do Redis (string, hash, list, set, sorted set) e dou um exemplo de uso para cada uma."},{"key":"limites-do-redis-como-fonte-de-verdade","text":"Sei os limites do Redis como fonte de verdade: dados em memória, opções de persistência (RDB e AOF) e o que pode ser perdido em uma falha."},{"key":"json-no-relacional","text":"Sei que colunas JSON/JSONB em um banco relacional podem atender parte dos casos de esquema flexível sem adotar outro banco."}]},{"track":"banco-de-dados-sql","slug":"sql-replicacao-particionamento","title":"Replicação, particionamento","description":"Escalar e tornar o banco resiliente com replicação síncrona e assíncrona, réplicas de leitura e failover, além de particionamento de tabelas e noções de sharding. O foco está nos trade-offs de consistência (replication lag), no impacto sobre as consultas e na operação em produção.","level":"senior","difficulty":5,"position":12,"prerequisites":["sql-transacoes-e-acid","sql-indices","sql-explain-e-otimizacao"],"resources":[{"name":"PostgreSQL — Documentação: High Availability, Load Balancing, and Replication","url":"https://www.postgresql.org/docs/current/high-availability.html"},{"name":"PostgreSQL — Documentação: Table Partitioning","url":"https://www.postgresql.org/docs/current/ddl-partitioning.html"},{"name":"MySQL — Documentação oficial (capítulo Replication)","url":"https://dev.mysql.com/doc/"},{"name":"Livro: Designing Data-Intensive Applications (Kleppmann) — Replicação e Particionamento"}],"checklist":[{"key":"comparar-replicacao-sincrona-assincrona","text":"Consigo comparar replicação síncrona e assíncrona quanto a durabilidade, latência de escrita e risco de perda de dados em um failover."},{"key":"explicar-replication-lag","text":"Sei explicar o replication lag e suas consequências (ler dados desatualizados, não enxergar a própria escrita) e como mitigá-las na aplicação."},{"key":"operar-replica-e-failover","text":"Já configurei (ao menos em ambiente de teste) uma réplica de leitura e executei um failover, manual ou automático."},{"key":"escolher-estrategia-de-particionamento","text":"Sei diferenciar particionamento por faixa, lista e hash e escolher uma chave de partição adequada ao padrão de acesso (lembrando que ela costuma precisar fazer parte das chaves únicas)."},{"key":"verificar-partition-pruning","text":"Consigo verificar com EXPLAIN que uma consulta aproveita a poda de partições (partition pruning) e sei quais consultas não a aproveitam."},{"key":"particionamento-vs-sharding","text":"Sei explicar a diferença entre particionamento em um único servidor e sharding entre servidores, e os custos do sharding (JOINs entre shards, transações distribuídas, rebalanceamento)."}]},{"track":"qualidade","slug":"qual-testes-unitarios","title":"Testes unitários","description":"Testes unitários verificam o comportamento de uma unidade pequena de código (função, classe ou método) de forma isolada, rápida e determinística. Dominar o padrão Arrange-Act-Assert, os dublês de teste (stubs, mocks e fakes) e a escolha de casos de borda dá segurança para evoluir o código sem medo de regressões. O foco é escrever testes legíveis em Pest (PHP) e Vitest (JavaScript) que só falhem quando o comportamento muda.","level":"junior","difficulty":2,"position":0,"prerequisites":[],"resources":[{"name":"Pest — Documentação","url":"https://pestphp.com/docs"},{"name":"Vitest — Guia","url":"https://vitest.dev/guide/"},{"name":"Martin Fowler — Unit Test","url":"https://martinfowler.com/bliki/UnitTest.html"},{"name":"Livro: The Art of Unit Testing — Roy Osherove"}],"checklist":[{"key":"escrever-teste-aaa","text":"Consigo escrever um teste unitário no padrão Arrange-Act-Assert para uma função pura."},{"key":"nomear-testes","text":"Sei nomear testes de modo que o nome descreva o cenário e o resultado esperado, sem precisar ler o corpo."},{"key":"casos-de-borda","text":"Consigo identificar e cobrir casos de borda, entradas inválidas e caminhos de erro de uma função."},{"key":"dubles-de-teste","text":"Sei explicar a diferença entre stub, mock, spy e fake e escolher o dublê adequado para isolar uma dependência."},{"key":"testes-deterministicos","text":"Sei eliminar a instabilidade causada por relógio, aleatoriedade, rede e ordem de execução, deixando o teste determinístico."},{"key":"rodar-pest-vitest","text":"Sei rodar toda a suíte, um arquivo ou um único teste com Pest ou Vitest e interpretar a saída de uma falha."}]},{"track":"qualidade","slug":"qual-testes-integracao","title":"Testes de integração","description":"Testes de integração verificam que módulos e camadas funcionam juntos de verdade: repositórios com banco de dados real, rotas HTTP, filas e clientes de APIs externas. Eles pegam falhas de configuração, de contrato e de SQL que testes unitários com dublês não enxergam, ao custo de serem mais lentos e exigirem um ambiente controlado. Entender a pirâmide de testes ajuda a decidir quantos escrever e onde.","level":"junior","difficulty":3,"position":1,"prerequisites":["qual-testes-unitarios"],"resources":[{"name":"Martin Fowler — Integration Test","url":"https://martinfowler.com/bliki/IntegrationTest.html"},{"name":"The Practical Test Pyramid — Ham Vocke","url":"https://martinfowler.com/articles/practical-test-pyramid.html"},{"name":"Testcontainers","url":"https://testcontainers.com/"},{"name":"Livro: Unit Testing Principles, Practices, and Patterns — Vladimir Khorikov"}],"checklist":[{"key":"banco-de-dados-real","text":"Consigo escrever um teste de integração para um repositório ou consulta usando um banco de dados real (local ou em container)."},{"key":"rota-http","text":"Sei testar uma rota HTTP validando status, corpo da resposta e efeitos colaterais, como registros gravados no banco."},{"key":"isolar-estado","text":"Sei isolar o estado entre testes (transação com rollback, truncate ou banco efêmero) para que a ordem de execução não importe."},{"key":"api-externa-simulada","text":"Consigo substituir uma API externa por um fake ou servidor simulado e testar timeouts e respostas de erro."},{"key":"piramide-de-testes","text":"Sei explicar a pirâmide de testes e justificar o que cobrir com testes unitários e o que cobrir com testes de integração."}]},{"track":"qualidade","slug":"qual-tdd","title":"TDD","description":"TDD (Test-Driven Development) é a prática de escrever primeiro um teste que falha, fazer o teste passar com o código mais simples possível e então refatorar, no ciclo Red-Green-Refactor. Ela guia o design para código mais simples e desacoplado e deixa uma suíte de testes de regressão como subproduto. Também é preciso saber quando TDD rende menos, como em spikes exploratórios e protótipos de interface.","level":"junior","difficulty":3,"position":2,"prerequisites":["qual-testes-unitarios","qual-clean-code"],"resources":[{"name":"Martin Fowler — Test Driven Development","url":"https://martinfowler.com/bliki/TestDrivenDevelopment.html"},{"name":"Vitest — Guia","url":"https://vitest.dev/guide/"},{"name":"Livro: Test-Driven Development: By Example — Kent Beck"},{"name":"Livro: Growing Object-Oriented Software, Guided by Tests — Steve Freeman e Nat Pryce"}],"checklist":[{"key":"ciclo-red-green-refactor","text":"Consigo executar o ciclo Red-Green-Refactor em passos pequenos, sem escrever código de produção antes de ter um teste falhando."},{"key":"kata-completa","text":"Já resolvi uma kata (como FizzBuzz, String Calculator ou Bowling Game) usando TDD do início ao fim."},{"key":"falha-pelo-motivo-certo","text":"Sei confirmar que o teste falha pelo motivo certo antes de escrever a implementação."},{"key":"fake-it-triangulacao","text":"Sei usar 'fake it' e triangulação para chegar de forma incremental a uma implementação geral."},{"key":"bug-primeiro-teste","text":"Já corrigi um bug escrevendo antes um teste que o reproduz e só então alterando o código."},{"key":"limites-do-tdd","text":"Sei apontar situações em que TDD rende menos, como spikes exploratórios e protótipos de interface, e como adaptar a prática."}]},{"track":"qualidade","slug":"qual-clean-code","title":"Clean code","description":"Clean code reúne práticas para escrever código legível e fácil de mudar: nomes que revelam intenção, funções pequenas com uma única responsabilidade, poucos parâmetros e ausência de duplicação. Como o código é lido muito mais vezes do que é escrito, a clareza reduz bugs e o custo de manutenção. O escopo inclui reconhecer code smells e aplicar DRY, KISS, YAGNI e SOLID com bom senso, sem criar abstrações prematuras.","level":"junior","difficulty":2,"position":3,"prerequisites":[],"resources":[{"name":"Livro: Clean Code — Robert C. Martin"},{"name":"Livro: A Philosophy of Software Design — John Ousterhout"},{"name":"Martin Fowler — Code Smell","url":"https://martinfowler.com/bliki/CodeSmell.html"},{"name":"clean-code-javascript — Ryan McDermott (GitHub)","url":"https://github.com/ryanmcdermott/clean-code-javascript"}],"checklist":[{"key":"nomes-reveladores","text":"Consigo renomear variáveis, funções e classes para que revelem a intenção sem depender de comentários."},{"key":"funcoes-pequenas","text":"Consigo quebrar uma função longa em funções pequenas, com uma única responsabilidade e poucos parâmetros."},{"key":"reconhecer-code-smells","text":"Sei reconhecer ao menos cinco code smells comuns, como método longo, duplicação, lista longa de parâmetros, feature envy e números mágicos."},{"key":"dry-kiss-yagni","text":"Sei explicar DRY, KISS e YAGNI e identificar quando aplicá-los de forma exagerada gera abstração prematura."},{"key":"responsabilidade-e-dependencias","text":"Sei explicar os princípios da responsabilidade única e da inversão de dependência com exemplos do meu próprio código."},{"key":"comentarios-uteis","text":"Sei diferenciar comentários úteis, que explicam o porquê, de comentários que repetem o código ou disfarçam código confuso."}]},{"track":"qualidade","slug":"qual-code-review","title":"Code review","description":"Code review é a revisão das mudanças por outra pessoa antes do merge, com o objetivo de achar defeitos, melhorar o design e espalhar conhecimento pelo time. Uma boa revisão combina pull requests pequenos e bem descritos, feedback objetivo e respeitoso e critérios claros do que bloqueia o merge e do que é apenas sugestão. Vale tanto para quem revisa quanto para quem tem o código revisado.","level":"junior","difficulty":3,"position":4,"prerequisites":["qual-clean-code"],"resources":[{"name":"Google Engineering Practices — Code Review","url":"https://google.github.io/eng-practices/review/"},{"name":"Martin Fowler — Ship / Show / Ask","url":"https://martinfowler.com/articles/ship-show-ask.html"},{"name":"GitHub Docs — Pull requests","url":"https://docs.github.com/en/pull-requests"},{"name":"Livro: Software Engineering at Google — Titus Winters, Tom Manshreck e Hyrum Wright","url":"https://abseil.io/resources/swe-book"}],"checklist":[{"key":"pr-pequeno-e-descrito","text":"Consigo abrir um pull request pequeno e focado, com descrição que explica o porquê da mudança, como testá-la e quais são os riscos."},{"key":"revisar-pr-completo","text":"Já revisei o pull request de outra pessoa verificando correção, testes, legibilidade, segurança e impacto em desempenho."},{"key":"feedback-construtivo","text":"Sei escrever comentários objetivos e respeitosos, distinguindo o que bloqueia o merge do que é sugestão ou detalhe menor."},{"key":"receber-feedback","text":"Sei responder a comentários de revisão sem levar para o lado pessoal, justificando minhas decisões ou ajustando o código."},{"key":"checklist-pessoal","text":"Já montei um checklist pessoal de revisão (tratamento de erros, casos de borda, nomes, testes e migrações) e o uso nas minhas revisões."},{"key":"automatizar-o-mecanico","text":"Sei delegar a linters, formatadores e à CI as checagens mecânicas para que a revisão humana foque em design e lógica de negócio."}]},{"track":"qualidade","slug":"qual-refatoracao","title":"Refatoração","description":"Refatoração é alterar a estrutura interna do código sem mudar o comportamento observável, em passos pequenos e protegidos por testes. Técnicas como extrair método, renomear, introduzir objeto de parâmetro e substituir condicional por polimorfismo melhoram o design e reduzem o custo de mudanças futuras. É a prática que mantém uma base de código saudável ao longo do tempo, inclusive em código legado.","level":"junior","difficulty":3,"position":5,"prerequisites":["qual-testes-unitarios","qual-clean-code"],"resources":[{"name":"Refactoring Guru — Refatoração","url":"https://refactoring.guru/pt-br/refactoring"},{"name":"Refactoring.com — Catálogo de refatorações (Martin Fowler)","url":"https://refactoring.com/catalog/"},{"name":"Livro: Refactoring: Improving the Design of Existing Code — Martin Fowler"},{"name":"Livro: Working Effectively with Legacy Code — Michael Feathers"}],"checklist":[{"key":"refatorar-com-testes-verdes","text":"Consigo refatorar um trecho de código mantendo a suíte de testes verde a cada passo pequeno."},{"key":"refatoracoes-da-ide","text":"Sei aplicar as refatorações Extract Method, Rename, Inline e Extract Variable com as ferramentas automáticas da IDE."},{"key":"testes-de-caracterizacao","text":"Sei escrever testes de caracterização para cobrir código legado antes de refatorá-lo."},{"key":"smell-para-tecnica","text":"Sei relacionar code smells (método longo, classe grande, condicionais repetidas) à técnica de refatoração adequada para cada caso."},{"key":"commits-separados","text":"Sei manter refatorações em commits ou pull requests separados de mudanças de comportamento, para facilitar revisão e reversão."}]},{"track":"qualidade","slug":"qual-linters-analise-estatica","title":"Linters e análise estática","description":"Linters, formatadores e analisadores estáticos inspecionam o código sem executá-lo para apontar erros de tipo, variáveis não usadas, vulnerabilidades e violações de estilo. Ferramentas como ESLint, Prettier, PHPStan e PHP-CS-Fixer automatizam convenções e pegam bugs cedo, antes da revisão e da produção. A adoção gradual, com baseline e níveis de rigor, permite usá-las até em bases legadas.","level":"junior","difficulty":2,"position":6,"prerequisites":["qual-clean-code"],"resources":[{"name":"ESLint — Documentação","url":"https://eslint.org/docs/latest/"},{"name":"Prettier","url":"https://prettier.io/"},{"name":"PHPStan — Primeiros passos","url":"https://phpstan.org/user-guide/getting-started"},{"name":"PHP CS Fixer (GitHub)","url":"https://github.com/PHP-CS-Fixer/PHP-CS-Fixer"}],"checklist":[{"key":"configurar-linter","text":"Já configurei um linter ou analisador estático (ESLint, PHPStan ou similar) em um projeto, fixando a versão e o conjunto de regras."},{"key":"formatador-e-hook","text":"Sei configurar um formatador automático (Prettier, PHP-CS-Fixer ou similar) e executá-lo no editor e em um hook de pre-commit."},{"key":"linter-formatador-tipos","text":"Sei explicar a diferença entre formatador, linter e analisador estático de tipos e o tipo de problema que cada um detecta."},{"key":"adocao-gradual","text":"Sei adotar uma ferramenta em código legado de forma gradual, usando baseline, níveis de rigor ou regras por diretório."},{"key":"falsos-positivos","text":"Sei tratar um falso positivo desativando a regra de forma pontual e justificada, em vez de desligá-la globalmente."}]},{"track":"qualidade","slug":"qual-ci-github-actions","title":"CI com GitHub Actions","description":"Integração contínua é a prática de integrar mudanças com frequência e validá-las automaticamente a cada push ou pull request. Com GitHub Actions você define workflows em YAML que instalam dependências, rodam linters e testes, geram artefatos e bloqueiam o merge quando algo falha. O objetivo é um pipeline rápido, confiável e seguro, com cache, matriz de versões e segredos bem gerenciados.","level":"mid","difficulty":3,"position":7,"prerequisites":["qual-testes-unitarios","qual-testes-integracao","qual-linters-analise-estatica","fund-git-basico"],"resources":[{"name":"GitHub Actions — Documentação","url":"https://docs.github.com/en/actions"},{"name":"Martin Fowler — Continuous Integration","url":"https://martinfowler.com/articles/continuousIntegration.html"},{"name":"setup-php — GitHub Action para PHP (GitHub)","url":"https://github.com/shivammathur/setup-php"},{"name":"actions/setup-node — GitHub Action para Node.js (GitHub)","url":"https://github.com/actions/setup-node"}],"checklist":[{"key":"workflow-de-pr","text":"Já criei um workflow do GitHub Actions que roda linter e testes a cada pull request."},{"key":"cache-de-dependencias","text":"Sei configurar cache de dependências (Composer e npm) para reduzir o tempo da pipeline."},{"key":"matriz-de-versoes","text":"Sei usar uma matriz de build para testar mais de uma versão de PHP ou de Node.js."},{"key":"segredos-e-permissoes","text":"Sei guardar segredos em GitHub Secrets e restringir as permissões do GITHUB_TOKEN ao mínimo necessário."},{"key":"protecao-de-branch","text":"Sei configurar regras de proteção de branch para exigir checks verdes antes do merge."},{"key":"pipeline-rapida","text":"Sei diagnosticar uma pipeline lenta ou instável e reduzir seu tempo com paralelismo, cache e execução condicional."}]},{"track":"qualidade","slug":"qual-cd-estrategias-release","title":"CD e estratégias de release","description":"Entrega contínua mantém o software sempre pronto para ir a produção, e o deploy contínuo vai além e publica automaticamente cada mudança aprovada. Estratégias como rolling update, blue-green, canary e feature flags reduzem o risco de uma release e permitem rollback rápido. O tema inclui migrações de banco compatíveis entre versões e métricas DORA para medir a saúde do processo de entrega.","level":"mid","difficulty":4,"position":8,"prerequisites":["qual-ci-github-actions","qual-testes-e2e"],"resources":[{"name":"Martin Fowler — Continuous Delivery","url":"https://martinfowler.com/bliki/ContinuousDelivery.html"},{"name":"Martin Fowler — Blue Green Deployment","url":"https://martinfowler.com/bliki/BlueGreenDeployment.html"},{"name":"Feature Toggles (aka Feature Flags) — Pete Hodgson","url":"https://martinfowler.com/articles/feature-toggles.html"},{"name":"Livro: Continuous Delivery — Jez Humble e David Farley"}],"checklist":[{"key":"delivery-vs-deployment","text":"Sei explicar a diferença entre entrega contínua e deploy contínuo e quando cada um é apropriado."},{"key":"pipeline-de-cd","text":"Já montei um pipeline que faz deploy automático em staging após os testes passarem e exige aprovação manual para produção."},{"key":"estrategias-de-release","text":"Sei comparar rolling update, blue-green e canary quanto a risco, custo e velocidade de rollback."},{"key":"feature-flags","text":"Já usei feature flags para separar deploy de release e sei o risco de deixá-las acumuladas no código."},{"key":"rollback-e-migracoes","text":"Sei planejar um rollback e escrever migrações de banco compatíveis com a versão antiga e a nova (expand/contract)."},{"key":"metricas-dora","text":"Sei explicar as métricas DORA (frequência de deploy, lead time, taxa de falha de mudanças e tempo de recuperação) e como coletá-las."}]},{"track":"qualidade","slug":"qual-testes-e2e","title":"Testes E2E","description":"Testes end-to-end exercitam o sistema completo pela perspectiva do usuário: um navegador real navega, preenche formulários e valida o resultado na tela. Ferramentas como Playwright e Cypress cobrem os fluxos críticos de negócio, mas são mais lentas e frágeis que os testes de camadas inferiores, então devem ser poucas e bem escolhidas. A estabilidade (seletores resilientes, esperas automáticas e dados de teste controlados) é o principal desafio.","level":"mid","difficulty":3,"position":9,"prerequisites":["qual-testes-integracao"],"resources":[{"name":"Playwright — Documentação","url":"https://playwright.dev/"},{"name":"Cypress — Documentação","url":"https://docs.cypress.io/"},{"name":"Martin Fowler — Eradicating Non-Determinism in Tests","url":"https://martinfowler.com/articles/nonDeterminism.html"},{"name":"Martin Fowler — Test Pyramid","url":"https://martinfowler.com/bliki/TestPyramid.html"}],"checklist":[{"key":"primeiro-teste-e2e","text":"Já escrevi um teste E2E com Playwright (ou Cypress) para um fluxo crítico, como login ou checkout."},{"key":"seletores-resilientes","text":"Sei escolher seletores resilientes (papéis, rótulos e data-testid) em vez de classes CSS ou XPath frágeis."},{"key":"esperas-automaticas","text":"Sei evitar esperas fixas (sleep), usando esperas automáticas e asserções com retry."},{"key":"dados-de-teste","text":"Sei preparar e limpar dados de teste de forma determinística (seeds, API de setup ou banco efêmero) a cada execução."},{"key":"depurar-na-ci","text":"Sei executar os testes E2E na CI e usar traces, vídeos e screenshots para depurar falhas."},{"key":"escolher-fluxos","text":"Sei decidir quais fluxos merecem teste E2E e quais devem ser cobertos por testes de camadas inferiores."}]},{"track":"qualidade","slug":"qual-cobertura-mutation-testing","title":"Cobertura e mutation testing","description":"Cobertura de código mede quais linhas e ramos são executados pelos testes, mas não garante que eles realmente verifiquem o comportamento. O mutation testing injeta pequenas falhas (mutantes) no código e checa se a suíte as detecta, medindo a eficácia real dos testes por meio do mutation score. Saber interpretar essas métricas, evitar a cobertura como meta cega e aplicá-las onde mais importa é uma habilidade de nível sênior.","level":"senior","difficulty":4,"position":10,"prerequisites":["qual-testes-unitarios","qual-testes-integracao","qual-ci-github-actions"],"resources":[{"name":"Martin Fowler — Test Coverage","url":"https://martinfowler.com/bliki/TestCoverage.html"},{"name":"Infection — Mutation testing para PHP","url":"https://infection.github.io/"},{"name":"StrykerJS — Mutation testing para JavaScript","url":"https://stryker-mutator.io/"},{"name":"Pest — Documentação","url":"https://pestphp.com/docs"}],"checklist":[{"key":"relatorio-de-cobertura","text":"Consigo gerar um relatório de cobertura de linhas e ramos com Pest/PHPUnit ou Vitest e interpretá-lo."},{"key":"cobertura-nao-e-qualidade","text":"Sei explicar por que 100% de cobertura não significa testes bons, com um exemplo de teste que executa o código sem verificar nada."},{"key":"rodar-mutation-testing","text":"Já executei uma ferramenta de mutation testing (Infection, StrykerJS ou Pest) e analisei os mutantes sobreviventes."},{"key":"matar-mutantes","text":"Sei transformar um mutante sobrevivente em um teste mais forte ou reconhecer um mutante equivalente."},{"key":"quality-gate","text":"Sei definir metas de cobertura realistas por tipo de módulo e aplicar quality gates na CI, como cobertura mínima no código novo."},{"key":"custo-do-mutation","text":"Sei reduzir o custo do mutation testing executando-o apenas em arquivos alterados ou em módulos críticos."}]},{"track":"qualidade","slug":"qual-divida-tecnica","title":"Dívida técnica","description":"Dívida técnica é o custo futuro assumido ao escolher uma solução rápida ou imperfeita hoje, e pode ser deliberada ou acidental, prudente ou imprudente. Gerenciá-la exige tornar a dívida visível, estimar os juros (impacto na velocidade e no risco), priorizar o pagamento junto ao roadmap de produto e comunicar o trade-off para pessoas não técnicas. Quem atua como sênior sabe quando assumir dívida de propósito e como impedir que ela paralise o time.","level":"senior","difficulty":4,"position":11,"prerequisites":["qual-refatoracao","qual-code-review","qual-linters-analise-estatica"],"resources":[{"name":"Martin Fowler — Technical Debt","url":"https://martinfowler.com/bliki/TechnicalDebt.html"},{"name":"Martin Fowler — Technical Debt Quadrant","url":"https://martinfowler.com/bliki/TechnicalDebtQuadrant.html"},{"name":"Martin Fowler — Strangler Fig Application","url":"https://martinfowler.com/bliki/StranglerFigApplication.html"},{"name":"Livro: Software Design X-Rays — Adam Tornhill"}],"checklist":[{"key":"quadrante-da-divida","text":"Sei classificar uma dívida técnica usando o quadrante de Martin Fowler (deliberada ou acidental, prudente ou imprudente)."},{"key":"registrar-divida","text":"Já registrei dívida técnica de forma rastreável (backlog, ADR ou comentário com link) com contexto, impacto e custo estimado."},{"key":"priorizar-pelos-juros","text":"Sei priorizar o pagamento da dívida pelos juros (frequência de mudança, incidentes e lentidão do time) e não por incômodo estético."},{"key":"comunicar-tradeoff","text":"Sei defender o investimento em dívida técnica perante produto e gestão em termos de risco, prazo e custo."},{"key":"pagar-incrementalmente","text":"Já conduzi o pagamento de uma dívida de forma incremental (regra do escoteiro, refatoração contínua ou strangler fig) sem parar a entrega de funcionalidades."},{"key":"medir-a-divida","text":"Sei usar métricas (complexidade ciclomática, churn, duplicação e tempo de ciclo) para acompanhar a evolução da dívida."}]},{"track":"arquitetura-system-design","slug":"arq-principios-solid","title":"Princípios SOLID","description":"Os cinco princípios de design orientado a objetos (responsabilidade única, aberto/fechado, substituição de Liskov, segregação de interfaces e inversão de dependência) que mantêm o código fácil de mudar e de testar. O foco é reconhecer violações em código real, em PHP/Laravel ou TypeScript, e corrigi-las com interfaces pequenas, composição e injeção de dependência.","level":"junior","difficulty":3,"position":0,"prerequisites":["php-poo"],"resources":[{"name":"Livro: Clean Architecture — Robert C. Martin (Parte III, princípios de design)"},{"name":"Martin Fowler — Inversion of Control Containers and the Dependency Injection pattern","url":"https://martinfowler.com/articles/injection.html"},{"name":"Laravel — Service Container (injeção de dependência)","url":"https://laravel.com/framework/docs/container"},{"name":"Martin Fowler — YAGNI (contrapeso ao excesso de abstração)","url":"https://martinfowler.com/bliki/Yagni.html"}],"checklist":[{"key":"explicar-srp","text":"Consigo explicar o princípio da responsabilidade única (SRP) com um exemplo de uma classe minha que acumulava responsabilidades e mostrar como a dividi."},{"key":"aplicar-ocp","text":"Sei trocar um `if/switch` por tipo por polimorfismo (ex.: Strategy) para estender o comportamento sem modificar o código existente (OCP)."},{"key":"violacao-lsp","text":"Consigo dar um exemplo de violação do princípio de substituição de Liskov (LSP) e explicar por que composição era a melhor escolha ali."},{"key":"segregar-interfaces","text":"Já dividi uma interface grande em interfaces menores e coesas, aplicando a segregação de interfaces (ISP)."},{"key":"inverter-dependencia","text":"Já apliquei inversão de dependência (DIP): uma classe de alto nível passou a depender de uma interface, com a implementação injetada pelo construtor ou pelo container."},{"key":"evitar-excesso","text":"Sei dizer quando aplicar SOLID vira excesso de engenharia e por que um pouco de duplicação costuma custar menos que uma abstração prematura."}]},{"track":"arquitetura-system-design","slug":"arq-padroes-criacionais","title":"Padrões de projeto (criacionais)","description":"Os padrões de criação do catálogo GoF (Factory Method, Abstract Factory, Builder, Prototype e Singleton) e o problema de instanciação que cada um resolve. Compara com alternativas modernas, como injeção de dependência e containers, que substituem boa parte do uso de Singleton e de fábricas manuais.","level":"mid","difficulty":3,"position":1,"prerequisites":["arq-principios-solid"],"resources":[{"name":"Refactoring Guru — Padrões criacionais","url":"https://refactoring.guru/pt-br/design-patterns/creational-patterns"},{"name":"Livro: Design Patterns: Elements of Reusable Object-Oriented Software — Gamma, Helm, Johnson e Vlissides (GoF)"},{"name":"Livro: Head First Design Patterns — Eric Freeman e Elisabeth Robson"},{"name":"PHP-FIG — PSR-11: Container Interface","url":"https://www.php-fig.org/psr/psr-11/"}],"checklist":[{"key":"factory-method-vs-abstract-factory","text":"Consigo diferenciar Factory Method de Abstract Factory e escrever um exemplo de cada em código."},{"key":"implementar-builder","text":"Já implementei um Builder para um objeto com muitos parâmetros opcionais (ex.: query, e-mail ou requisição HTTP) e sei explicar o ganho de legibilidade."},{"key":"critica-singleton","text":"Sei explicar por que um Singleton global dificulta testes e como um container de injeção de dependência resolve o mesmo problema."},{"key":"prototype-copia","text":"Consigo explicar o padrão Prototype e a diferença entre cópia rasa e cópia profunda (shallow e deep copy) ao clonar objetos."},{"key":"ver-no-framework","text":"Consigo apontar onde um framework que uso (ex.: Laravel ou Vue) aplica Factory, Builder ou Manager internamente."},{"key":"quando-nao-usar","text":"Sei decidir quando um construtor simples ou uma função fábrica resolve e um padrão criacional seria exagero."}]},{"track":"arquitetura-system-design","slug":"arq-padroes-estruturais-comportamentais","title":"Padrões (estruturais/comportamentais)","description":"Padrões GoF que organizam a composição entre objetos (Adapter, Decorator, Facade, Proxy e Composite) e a divisão de responsabilidades em tempo de execução (Strategy, Observer, Command, Template Method, State e Chain of Responsibility). O objetivo é reconhecê-los em frameworks, como middlewares, eventos e jobs, e aplicá-los só quando simplificam o código.","level":"mid","difficulty":3,"position":2,"prerequisites":["arq-principios-solid","arq-padroes-criacionais"],"resources":[{"name":"Refactoring Guru — Padrões estruturais","url":"https://refactoring.guru/pt-br/design-patterns/structural-patterns"},{"name":"Refactoring Guru — Padrões comportamentais","url":"https://refactoring.guru/pt-br/design-patterns/behavioral-patterns"},{"name":"PHP-FIG — PSR-15: HTTP Server Request Handlers (middleware)","url":"https://www.php-fig.org/psr/psr-15/"},{"name":"Livro: Design Patterns: Elements of Reusable Object-Oriented Software — Gamma, Helm, Johnson e Vlissides (GoF)"}],"checklist":[{"key":"adapter-facade-proxy","text":"Consigo explicar a diferença entre Adapter, Facade e Proxy e já escrevi um Adapter para isolar uma biblioteca ou API externa do resto do código."},{"key":"decorator","text":"Já implementei um Decorator (ex.: cache, log ou retry em volta de um repositório ou cliente HTTP) sem alterar a classe original."},{"key":"strategy","text":"Já substituí condicionais extensas por Strategy e sei trocar a implementação em tempo de execução."},{"key":"observer-eventos","text":"Consigo explicar como o Observer se relaciona com eventos e listeners e já o usei em código meu."},{"key":"chain-middleware","text":"Sei explicar como o Chain of Responsibility aparece em pipelines de middleware (Laravel, Express, PSR-15) e já escrevi um middleware próprio."},{"key":"command-jobs","text":"Consigo relacionar o padrão Command a jobs em fila ou a ações com desfazer (undo)."}]},{"track":"arquitetura-system-design","slug":"arq-arquitetura-em-camadas","title":"Arquitetura em camadas","description":"Organização do sistema em camadas (apresentação, aplicação, domínio e infraestrutura) com regras claras sobre quem pode depender de quem. Cobre onde cada responsabilidade deve ficar, os problemas de controllers e models inchados e como DTOs e serviços de aplicação mantêm as regras de negócio fora do framework.","level":"mid","difficulty":3,"position":3,"prerequisites":["arq-principios-solid"],"resources":[{"name":"Martin Fowler — Presentation Domain Data Layering","url":"https://martinfowler.com/bliki/PresentationDomainDataLayering.html"},{"name":"Martin Fowler — Anemic Domain Model","url":"https://martinfowler.com/bliki/AnemicDomainModel.html"},{"name":"Martin Fowler — Catálogo de padrões de arquitetura corporativa (PoEAA)","url":"https://martinfowler.com/eaaCatalog/"},{"name":"Livro: Clean Architecture — Robert C. Martin"}],"checklist":[{"key":"desenhar-camadas","text":"Consigo desenhar as camadas de um projeto meu e dizer quais dependências entre elas são permitidas e quais são proibidas."},{"key":"regra-fora-do-controller","text":"Já movi regra de negócio de um controller ou model para uma camada de aplicação (ex.: Action, Service ou caso de uso)."},{"key":"dto-na-fronteira","text":"Sei explicar por que não devo expor models ou entidades diretamente na API e já usei DTOs ou API Resources na fronteira."},{"key":"active-record-gordo","text":"Consigo explicar o problema de um Active Record com regra demais e citar alternativas (serviços, objetos de valor, repositórios)."},{"key":"limites-das-camadas","text":"Sei apontar limitações do modelo em camadas, como camadas que só repassam chamadas e domínio acoplado ao banco."}]},{"track":"arquitetura-system-design","slug":"arq-ddd-basico","title":"DDD básico","description":"Domain-Driven Design em nível introdutório: linguagem ubíqua, contextos delimitados (bounded contexts), entidades, objetos de valor, agregados, repositórios e eventos de domínio. O foco é modelar regras de negócio complexas junto com quem entende do negócio, sem cair em modelo anêmico nem aplicar DDD onde um CRUD simples basta.","level":"mid","difficulty":4,"position":4,"prerequisites":["arq-principios-solid","arq-arquitetura-em-camadas","sql-modelagem-e-er"],"resources":[{"name":"Livro: Domain-Driven Design: Tackling Complexity in the Heart of Software — Eric Evans"},{"name":"Livro: Domain-Driven Design Distilled — Vaughn Vernon"},{"name":"Martin Fowler — Bounded Context","url":"https://martinfowler.com/bliki/BoundedContext.html"},{"name":"Martin Fowler — DDD Aggregate","url":"https://martinfowler.com/bliki/DDD_Aggregate.html"}],"checklist":[{"key":"linguagem-ubiqua","text":"Consigo montar um glossário de linguagem ubíqua para um domínio que conheço e usá-lo nos nomes de classes e métodos."},{"key":"entidade-vs-value-object","text":"Sei diferenciar entidade de objeto de valor e já modelei um Value Object imutável (ex.: Dinheiro, E-mail ou CPF)."},{"key":"agregado-e-invariantes","text":"Consigo explicar o que é um agregado, sua raiz e suas invariantes, e já desenhei um (ex.: Pedido com seus itens)."},{"key":"bounded-context","text":"Sei identificar contextos delimitados em um sistema e desenhar um mapa de contextos simples com os relacionamentos entre eles."},{"key":"repositorio-e-evento","text":"Sei a função de um repositório de agregado e de um evento de domínio, e já publiquei um evento de domínio em código meu."},{"key":"quando-nao-usar-ddd","text":"Consigo dizer quando DDD é exagero (ex.: CRUD simples) e quando o investimento compensa."}]},{"track":"arquitetura-system-design","slug":"arq-hexagonal-clean-architecture","title":"Hexagonal/Clean Architecture","description":"Arquiteturas que invertem a direção das dependências para proteger o domínio: portas e adaptadores (Hexagonal), Clean Architecture e Onion. Mostra como isolar regras de negócio de framework, banco e I/O para testá-las sem infraestrutura e trocar detalhes técnicos sem reescrever o núcleo.","level":"senior","difficulty":4,"position":5,"prerequisites":["arq-principios-solid","arq-arquitetura-em-camadas","arq-ddd-basico"],"resources":[{"name":"Alistair Cockburn — Hexagonal Architecture","url":"https://alistair.cockburn.us/hexagonal-architecture"},{"name":"Robert C. Martin — The Clean Architecture","url":"https://blog.cleancoder.com/uncle-bob/2012/08/13/the-clean-architecture.html"},{"name":"Livro: Clean Architecture — Robert C. Martin"},{"name":"Livro: Get Your Hands Dirty on Clean Architecture — Tom Hombergs"}],"checklist":[{"key":"regra-de-dependencia","text":"Consigo explicar a regra de dependência (as dependências apontam para dentro) e desenhar o diagrama com entidades, casos de uso e adaptadores."},{"key":"porta-e-adaptadores","text":"Já implementei uma porta (interface) com pelo menos dois adaptadores (ex.: repositório em memória e repositório em banco)."},{"key":"caso-de-uso-testavel","text":"Já escrevi um caso de uso independente de framework e o testei sem subir banco de dados nem servidor HTTP."},{"key":"mapeamento-nas-fronteiras","text":"Sei mapear dados entre as fronteiras (request, DTO, entidade, resource) e justificar o custo desse mapeamento."},{"key":"aplicar-em-laravel","text":"Sei aplicar a ideia em um projeto Laravel (ex.: controller fino que chama um caso de uso e repositório definido por interface)."},{"key":"custo-beneficio","text":"Consigo argumentar quando a arquitetura hexagonal compensa e quando vira cerimônia desnecessária."}]},{"track":"arquitetura-system-design","slug":"arq-monolito-modular","title":"Monólito modular","description":"Estruturar um único deployável em módulos com fronteiras explícitas, orientados a contextos de negócio e com API pública, dados e dependências controlados. É o passo intermediário entre o 'big ball of mud' e os microsserviços e transforma a extração de serviços em uma decisão futura, não em uma urgência.","level":"senior","difficulty":4,"position":6,"prerequisites":["arq-ddd-basico","arq-hexagonal-clean-architecture"],"resources":[{"name":"Martin Fowler — Monolith First","url":"https://martinfowler.com/bliki/MonolithFirst.html"},{"name":"Shopify Engineering — Under Deconstruction: The State of Shopify's Monolith","url":"https://shopify.engineering/shopify-monolith"},{"name":"Deptrac — verificação de dependências entre camadas e módulos em PHP","url":"https://github.com/deptrac/deptrac"},{"name":"Livro: Monolith to Microservices — Sam Newman"}],"checklist":[{"key":"dividir-por-contexto","text":"Consigo dividir um sistema em módulos por contexto de negócio (e não por camada técnica) e justificar as fronteiras."},{"key":"api-publica-do-modulo","text":"Já defini uma API pública para um módulo (interface ou facade) e impedi o acesso direto às suas classes internas."},{"key":"dados-por-modulo","text":"Sei explicar por que evitar joins e chaves estrangeiras entre módulos e como eles trocam dados (API pública ou eventos)."},{"key":"verificar-fronteiras","text":"Já usei uma ferramenta ou teste de arquitetura (ex.: Deptrac, PHPat ou dependency-cruiser) para barrar dependências proibidas."},{"key":"eventos-entre-modulos","text":"Já implementei a comunicação entre módulos por eventos internos, sem acoplamento direto."},{"key":"sinais-de-extracao","text":"Sei listar os sinais de que um módulo deve virar um serviço separado e o que precisa estar pronto antes da extração."}]},{"track":"arquitetura-system-design","slug":"arq-apis-rest-maduras","title":"APIs REST maduras (versionamento, idempotência)","description":"Desenho de APIs HTTP que evoluem sem quebrar clientes: semântica correta de métodos e status, versionamento e depreciação, paginação, erros padronizados (Problem Details), idempotência com Idempotency-Key e concorrência otimista com ETag. O foco é manter contratos estáveis e operações que podem ser repetidas com segurança.","level":"mid","difficulty":4,"position":7,"prerequisites":["arq-arquitetura-em-camadas","web-http-em-profundidade"],"resources":[{"name":"Martin Fowler — Richardson Maturity Model","url":"https://martinfowler.com/articles/richardsonMaturityModel.html"},{"name":"RFC 9110 — HTTP Semantics (métodos, status e requisições condicionais)","url":"https://www.rfc-editor.org/rfc/rfc9110.html"},{"name":"RFC 9457 — Problem Details for HTTP APIs","url":"https://www.rfc-editor.org/rfc/rfc9457.html"},{"name":"Stripe — Idempotent requests","url":"https://docs.stripe.com/api/idempotent_requests"}],"checklist":[{"key":"semantica-http","text":"Consigo escolher corretamente métodos e códigos de status (201, 204, 409, 422, 429...) e explicar quais métodos são seguros e quais são idempotentes."},{"key":"versionamento","text":"Sei comparar versionamento por URL, por header e por media type e já defini uma política de depreciação para uma API."},{"key":"idempotency-key","text":"Já implementei idempotência em um POST (ex.: Idempotency-Key com a resposta guardada) e sei explicar o que acontece com repetições simultâneas."},{"key":"erros-padronizados","text":"Já padronizei as respostas de erro de uma API (ex.: RFC 9457) com código estável e detalhes de validação por campo."},{"key":"paginacao","text":"Sei explicar a diferença entre paginação por offset e por cursor e quando cada uma é a melhor escolha."},{"key":"etag-concorrencia","text":"Sei usar ETag com If-Match ou If-None-Match para controle de concorrência otimista ou cache condicional."}]},{"track":"arquitetura-system-design","slug":"arq-filas-e-mensageria","title":"Filas e mensageria","description":"Comunicação assíncrona entre componentes com filas e brokers (RabbitMQ, SQS, Kafka, Redis): fila ponto a ponto versus publish/subscribe, entrega at-least-once, consumidores idempotentes, retentativas com backoff, dead-letter queues e o padrão Outbox. O objetivo é saber quando a assincronia resolve o problema e quando só acrescenta complexidade.","level":"senior","difficulty":4,"position":8,"prerequisites":["arq-padroes-estruturais-comportamentais","arq-apis-rest-maduras","php-filas-e-jobs"],"resources":[{"name":"Enterprise Integration Patterns — Gregor Hohpe e Bobby Woolf","url":"https://www.enterpriseintegrationpatterns.com/"},{"name":"RabbitMQ — Tutoriais","url":"https://www.rabbitmq.com/tutorials"},{"name":"Apache Kafka — Introdução","url":"https://kafka.apache.org/intro/"},{"name":"Chris Richardson — Pattern: Transactional outbox","url":"https://microservices.io/patterns/data/transactional-outbox.html"}],"checklist":[{"key":"fila-vs-pubsub","text":"Consigo explicar a diferença entre fila (consumidores concorrentes) e publish/subscribe (fan-out por tópico) e escolher entre elas em um cenário real."},{"key":"at-least-once","text":"Sei explicar por que 'exactly-once' é raro na prática e como a entrega at-least-once exige consumidores idempotentes."},{"key":"consumidor-idempotente","text":"Já implementei um consumidor idempotente (ex.: tabela de mensagens processadas ou chave de deduplicação)."},{"key":"retry-e-dlq","text":"Já configurei retentativas com backoff e uma dead-letter queue e sei reprocessar mensagens que falharam."},{"key":"transactional-outbox","text":"Consigo explicar o padrão Transactional Outbox e o problema de 'dual write' (gravar no banco e publicar na fila) que ele resolve."},{"key":"ordem-e-backpressure","text":"Sei explicar ordenação por partição ou chave e o que acontece quando a fila cresce mais rápido do que é consumida (backpressure)."}]},{"track":"arquitetura-system-design","slug":"arq-cache-e-cdn","title":"Cache e CDN","description":"Estratégias para reduzir latência e carga em várias camadas (navegador, CDN, aplicação e banco): cache-aside, write-through, TTL, invalidação, cache stampede e headers HTTP como Cache-Control e ETag. Inclui projetar chaves de cache seguras e medir a taxa de acerto para saber se o cache está de fato ajudando.","level":"senior","difficulty":4,"position":9,"prerequisites":["arq-apis-rest-maduras","php-cache"],"resources":[{"name":"MDN — Cache HTTP","url":"https://developer.mozilla.org/pt-BR/docs/Web/HTTP/Guides/Caching"},{"name":"RFC 9111 — HTTP Caching","url":"https://www.rfc-editor.org/rfc/rfc9111.html"},{"name":"Redis — Documentação oficial","url":"https://redis.io/docs/latest/"},{"name":"Cloudflare — Cache (CDN) docs","url":"https://developers.cloudflare.com/cache/"}],"checklist":[{"key":"camadas-de-cache","text":"Consigo listar as camadas de cache por onde uma requisição web passa (navegador, CDN, proxy, aplicação, banco) e o que cada uma guarda."},{"key":"cache-aside","text":"Já implementei cache-aside com TTL e invalidação em um projeto e sei compará-lo com write-through e write-behind."},{"key":"cache-control-etag","text":"Sei configurar Cache-Control (max-age, s-maxage, no-store, stale-while-revalidate) e ETag de acordo com o tipo de recurso."},{"key":"cache-stampede","text":"Consigo explicar cache stampede e já usei uma mitigação (lock, jitter no TTL ou renovação antecipada)."},{"key":"estrategias-de-invalidacao","text":"Sei comparar estratégias de invalidação (por tempo, por evento e por versão ou tag na chave) e seus riscos de dado desatualizado."},{"key":"medir-hit-ratio","text":"Já medi a taxa de acerto (hit ratio) de um cache e usei o resultado para ajustar TTL ou chaves."}]},{"track":"arquitetura-system-design","slug":"arq-escalabilidade-horizontal","title":"Escalabilidade horizontal","description":"Como fazer o sistema crescer adicionando instâncias em vez de máquinas maiores: aplicações stateless, balanceamento de carga, sessões e arquivos fora do servidor, réplicas de leitura e particionamento (sharding) do banco. Inclui estimar capacidade, achar gargalos com testes de carga e saber quando escalar verticalmente ainda é a melhor decisão.","level":"senior","difficulty":5,"position":10,"prerequisites":["arq-cache-e-cdn","arq-filas-e-mensageria"],"resources":[{"name":"Livro: Designing Data-Intensive Applications — Martin Kleppmann (capítulos sobre replicação e particionamento)"},{"name":"Livro: System Design Interview — Alex Xu"},{"name":"Google SRE Book — Load Balancing in the Datacenter","url":"https://sre.google/sre-book/load-balancing-datacenter/"},{"name":"k6 — Documentação oficial","url":"https://grafana.com/docs/k6/latest/"}],"checklist":[{"key":"aplicacao-stateless","text":"Consigo explicar por que a aplicação precisa ser stateless e já movi sessão, cache e uploads para fora do servidor local."},{"key":"balanceamento-de-carga","text":"Sei descrever algoritmos de balanceamento (round robin, least connections, hash consistente) e o papel dos health checks."},{"key":"escala-do-banco","text":"Consigo explicar réplicas de leitura, lag de replicação e sharding, e os gargalos que cada um resolve ou cria."},{"key":"estimativa-de-capacidade","text":"Já fiz uma estimativa de capacidade (requisições por segundo, armazenamento, banda) para um sistema e apontei o gargalo provável."},{"key":"teste-de-carga","text":"Já executei um teste de carga (k6, Locust ou similar), li a latência em p95 e p99 e identifiquei o primeiro gargalo."},{"key":"vertical-vs-horizontal","text":"Sei argumentar quando escalar verticalmente ainda é a melhor decisão."}]},{"track":"arquitetura-system-design","slug":"arq-cap-consistencia-eventual","title":"CAP e consistência eventual","description":"Fundamentos de sistemas distribuídos para escolher e usar bancos e filas conhecendo os trade-offs: teorema CAP e PACELC, consistência forte versus eventual, quorum e padrões para conviver com inconsistência, como Saga e compensação. O objetivo é raciocinar sobre disponibilidade, latência e consistência ao desenhar fluxos que cruzam serviços.","level":"senior","difficulty":5,"position":11,"prerequisites":["arq-escalabilidade-horizontal","arq-filas-e-mensageria"],"resources":[{"name":"Livro: Designing Data-Intensive Applications — Martin Kleppmann (capítulos sobre replicação, transações e consistência)"},{"name":"Martin Kleppmann — Please stop calling databases CP or AP","url":"https://martin.kleppmann.com/2015/05/11/please-stop-calling-databases-cp-or-ap.html"},{"name":"Werner Vogels — Eventually Consistent","url":"https://www.allthingsdistributed.com/2008/12/eventually_consistent.html"},{"name":"Chris Richardson — Pattern: Saga","url":"https://microservices.io/patterns/data/saga.html"}],"checklist":[{"key":"explicar-cap","text":"Consigo explicar o teorema CAP sem os mitos comuns e dizer o que acontece com disponibilidade e consistência durante uma partição de rede."},{"key":"pacelc","text":"Sei o que o PACELC acrescenta ao CAP (o trade-off entre latência e consistência quando não há partição)."},{"key":"niveis-de-consistencia","text":"Consigo diferenciar consistência forte, eventual, read-your-writes e monotonic reads com exemplos de produto."},{"key":"regra-de-quorum","text":"Sei aplicar a regra de quorum (R + W > N) e explicar como ela afeta leituras e escritas."},{"key":"saga-e-compensacao","text":"Sei explicar a Saga (coreografada e orquestrada) e já desenhei as ações de compensação de um fluxo (ex.: pedido, pagamento e estoque)."},{"key":"escolher-banco-por-garantias","text":"Consigo justificar a escolha de um banco (ex.: PostgreSQL, Redis, DynamoDB ou Cassandra) para um caso de uso a partir de suas garantias de consistência."}]},{"track":"arquitetura-system-design","slug":"arq-microsservicos-e-trade-offs","title":"Microsserviços e trade-offs","description":"Arquitetura de serviços independentes por contexto de negócio: ganhos (deploy e escala independentes, autonomia de times) e custos (consistência distribuída, observabilidade, latência de rede e complexidade operacional). Cobre critérios para escolher entre monólito e microsserviços, comunicação síncrona e assíncrona, dados por serviço e migração gradual com Strangler Fig.","level":"senior","difficulty":5,"position":12,"prerequisites":["arq-monolito-modular","arq-filas-e-mensageria","arq-cap-consistencia-eventual"],"resources":[{"name":"Martin Fowler e James Lewis — Microservices","url":"https://martinfowler.com/articles/microservices.html"},{"name":"Martin Fowler — Microservice Prerequisites","url":"https://martinfowler.com/bliki/MicroservicePrerequisites.html"},{"name":"Martin Fowler — Strangler Fig Application","url":"https://martinfowler.com/bliki/StranglerFigApplication.html"},{"name":"Livro: Building Microservices — Sam Newman"}],"checklist":[{"key":"decidir-monolito-ou-servicos","text":"Consigo listar os critérios (tamanho do time, necessidade de escala, ritmo de deploy, maturidade operacional) para escolher entre monólito modular e microsserviços e defender a decisão."},{"key":"banco-por-servico","text":"Sei explicar o padrão 'banco por serviço' e as consequências para consultas, relatórios e transações."},{"key":"sincrono-vs-assincrono","text":"Consigo comparar comunicação síncrona (REST ou gRPC) com assíncrona (eventos) quanto a acoplamento temporal e falhas em cascata."},{"key":"resiliencia-entre-servicos","text":"Já configurei timeout, retry com backoff e circuit breaker em chamadas entre serviços."},{"key":"strangler-fig","text":"Sei descrever o padrão Strangler Fig e como migrar uma funcionalidade de um monólito sem reescrita total."},{"key":"anti-padroes","text":"Reconheço anti-padrões como 'monólito distribuído' e serviços excessivamente granulares e sei como evitá-los."}]},{"track":"arquitetura-system-design","slug":"arq-adrs-documentacao-decisoes","title":"ADRs e documentação de decisões","description":"Registrar decisões arquiteturais em ADRs (Architecture Decision Records) curtos e versionados junto do código, com contexto, alternativas consideradas, decisão e consequências. Inclui o fluxo de proposta e revisão, o ciclo de vida (proposto, aceito, substituído) e diagramas leves, como o modelo C4, para comunicar a arquitetura.","level":"senior","difficulty":3,"position":13,"prerequisites":["arq-arquitetura-em-camadas"],"resources":[{"name":"Michael Nygard — Documenting Architecture Decisions","url":"https://cognitect.com/blog/2011/11/15/documenting-architecture-decisions"},{"name":"adr.github.io — Architectural Decision Records","url":"https://adr.github.io/"},{"name":"MADR — Markdown Architectural Decision Records","url":"https://adr.github.io/madr/"},{"name":"C4 model — Simon Brown","url":"https://c4model.com/"}],"checklist":[{"key":"escrever-adr","text":"Já escrevi um ADR com contexto, alternativas, decisão e consequências para uma escolha técnica real."},{"key":"adrs-versionados","text":"Mantenho ADRs versionados junto do código (ex.: docs/adr), com numeração e status."},{"key":"substituir-adr","text":"Sei por que um ADR é substituído por outro (superseded) em vez de apagado e como registrar essa ligação."},{"key":"revisar-adr-em-time","text":"Já submeti um ADR à revisão do time (PR ou RFC) e incorporei as objeções antes de aceitá-lo."},{"key":"explicitar-trade-offs","text":"Consigo explicitar trade-offs e critérios (custo, risco, reversibilidade) em vez de apenas descrever a solução escolhida."},{"key":"diagrama-c4","text":"Consigo desenhar um diagrama de contexto e outro de contêineres (modelo C4) de um sistema meu."}]},{"track":"devops-observabilidade","slug":"ops-linux-essencial","title":"Linux essencial","description":"Operar um servidor Linux pela linha de comando: sistema de arquivos, permissões e usuários, processos, serviços com systemd, SSH e diagnóstico básico de disco, memória e CPU. É a base de tudo o que roda em produção, de contêineres a pipelines de deploy.","level":"junior","difficulty":2,"position":0,"prerequisites":[],"resources":[{"name":"Livro: The Linux Command Line — William Shotts","url":"https://linuxcommand.org/tlcl.php"},{"name":"Linux man pages — man7.org","url":"https://man7.org/linux/man-pages/"},{"name":"ArchWiki — File permissions and attributes","url":"https://wiki.archlinux.org/title/File_permissions_and_attributes"},{"name":"ArchWiki — systemd","url":"https://wiki.archlinux.org/title/Systemd"}],"checklist":[{"key":"navegar-e-buscar","text":"Consigo navegar pelo sistema de arquivos, localizar arquivos e trechos (find, grep) e ler logs (tail -f, less, journalctl) só com a linha de comando."},{"key":"permissoes-e-usuarios","text":"Sei interpretar e alterar permissões (chmod, chown, umask) e explicar por que uma aplicação não deve rodar como root."},{"key":"processos-e-sinais","text":"Consigo listar, inspecionar e encerrar processos (ps, top ou htop, kill) e explicar a diferença entre SIGTERM e SIGKILL."},{"key":"servico-systemd","text":"Já criei e gerenciei um serviço com systemd (unit file, systemctl e journalctl) para uma aplicação minha."},{"key":"ssh-com-chaves","text":"Já configurei acesso SSH por chave (sem senha) e sei explicar o papel do arquivo authorized_keys."},{"key":"diagnostico-de-recursos","text":"Sei diagnosticar disco cheio, falta de memória e uso alto de CPU com df, du, free e top."}]},{"track":"devops-observabilidade","slug":"ops-redes-basicas","title":"Redes básicas","description":"Os conceitos de rede que todo desenvolvedor precisa para depurar problemas em produção: IP, CIDR e sub-redes, portas e TCP/UDP, DNS, HTTP e TLS, NAT e firewall. O foco é ler o que está acontecendo com ferramentas como curl, dig, ss e traceroute e entender por que uma conexão falha.","level":"junior","difficulty":2,"position":1,"prerequisites":[],"resources":[{"name":"MDN — Uma visão geral do HTTP","url":"https://developer.mozilla.org/pt-BR/docs/Web/HTTP/Guides/Overview"},{"name":"How DNS Works — quadrinho explicativo","url":"https://howdns.works/"},{"name":"High Performance Browser Networking — Ilya Grigorik","url":"https://hpbn.co/"},{"name":"Livro: Computer Networking: A Top-Down Approach — Kurose e Ross"}],"checklist":[{"key":"ip-e-cidr","text":"Consigo explicar endereço IP, máscara e notação CIDR e calcular quantos hosts úteis cabem em uma sub-rede /24."},{"key":"tcp-e-portas","text":"Sei explicar o handshake TCP, a diferença entre TCP e UDP e o que é uma porta, e já descobri com ss ou lsof qual processo escuta em uma porta."},{"key":"resolucao-dns","text":"Consigo explicar como uma consulta DNS é resolvida (resolver, registros A, CNAME e MX, TTL) e já depurei um problema de DNS com dig ou nslookup."},{"key":"url-ate-pagina","text":"Sei descrever o que acontece desde digitar uma URL até receber a página, passando por DNS, TCP, TLS e HTTP."},{"key":"depurar-conexao","text":"Já diagnosticei uma conexão que falhava (porta fechada, firewall, DNS ou certificado) usando curl -v, ping, traceroute ou nc."},{"key":"nat-e-firewall","text":"Consigo explicar NAT, IP privado versus público e como um firewall ou security group libera ou bloqueia tráfego."}]},{"track":"devops-observabilidade","slug":"ops-docker","title":"Docker","description":"Empacotar e executar aplicações em contêineres: imagens, camadas, Dockerfile, volumes, redes, variáveis de ambiente e registries. Cobre builds multi-stage, cache de build, imagens enxutas e seguras (usuário não root) e como depurar um contêiner que não sobe.","level":"junior","difficulty":3,"position":2,"prerequisites":["ops-linux-essencial","ops-redes-basicas","fund-terminal-e-shell"],"resources":[{"name":"Docker — Documentação oficial","url":"https://docs.docker.com/"},{"name":"Docker — Get started","url":"https://docs.docker.com/get-started/"},{"name":"Docker — Building best practices (Dockerfile)","url":"https://docs.docker.com/build/building/best-practices/"},{"name":"Docker — Multi-stage builds","url":"https://docs.docker.com/build/building/multi-stage/"}],"checklist":[{"key":"imagem-vs-conteiner","text":"Consigo explicar a diferença entre imagem, contêiner, camada e registry, e o que muda entre um contêiner e uma máquina virtual."},{"key":"escrever-dockerfile","text":"Já escrevi um Dockerfile para uma aplicação minha (PHP ou Node) e entendo cada instrução usada (FROM, COPY, RUN, CMD, ENTRYPOINT)."},{"key":"multi-stage-e-cache","text":"Já usei build multi-stage e ordenei as instruções para aproveitar o cache de camadas, reduzindo o tamanho da imagem e o tempo de build."},{"key":"volumes-e-redes","text":"Sei usar volumes (bind e nomeados) e redes e consigo explicar por que dados sem volume somem quando o contêiner é recriado."},{"key":"usuario-nao-root","text":"Já configurei um contêiner para rodar como usuário não root e usei .dockerignore para não enviar segredos nem lixo ao build."},{"key":"depurar-conteiner","text":"Sei depurar um contêiner que não sobe (docker logs, exec e inspect) e identificar causas comuns, como porta, variável de ambiente ou permissão."}]},{"track":"devops-observabilidade","slug":"ops-docker-compose","title":"Docker Compose","description":"Descrever um ambiente com vários serviços (app, banco, cache e fila) em um único arquivo compose.yaml: redes, volumes, dependências com healthcheck, variáveis de ambiente, perfis e múltiplos arquivos para desenvolvimento e produção. Garante um ambiente local reproduzível com um só comando e prepara o terreno para orquestradores como o Kubernetes.","level":"junior","difficulty":3,"position":3,"prerequisites":["ops-docker"],"resources":[{"name":"Docker Compose — Documentação oficial","url":"https://docs.docker.com/compose/"},{"name":"Compose file reference","url":"https://docs.docker.com/reference/compose-file/"},{"name":"Compose — Networking","url":"https://docs.docker.com/compose/how-tos/networking/"},{"name":"Compose — Control startup and shutdown order (healthcheck e depends_on)","url":"https://docs.docker.com/compose/how-tos/startup-order/"}],"checklist":[{"key":"stack-completa","text":"Já montei um compose.yaml com aplicação, banco de dados e cache (ex.: PHP-FPM, Nginx, PostgreSQL ou MySQL e Redis) que sobe com um único comando."},{"key":"rede-por-nome","text":"Sei explicar como os serviços se encontram pelo nome na rede do Compose e por que o host do banco não é localhost dentro do contêiner da aplicação."},{"key":"healthcheck-e-depends-on","text":"Já usei healthcheck com depends_on (condition: service_healthy) para a aplicação só iniciar quando o banco estiver pronto."},{"key":"env-e-segredos","text":"Sei separar a configuração por ambiente com arquivos .env e variáveis de ambiente, sem versionar segredos."},{"key":"override-e-profiles","text":"Já usei múltiplos arquivos (override) ou profiles para diferenciar desenvolvimento e produção ou para ativar serviços opcionais."},{"key":"persistencia-de-dados","text":"Consigo explicar como persistir os dados do banco com volumes nomeados e como recriar o ambiente do zero."}]},{"track":"devops-observabilidade","slug":"ops-deploy-php-node","title":"Deploy de apps PHP/Node","description":"Levar uma aplicação PHP (Laravel) ou Node do repositório para produção de forma repetível: variáveis de ambiente, migrações, processos supervisionados (PHP-FPM, systemd, PM2 e workers), release atômica com rollback e health checks. Inclui estratégias de deploy sem downtime, como blue/green e canary, e a ligação com o pipeline de CI/CD.","level":"mid","difficulty":3,"position":4,"prerequisites":["ops-linux-essencial","ops-docker-compose"],"resources":[{"name":"The Twelve-Factor App (pt-BR)","url":"https://12factor.net/pt_br/"},{"name":"Laravel — Deployment","url":"https://laravel.com/framework/docs/deployment"},{"name":"Deployer — ferramenta de deploy para PHP","url":"https://deployer.org/"},{"name":"Martin Fowler — Blue Green Deployment","url":"https://martinfowler.com/bliki/BlueGreenDeployment.html"}],"checklist":[{"key":"config-por-ambiente","text":"Sei configurar a aplicação por variáveis de ambiente (configuração fora do código) e mantenho os segredos fora do repositório."},{"key":"release-atomica-rollback","text":"Já fiz um deploy com release atômica (ex.: troca do symlink 'current' ou de imagem) e executei um rollback para a versão anterior."},{"key":"processos-supervisionados","text":"Já coloquei processos de longa duração (PHP-FPM, workers de fila ou Node) sob supervisão (systemd, Supervisor ou PM2) com reinício automático."},{"key":"migracoes-no-deploy","text":"Sei executar migrações de banco durante o deploy sem derrubar a aplicação, mantendo o esquema compatível com a versão anterior do código."},{"key":"healthcheck-e-smoke-test","text":"Já configurei um health check e um smoke test pós-deploy que interrompem ou desfazem o deploy quando falham."},{"key":"otimizacoes-de-producao","text":"Conheço as otimizações de produção do meu stack (ex.: cache de config e rotas, OPcache e composer install --no-dev em Laravel, ou build com NODE_ENV=production em Node)."}]},{"track":"devops-observabilidade","slug":"ops-nginx-proxy-reverso","title":"Nginx e proxy reverso","description":"Usar o Nginx na frente da aplicação: server blocks, proxy_pass e upstreams, FastCGI para PHP-FPM, terminação TLS com Let's Encrypt, cabeçalhos de proxy, compressão e limitação de requisições. Também cobre balanceamento entre instâncias e o diagnóstico de erros comuns como 502, 504 e 413.","level":"mid","difficulty":3,"position":5,"prerequisites":["ops-redes-basicas","ops-linux-essencial"],"resources":[{"name":"Nginx — Beginner's Guide","url":"https://nginx.org/en/docs/beginners_guide.html"},{"name":"NGINX Docs — Reverse Proxy","url":"https://docs.nginx.com/nginx/admin-guide/web-server/reverse-proxy/"},{"name":"Let's Encrypt — Documentação","url":"https://letsencrypt.org/docs/"},{"name":"Mozilla SSL Configuration Generator","url":"https://ssl-config.mozilla.org/"}],"checklist":[{"key":"server-block","text":"Já configurei um server block do zero (server_name, root e location) e validei com nginx -t antes de recarregar."},{"key":"proxy-pass-e-cabecalhos","text":"Já usei proxy_pass para uma aplicação Node ou um contêiner, repassando cabeçalhos como Host, X-Real-IP e X-Forwarded-For/Proto."},{"key":"php-fpm-laravel","text":"Sei configurar o Nginx com PHP-FPM (fastcgi_pass) para uma aplicação Laravel, incluindo a regra try_files do front controller."},{"key":"tls-letsencrypt","text":"Já emiti e renovei um certificado TLS com Let's Encrypt e configurei o redirecionamento de HTTP para HTTPS."},{"key":"upstream-e-limites","text":"Sei configurar um upstream com mais de uma instância e aplicar limite de requisições (limit_req) e de tamanho de upload (client_max_body_size)."},{"key":"diagnosticar-502-504","text":"Consigo diagnosticar um 502, 504 ou 413 lendo os logs de acesso e de erro do Nginx."}]},{"track":"devops-observabilidade","slug":"ops-logs-estruturados","title":"Logs estruturados","description":"Gerar logs em formato estruturado (JSON) com nível, contexto e identificador de correlação, em vez de texto solto, para que possam ser buscados e agregados. Cobre níveis de log, o que nunca registrar (dados sensíveis), saída em stdout em contêineres e coleta centralizada com ferramentas como Loki ou Elastic.","level":"mid","difficulty":3,"position":6,"prerequisites":["ops-linux-essencial","ops-docker"],"resources":[{"name":"The Twelve-Factor App — Logs (pt-BR)","url":"https://12factor.net/pt_br/logs"},{"name":"PHP-FIG — PSR-3: Logger Interface","url":"https://www.php-fig.org/psr/psr-3/"},{"name":"Stripe — Fast and flexible observability with canonical log lines","url":"https://stripe.com/blog/canonical-log-lines"},{"name":"Grafana Loki — Documentação oficial","url":"https://grafana.com/docs/loki/latest/"}],"checklist":[{"key":"logs-json-com-contexto","text":"Já configurei uma aplicação minha para emitir logs em JSON com nível, mensagem, timestamp e contexto (ex.: user_id e rota)."},{"key":"correlation-id","text":"Já implementei um identificador de correlação (request ID) propagado entre middleware, logs e chamadas a outros serviços."},{"key":"niveis-de-log","text":"Sei escolher o nível de log (debug, info, warning e error) e evitar tanto o silêncio quanto o ruído que esconde problemas."},{"key":"dados-sensiveis","text":"Sei quais dados nunca devem aparecer em logs (senhas, tokens, dados pessoais e de pagamento) e já apliquei mascaramento."},{"key":"stdout-em-conteineres","text":"Consigo explicar por que contêineres devem escrever logs em stdout/stderr e como funcionam a coleta e a rotação."},{"key":"busca-centralizada","text":"Já consultei logs centralizados (ex.: Loki, Elastic ou CloudWatch) para investigar um erro real, filtrando por campos."}]},{"track":"devops-observabilidade","slug":"ops-metricas-e-alertas","title":"Métricas e alertas","description":"Instrumentar aplicações e servidores com métricas (contadores, gauges e histogramas) coletadas pelo Prometheus e visualizadas no Grafana, usando métodos como RED e USE. Cobre cardinalidade de labels, consultas em PromQL e a criação de alertas acionáveis no Alertmanager, evitando a fadiga de alertas.","level":"mid","difficulty":4,"position":7,"prerequisites":["ops-logs-estruturados","ops-docker-compose"],"resources":[{"name":"Prometheus — Documentação oficial (visão geral)","url":"https://prometheus.io/docs/introduction/overview/"},{"name":"Prometheus — Alerting best practices","url":"https://prometheus.io/docs/practices/alerting/"},{"name":"Google SRE Book — Monitoring Distributed Systems","url":"https://sre.google/sre-book/monitoring-distributed-systems/"},{"name":"Brendan Gregg — The USE Method","url":"https://www.brendangregg.com/usemethod.html"}],"checklist":[{"key":"tipos-de-metrica","text":"Sei diferenciar counter, gauge e histogram e escolher o tipo certo para contagem de requisições, uso de memória e latência."},{"key":"instrumentar-aplicacao","text":"Já instrumentei uma aplicação minha para expor métricas (requisições, erros e duração) em um endpoint /metrics e coletei com o Prometheus."},{"key":"promql-basico","text":"Consigo escrever consultas PromQL básicas (rate, sum by e histogram_quantile) para taxa de requisições, taxa de erros e latência p95."},{"key":"golden-signals-red-use","text":"Sei explicar os quatro sinais dourados (latência, tráfego, erros e saturação) e os métodos RED e USE, e montei um painel no Grafana com eles."},{"key":"cardinalidade","text":"Sei explicar por que labels com valores ilimitados (ex.: user_id ou URL completa) causam explosão de cardinalidade e como evitá-la."},{"key":"alerta-acionavel","text":"Já criei um alerta no Alertmanager que avisa sobre um sintoma percebido pelo usuário, com severidade, descrição e link para um runbook."}]},{"track":"devops-observabilidade","slug":"ops-tracing-distribuido","title":"Tracing distribuído","description":"Acompanhar uma requisição que atravessa vários serviços, filas e bancos usando traces e spans, com propagação de contexto (W3C Trace Context) e instrumentação via OpenTelemetry. Mostra como achar gargalos de latência, correlacionar traces com logs e métricas e escolher uma estratégia de amostragem (sampling).","level":"senior","difficulty":4,"position":8,"prerequisites":["ops-logs-estruturados","ops-metricas-e-alertas"],"resources":[{"name":"OpenTelemetry — Documentação oficial","url":"https://opentelemetry.io/docs/"},{"name":"OpenTelemetry — Traces (conceitos)","url":"https://opentelemetry.io/docs/concepts/signals/traces/"},{"name":"OpenTelemetry — Context propagation (inclui W3C Trace Context)","url":"https://opentelemetry.io/docs/concepts/context-propagation/"},{"name":"Jaeger — Documentação oficial","url":"https://www.jaegertracing.io/docs/"}],"checklist":[{"key":"trace-e-spans","text":"Consigo explicar trace, span, atributos e a relação pai-filho entre spans, e ler a cascata (waterfall) de um trace."},{"key":"instrumentar-otel","text":"Já instrumentei uma aplicação (automática ou manualmente) com OpenTelemetry e enviei traces a um backend como Jaeger ou Tempo."},{"key":"propagacao-de-contexto","text":"Sei explicar como o cabeçalho traceparent (W3C Trace Context) propaga o contexto entre serviços e filas e já verifiquei isso em um fluxo real."},{"key":"achar-gargalo","text":"Já usei um trace para localizar o gargalo de uma requisição lenta (ex.: consultas N+1 ou chamada externa) e corrigi o problema."},{"key":"correlacionar-logs","text":"Já correlacionei logs e traces incluindo o trace_id nos logs estruturados."},{"key":"estrategia-de-sampling","text":"Sei comparar amostragem na origem (head) e na cauda (tail) e escolher uma estratégia considerando custo e perda de traces raros."}]},{"track":"devops-observabilidade","slug":"ops-infra-como-codigo","title":"Infra como código","description":"Definir e versionar infraestrutura (redes, servidores, bancos, DNS e permissões) em código declarativo, com Terraform ou OpenTofu, e configurar servidores com Ansible. Cobre state remoto, módulos, plan antes de apply, detecção de drift, gestão de segredos e revisão de mudanças de infraestrutura por pull request.","level":"senior","difficulty":4,"position":9,"prerequisites":["ops-redes-basicas","ops-deploy-php-node"],"resources":[{"name":"Terraform — Documentação oficial","url":"https://developer.hashicorp.com/terraform/docs"},{"name":"OpenTofu — Documentação oficial","url":"https://opentofu.org/docs/"},{"name":"Ansible — Documentação oficial","url":"https://docs.ansible.com/"},{"name":"Martin Fowler — Infrastructure As Code","url":"https://martinfowler.com/bliki/InfrastructureAsCode.html"}],"checklist":[{"key":"declarativo-vs-imperativo","text":"Consigo explicar a diferença entre abordagem declarativa e imperativa e entre provisionamento (Terraform) e configuração (Ansible)."},{"key":"provisionar-e-destruir","text":"Já provisionei recursos reais (ex.: uma VM ou contêiner, rede e DNS) com Terraform ou OpenTofu e os destruí em seguida."},{"key":"state-remoto","text":"Sei explicar o que é o state, por que ele deve ser remoto e com lock, e o que acontece se for perdido ou editado à mão."},{"key":"plan-no-pull-request","text":"Já usei a saída do terraform plan na revisão de um pull request antes de aplicar uma mudança de infraestrutura."},{"key":"modulos-e-variaveis","text":"Já criei um módulo reutilizável com variáveis e outputs e o usei em mais de um ambiente."},{"key":"drift-e-segredos","text":"Sei explicar o que é drift de configuração e como manter segredos fora do código e protegidos no state (cofre de segredos, state criptografado)."}]},{"track":"devops-observabilidade","slug":"ops-kubernetes-nocoes","title":"Kubernetes (noções)","description":"Noções do Kubernetes para quem desenvolve e opera aplicações: arquitetura do cluster, Pods, Deployments, Services, Ingress, ConfigMaps e Secrets, probes de liveness e readiness, limites de recursos e rolling updates. O objetivo é ler e escrever manifestos, depurar com kubectl e entender o que a plataforma resolve, sem precisar administrar o cluster.","level":"senior","difficulty":4,"position":10,"prerequisites":["ops-docker-compose","ops-nginx-proxy-reverso"],"resources":[{"name":"Kubernetes — Documentação oficial","url":"https://kubernetes.io/docs/home/"},{"name":"Kubernetes — Tutorial: Learn Kubernetes Basics","url":"https://kubernetes.io/docs/tutorials/kubernetes-basics/"},{"name":"Kubernetes — Configure Liveness, Readiness and Startup Probes","url":"https://kubernetes.io/docs/tasks/configure-pod-container/configure-liveness-readiness-startup-probes/"},{"name":"kind — Kubernetes in Docker (cluster local)","url":"https://kind.sigs.k8s.io/"}],"checklist":[{"key":"arquitetura-do-cluster","text":"Consigo explicar os componentes do cluster (control plane, nós e kubelet) e o papel do API server e do etcd."},{"key":"pod-deployment-service","text":"Já criei um Deployment e um Service para uma aplicação minha e sei explicar a diferença entre Pod, ReplicaSet e Deployment."},{"key":"ingress-vs-proxy","text":"Sei explicar como um Ingress expõe um Service ao tráfego externo e compará-lo com um proxy reverso Nginx."},{"key":"configmap-e-secret","text":"Já separei a configuração do contêiner com ConfigMap e Secret e sei por que um Secret não é criptografia por si só."},{"key":"probes-e-recursos","text":"Sei configurar liveness e readiness probes e requests/limits de CPU e memória, e explicar o efeito de cada um."},{"key":"rollout-e-depuracao","text":"Já executei um rolling update com rollback (kubectl rollout) e sei depurar um Pod em CrashLoopBackOff ou ImagePullBackOff com describe, logs e events."}]},{"track":"devops-observabilidade","slug":"ops-sli-slo-incidentes","title":"SLI/SLO e incidentes","description":"Definir o que significa 'funcionar bem' com indicadores (SLI), objetivos (SLO) e orçamento de erro (error budget) e usá-los para equilibrar confiabilidade e entrega de funcionalidades. Cobre alertas baseados em burn rate, o ciclo de resposta a incidentes (papéis, comunicação e mitigação) e postmortems sem culpados.","level":"senior","difficulty":4,"position":11,"prerequisites":["ops-metricas-e-alertas"],"resources":[{"name":"Google SRE Book — Service Level Objectives","url":"https://sre.google/sre-book/service-level-objectives/"},{"name":"Google SRE Workbook — Implementing SLOs","url":"https://sre.google/workbook/implementing-slos/"},{"name":"Google SRE Book — Managing Incidents","url":"https://sre.google/sre-book/managing-incidents/"},{"name":"Google SRE Book — Postmortem Culture: Learning from Failure","url":"https://sre.google/sre-book/postmortem-culture/"}],"checklist":[{"key":"sli-slo-sla","text":"Consigo diferenciar SLI, SLO e SLA e escolher SLIs de disponibilidade e latência a partir da perspectiva do usuário."},{"key":"definir-slo","text":"Já defini um SLO com janela de tempo (ex.: 99,9% em 30 dias) para um serviço e calculei quanto de erro ele permite."},{"key":"error-budget","text":"Sei explicar o orçamento de erro e como usá-lo para decidir entre entregar funcionalidades e investir em confiabilidade."},{"key":"alertas-burn-rate","text":"Sei explicar alertas por burn rate (janelas curta e longa) e por que eles são melhores que alertar por um limite fixo de erros."},{"key":"papeis-no-incidente","text":"Consigo descrever os papéis de um incidente (comandante, comunicação e operações) e já participei de um, real ou simulado."},{"key":"postmortem-sem-culpa","text":"Já escrevi ou revisei um postmortem sem culpados, com linha do tempo, causas contribuintes e ações de acompanhamento com responsáveis."}]},{"track":"devops-observabilidade","slug":"ops-backup-disaster-recovery","title":"Backup e disaster recovery","description":"Proteger dados e serviço contra perdas e desastres: estratégia de backup (regra 3-2-1, completo, incremental e ponto no tempo), RPO e RTO, replicação entre zonas ou regiões e planos de recuperação. O ponto central é restaurar de verdade: backup que nunca foi testado não conta, e a recuperação deve ser ensaiada e documentada em runbooks.","level":"senior","difficulty":4,"position":12,"prerequisites":["ops-infra-como-codigo","ops-sli-slo-incidentes"],"resources":[{"name":"AWS Whitepaper — Disaster Recovery of Workloads on AWS","url":"https://docs.aws.amazon.com/whitepapers/latest/disaster-recovery-workloads-on-aws/disaster-recovery-workloads-on-aws.html"},{"name":"PostgreSQL — Backup and Restore","url":"https://www.postgresql.org/docs/current/backup.html"},{"name":"Google SRE Book — Data Integrity: What You Read Is What You Wrote","url":"https://sre.google/sre-book/data-integrity/"},{"name":"restic — Documentação oficial","url":"https://restic.readthedocs.io/en/stable/"}],"checklist":[{"key":"rpo-e-rto","text":"Consigo explicar RPO e RTO e definir valores para um serviço meu a partir do impacto no negócio."},{"key":"regra-3-2-1","text":"Sei explicar a regra 3-2-1 e já configurei backups automáticos com uma cópia fora do ambiente principal (outra região ou provedor)."},{"key":"backup-de-banco","text":"Já fiz backup lógico e físico de um banco (ex.: pg_dump e arquivamento de WAL, ou mysqldump) e entendo a restauração até um ponto no tempo (PITR)."},{"key":"testar-restauracao","text":"Já testei a restauração completa de um backup em um ambiente limpo e medi o tempo real de recuperação."},{"key":"runbook-e-simulacao","text":"Já escrevi um runbook de recuperação e o ensaiei em uma simulação (game day) ou em um ambiente de teste."},{"key":"estrategias-de-dr","text":"Sei comparar as estratégias de DR (backup e restauração, pilot light, warm standby e multi-site ativo-ativo) em custo e tempo de recuperação."}]},{"track":"seguranca","slug":"seg-principios-cia-menor-privilegio","title":"Princípios (CIA, menor privilégio)","description":"Fundamentos que guiam toda decisão de segurança: a tríade CIA (confidencialidade, integridade e disponibilidade), menor privilégio, defesa em profundidade e falha segura. Dominar esses princípios permite avaliar riscos e justificar controles antes de partir para técnicas específicas.","level":"junior","difficulty":2,"position":0,"prerequisites":[],"resources":[{"name":"MDN — Segurança na Web","url":"https://developer.mozilla.org/pt-BR/docs/Web/Security"},{"name":"Artigo: The Protection of Information in Computer Systems — Saltzer e Schroeder (1975)"},{"name":"Livro: Security Engineering — Ross Anderson"},{"name":"Livro: Designing Secure Software — Loren Kohnfelder"}],"checklist":[{"key":"explicar-cia","text":"Consigo explicar confidencialidade, integridade e disponibilidade com um exemplo concreto de cada e citar um ataque que compromete cada propriedade."},{"key":"aplicar-menor-privilegio","text":"Sei aplicar o menor privilégio ao configurar o usuário do banco de dados, papéis de serviços e permissões de arquivos."},{"key":"defesa-em-profundidade","text":"Consigo descrever defesa em profundidade e dar um exemplo de várias camadas protegendo um mesmo recurso."},{"key":"falha-segura","text":"Sei explicar o que é falhar de forma segura (fail-safe defaults) e identificar um trecho de código que 'falha aberto'."},{"key":"ameaca-vulnerabilidade-risco","text":"Sei diferenciar ameaça, vulnerabilidade e risco e dar um exemplo que relacione os três."},{"key":"classificar-dados","text":"Consigo classificar os dados de um sistema por sensibilidade (público, interno, confidencial) e dizer quais controles cada classe exige."}]},{"track":"seguranca","slug":"seg-owasp-top-10","title":"OWASP Top 10","description":"Lista de consenso da OWASP com as categorias de risco mais críticas em aplicações web, como controle de acesso quebrado, falhas criptográficas, injeção e configuração insegura. Funciona como vocabulário comum para revisar código, priorizar correções e conversar com times de segurança e auditoria.","level":"junior","difficulty":3,"position":1,"prerequisites":["seg-principios-cia-menor-privilegio"],"resources":[{"name":"OWASP Top 10","url":"https://owasp.org/www-project-top-ten/"},{"name":"OWASP Cheat Sheet Series","url":"https://cheatsheetseries.owasp.org/"},{"name":"PortSwigger Web Security Academy","url":"https://portswigger.net/web-security"},{"name":"Livro: Web Application Security — Andrew Hoffman"}],"checklist":[{"key":"listar-categorias","text":"Consigo citar as categorias do OWASP Top 10 e dar um exemplo de falha de cada uma."},{"key":"controle-de-acesso-quebrado","text":"Sei explicar por que o controle de acesso quebrado é um dos riscos mais recorrentes e como testar um IDOR na minha própria API."},{"key":"mapear-no-codigo","text":"Consigo mapear ao menos três categorias do Top 10 para trechos reais de um projeto meu ou de um laboratório (ex.: OWASP Juice Shop)."},{"key":"consultar-cheat-sheets","text":"Sei consultar o OWASP Cheat Sheet Series para encontrar a mitigação recomendada de cada categoria."},{"key":"listas-complementares","text":"Sei que existem listas complementares, como o OWASP API Security Top 10, e consigo dizer quando consultá-las."},{"key":"usar-em-revisao","text":"Já usei o Top 10 como checklist ao revisar um pull request ou ao desenhar uma funcionalidade nova."}]},{"track":"seguranca","slug":"seg-xss-csrf","title":"XSS e CSRF","description":"XSS injeta scripts no navegador da vítima por causa de saídas sem escape, enquanto CSRF induz um navegador já autenticado a enviar requisições que o usuário não pretendia. Cobre as variantes de XSS (refletido, armazenado, DOM), escape contextual, Content Security Policy, tokens anti-CSRF e cookies SameSite.","level":"junior","difficulty":3,"position":2,"prerequisites":["seg-owasp-top-10","web-dom-e-eventos"],"resources":[{"name":"OWASP — Cross Site Scripting Prevention Cheat Sheet","url":"https://cheatsheetseries.owasp.org/cheatsheets/Cross_Site_Scripting_Prevention_Cheat_Sheet.html"},{"name":"OWASP — Cross-Site Request Forgery Prevention Cheat Sheet","url":"https://cheatsheetseries.owasp.org/cheatsheets/Cross-Site_Request_Forgery_Prevention_Cheat_Sheet.html"},{"name":"PortSwigger Web Security Academy — Cross-site scripting","url":"https://portswigger.net/web-security/cross-site-scripting"},{"name":"Laravel — Proteção contra CSRF","url":"https://laravel.com/docs/csrf"}],"checklist":[{"key":"tipos-de-xss","text":"Consigo diferenciar XSS refletido, armazenado e baseado em DOM e demonstrar cada um em um laboratório."},{"key":"escape-contextual","text":"Sei aplicar escape de saída conforme o contexto (HTML, atributo, JavaScript, URL) e explico por que sanitizar só na entrada não basta."},{"key":"escape-desativado","text":"Sei identificar onde o framework desativa o escape automático (ex.: {!! !!} no Blade, dangerouslySetInnerHTML no React, v-html no Vue) e evito esses usos com dados não confiáveis."},{"key":"csp-basica","text":"Sei configurar uma Content Security Policy básica e explico como ela reduz o impacto de um XSS."},{"key":"defesa-csrf","text":"Consigo explicar como o CSRF funciona e implementar a defesa com token anti-CSRF e cookies SameSite."},{"key":"flags-de-cookie","text":"Sei configurar os atributos HttpOnly, Secure e SameSite de um cookie de sessão e dizer o que cada um previne."}]},{"track":"seguranca","slug":"seg-sql-injection","title":"SQL Injection","description":"Ataque em que a entrada do usuário altera a estrutura de uma consulta SQL, permitindo ler, alterar ou apagar dados e, em alguns casos, executar comandos no servidor. Cobre queries parametrizadas, uso seguro de ORMs e query builders, allowlist para identificadores e privilégio mínimo no usuário do banco.","level":"junior","difficulty":3,"position":3,"prerequisites":["seg-owasp-top-10","sql-select-e-join"],"resources":[{"name":"OWASP — SQL Injection Prevention Cheat Sheet","url":"https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html"},{"name":"OWASP — Query Parameterization Cheat Sheet","url":"https://cheatsheetseries.owasp.org/cheatsheets/Query_Parameterization_Cheat_Sheet.html"},{"name":"PortSwigger Web Security Academy — SQL injection","url":"https://portswigger.net/web-security/sql-injection"},{"name":"Manual do PHP — Prepared statements e stored procedures (PDO)","url":"https://www.php.net/manual/pt_BR/pdo.prepared-statements.php"}],"checklist":[{"key":"explicar-ataque","text":"Consigo explicar como a concatenação de strings em uma query permite SQL Injection e demonstrar com um payload simples em ambiente de teste."},{"key":"queries-parametrizadas","text":"Sei usar prepared statements com parâmetros vinculados (PDO, mysqli, pg ou mysql2 no Node) em vez de concatenar valores."},{"key":"orm-raw","text":"Sei identificar onde ORMs e query builders voltam a ser vulneráveis (ex.: DB::raw, whereRaw, orderBy com nome de coluna vindo do usuário)."},{"key":"allowlist-identificadores","text":"Sei tratar com allowlist o que não pode ser parametrizado, como nomes de colunas e direção de ordenação."},{"key":"privilegio-minimo-banco","text":"Já configurei um usuário de banco da aplicação sem permissões de DDL e sem acesso a outros schemas para limitar o dano de uma injeção."},{"key":"laboratorio-sqli","text":"Já explorei e corrigi uma SQL Injection em um laboratório (PortSwigger Academy, DVWA ou Juice Shop)."}]},{"track":"seguranca","slug":"seg-hash-senhas-criptografia-basica","title":"Hash de senhas e criptografia básica","description":"Como armazenar senhas com hash lento e salt (Argon2id, bcrypt, scrypt) e quando usar hash, HMAC, criptografia simétrica (AES-GCM) ou assimétrica. Evita erros clássicos como MD5 ou SHA-1 para senhas, criptografia caseira e reuso de nonce.","level":"junior","difficulty":3,"position":4,"prerequisites":["seg-principios-cia-menor-privilegio"],"resources":[{"name":"OWASP — Password Storage Cheat Sheet","url":"https://cheatsheetseries.owasp.org/cheatsheets/Password_Storage_Cheat_Sheet.html"},{"name":"OWASP — Cryptographic Storage Cheat Sheet","url":"https://cheatsheetseries.owasp.org/cheatsheets/Cryptographic_Storage_Cheat_Sheet.html"},{"name":"Manual do PHP — password_hash","url":"https://www.php.net/manual/pt_BR/function.password-hash.php"},{"name":"Livro: Serious Cryptography — Jean-Philippe Aumasson"}],"checklist":[{"key":"hash-vs-criptografia","text":"Consigo diferenciar hash, HMAC, criptografia simétrica e assimétrica e dizer quando usar cada uma."},{"key":"algoritmos-de-senha","text":"Sei explicar por que senhas exigem hash lento com salt (Argon2id, bcrypt) e por que MD5, SHA-1 e SHA-256 simples não servem para isso."},{"key":"implementar-hash","text":"Já implementei cadastro e login com password_hash e password_verify, Hash::make do Laravel ou bcrypt/argon2 no Node, incluindo rehash quando o custo muda."},{"key":"criptografia-autenticada","text":"Sei usar criptografia autenticada (AES-GCM ou libsodium) e explico por que nunca se reutiliza o nonce com a mesma chave."},{"key":"nao-inventar-cripto","text":"Consigo justificar por que não se inventa algoritmo criptográfico e priorizo bibliotecas consolidadas, como libsodium e OpenSSL."},{"key":"garantias-do-tls","text":"Sei explicar o que o TLS garante (confidencialidade, integridade e autenticação do servidor) e como verificar a validade de um certificado."}]},{"track":"seguranca","slug":"seg-autenticacao-sessoes","title":"Autenticação e sessões","description":"Como verificar quem é o usuário e manter essa identidade entre requisições: fluxos de login, recuperação de senha, MFA e cookies de sessão, com proteção contra fixação, roubo de sessão e força bruta. Falhas aqui levam direto à tomada de conta, por isso o desenho do fluxo importa tanto quanto o código.","level":"mid","difficulty":3,"position":5,"prerequisites":["seg-hash-senhas-criptografia-basica","seg-xss-csrf"],"resources":[{"name":"OWASP — Authentication Cheat Sheet","url":"https://cheatsheetseries.owasp.org/cheatsheets/Authentication_Cheat_Sheet.html"},{"name":"OWASP — Session Management Cheat Sheet","url":"https://cheatsheetseries.owasp.org/cheatsheets/Session_Management_Cheat_Sheet.html"},{"name":"PortSwigger Web Security Academy — Authentication vulnerabilities","url":"https://portswigger.net/web-security/authentication"},{"name":"NIST SP 800-63B — Digital Identity Guidelines (Authentication)","url":"https://pages.nist.gov/800-63-3/sp800-63b.html"}],"checklist":[{"key":"login-seguro","text":"Sei implementar um fluxo de login seguro com mensagens de erro genéricas, limite de tentativas e proteção contra credential stuffing."},{"key":"cookie-de-sessao","text":"Consigo configurar cookies de sessão com HttpOnly, Secure e SameSite e regenerar o ID da sessão após o login para evitar session fixation."},{"key":"logout-e-expiracao","text":"Sei implementar um logout que invalida a sessão no servidor e definir expiração por inatividade e expiração absoluta."},{"key":"tipos-de-mfa","text":"Consigo explicar os tipos de MFA (TOTP, WebAuthn/passkeys, SMS) e seus níveis de resistência a phishing."},{"key":"recuperacao-de-senha","text":"Sei desenhar a recuperação de senha com token aleatório de uso único, expiração curta e sem revelar se o e-mail existe."},{"key":"stateful-vs-stateless","text":"Consigo comparar sessão no servidor com tokens stateless e explicar o custo de revogação de cada abordagem."}]},{"track":"seguranca","slug":"seg-oauth2-jwt","title":"OAuth2 e JWT","description":"OAuth 2.0 é o framework de delegação de acesso (com OpenID Connect para identidade) e JWT é um formato de token assinado, muito usado e frequentemente mal aplicado. Cobre os fluxos (Authorization Code com PKCE, Client Credentials), a validação de assinatura e claims, expiração, refresh tokens e armadilhas como alg=none e armazenamento no navegador.","level":"mid","difficulty":4,"position":6,"prerequisites":["seg-autenticacao-sessoes","seg-hash-senhas-criptografia-basica","web-http-em-profundidade"],"resources":[{"name":"OAuth 2.0 — oauth.net","url":"https://oauth.net/2/"},{"name":"JWT.io — Introduction","url":"https://jwt.io/introduction"},{"name":"RFC 8725 — JSON Web Token Best Current Practices","url":"https://datatracker.ietf.org/doc/html/rfc8725"},{"name":"Livro: OAuth 2 in Action — Justin Richer e Antonio Sanso"}],"checklist":[{"key":"papeis-oauth","text":"Consigo explicar os papéis do OAuth 2.0 (resource owner, client, authorization server, resource server) e a diferença entre autenticação (OpenID Connect) e autorização (OAuth)."},{"key":"escolher-fluxo","text":"Sei escolher o fluxo adequado (Authorization Code com PKCE para apps de usuário, Client Credentials entre serviços) e explico por que Implicit e Password foram abandonados."},{"key":"validar-jwt","text":"Sei validar um JWT corretamente (assinatura, algoritmo fixado, iss, aud, exp e nbf) e explico os riscos de alg=none e de confusão entre HS256 e RS256."},{"key":"refresh-e-revogacao","text":"Consigo projetar tokens de acesso de vida curta com refresh token rotativo e uma estratégia de revogação."},{"key":"armazenamento-de-token","text":"Sei comparar guardar tokens em cookie HttpOnly e em localStorage e os riscos de XSS e CSRF de cada escolha."},{"key":"integrar-provedor","text":"Já integrei login com um provedor OAuth2/OpenID Connect (Google, Keycloak, Auth0 ou similar) validando state e nonce."}]},{"track":"seguranca","slug":"seg-autorizacao-rbac-abac","title":"Autorização (RBAC/ABAC)","description":"Define o que cada identidade autenticada pode fazer, usando papéis (RBAC), atributos e contexto (ABAC) ou relações entre recursos. Falhas de controle de acesso, como IDOR e escalada de privilégio, estão no topo do OWASP Top 10, então a checagem deve ser centralizada, negada por padrão e sempre feita no servidor.","level":"mid","difficulty":3,"position":7,"prerequisites":["seg-autenticacao-sessoes","seg-principios-cia-menor-privilegio"],"resources":[{"name":"OWASP — Authorization Cheat Sheet","url":"https://cheatsheetseries.owasp.org/cheatsheets/Authorization_Cheat_Sheet.html"},{"name":"PortSwigger Web Security Academy — Access control vulnerabilities","url":"https://portswigger.net/web-security/access-control"},{"name":"Laravel — Autorização (Gates e Policies)","url":"https://laravel.com/docs/authorization"},{"name":"NIST SP 800-162 — Guide to Attribute Based Access Control (ABAC)"}],"checklist":[{"key":"rbac-abac-rebac","text":"Consigo comparar RBAC, ABAC e autorização baseada em relações (ReBAC) e indicar quando cada modelo se encaixa."},{"key":"negar-por-padrao","text":"Sei aplicar 'negar por padrão' e centralizar as decisões em um ponto único (middleware, policies e gates do Laravel, guards) em vez de espalhar ifs pelo código."},{"key":"corrigir-idor","text":"Consigo identificar e corrigir um IDOR verificando a propriedade do recurso no servidor, e não apenas escondendo o ID ou o botão na interface."},{"key":"escalada-de-privilegio","text":"Sei testar escalada de privilégio horizontal e vertical em uma API alterando papéis, IDs e métodos HTTP."},{"key":"isolamento-multi-tenant","text":"Sei garantir isolamento entre tenants com filtro obrigatório em toda consulta (global scopes ou row-level security)."},{"key":"testes-de-permissao","text":"Já escrevi testes automatizados que cobrem a matriz de permissões (quem pode e quem não pode) de um recurso."}]},{"track":"seguranca","slug":"seg-gestao-segredos","title":"Gestão de segredos","description":"Como guardar, distribuir e rotacionar senhas de banco, chaves de API, tokens e certificados sem deixá-los no código, em imagens Docker ou em logs. Cobre variáveis de ambiente, cofres de segredos (Vault, AWS Secrets Manager), rotação sem downtime e detecção de vazamentos em repositórios.","level":"mid","difficulty":3,"position":8,"prerequisites":["seg-hash-senhas-criptografia-basica","seg-principios-cia-menor-privilegio"],"resources":[{"name":"OWASP — Secrets Management Cheat Sheet","url":"https://cheatsheetseries.owasp.org/cheatsheets/Secrets_Management_Cheat_Sheet.html"},{"name":"The Twelve-Factor App — Config","url":"https://12factor.net/config"},{"name":"HashiCorp Vault — Documentação","url":"https://developer.hashicorp.com/vault/docs"},{"name":"Gitleaks — detecção de segredos em repositórios","url":"https://github.com/gitleaks/gitleaks"}],"checklist":[{"key":"fora-do-codigo","text":"Sei manter segredos fora do código e do controle de versão (.env no .gitignore, variáveis de ambiente, arquivos montados) e explico os limites de cada abordagem."},{"key":"usar-cofre","text":"Consigo explicar o que um cofre de segredos oferece (controle de acesso, auditoria, rotação, segredos dinâmicos) e já usei um ou o equivalente do meu provedor de nuvem."},{"key":"rotacao-sem-downtime","text":"Sei planejar a rotação de um segredo sem downtime, por exemplo mantendo duas credenciais válidas durante a troca."},{"key":"detectar-vazamentos","text":"Já configurei uma ferramenta de detecção de segredos (gitleaks, trufflehog ou secret scanning) em um hook de pre-commit ou no pipeline de CI."},{"key":"resposta-a-vazamento","text":"Sei o que fazer quando um segredo vaza: revogar e rotacionar primeiro, depois investigar o uso indevido e só então limpar o histórico do Git."},{"key":"imagens-e-logs","text":"Consigo garantir que segredos não vão parar em imagens Docker (uso BuildKit secrets em vez de ARG/ENV), logs ou mensagens de erro."}]},{"track":"seguranca","slug":"seg-dependencias-vulneraveis","title":"Dependências vulneráveis","description":"Bibliotecas de terceiros trazem vulnerabilidades conhecidas (CVEs) e riscos de cadeia de suprimentos, como pacotes maliciosos e typosquatting. Cobre auditoria (npm audit, composer audit), atualizações automatizadas com Dependabot ou Renovate, lockfiles e geração de SBOM.","level":"mid","difficulty":2,"position":9,"prerequisites":["seg-principios-cia-menor-privilegio","php-composer-e-psr"],"resources":[{"name":"OWASP — Vulnerable Dependency Management Cheat Sheet","url":"https://cheatsheetseries.owasp.org/cheatsheets/Vulnerable_Dependency_Management_Cheat_Sheet.html"},{"name":"npm Docs — npm audit","url":"https://docs.npmjs.com/cli/commands/npm-audit"},{"name":"Composer — comando audit","url":"https://getcomposer.org/doc/03-cli.md#audit"},{"name":"OSV — Open Source Vulnerabilities","url":"https://osv.dev/"}],"checklist":[{"key":"cve-e-cvss","text":"Sei explicar o que são CVE e CVSS e priorizar uma vulnerabilidade considerando explorabilidade e contexto real, não só a nota."},{"key":"rodar-auditoria","text":"Já rodei npm audit e composer audit (ou equivalente) em um projeto e triei os resultados, distinguindo dependências diretas e transitivas."},{"key":"lockfiles","text":"Sei explicar o papel dos lockfiles (package-lock.json, composer.lock) e uso instalações reproduzíveis (npm ci) no CI."},{"key":"atualizacao-automatica","text":"Já configurei Dependabot ou Renovate para abrir pull requests de atualização e sei definir um prazo de correção por severidade."},{"key":"cadeia-de-suprimentos","text":"Consigo descrever ataques de cadeia de suprimentos (typosquatting, dependency confusion, pacote comprometido) e medidas para reduzi-los."},{"key":"gerar-sbom","text":"Sei o que é um SBOM e consigo gerar um para um projeto (CycloneDX ou SPDX)."}]},{"track":"seguranca","slug":"seg-threat-modeling","title":"Threat modeling","description":"Prática de identificar, ainda no design, o que pode dar errado em um sistema: mapear ativos, fluxos de dados e fronteiras de confiança, enumerar ameaças com STRIDE ou árvores de ataque e definir mitigações priorizadas. Traz a segurança para o início do ciclo, quando corrigir é mais barato.","level":"senior","difficulty":4,"position":10,"prerequisites":["seg-owasp-top-10","seg-autenticacao-sessoes","seg-autorizacao-rbac-abac"],"resources":[{"name":"Threat Modeling Manifesto","url":"https://www.threatmodelingmanifesto.org/"},{"name":"OWASP Threat Dragon","url":"https://owasp.org/www-project-threat-dragon/"},{"name":"MITRE ATT&CK","url":"https://attack.mitre.org/"},{"name":"Livro: Threat Modeling: Designing for Security — Adam Shostack"}],"checklist":[{"key":"quatro-perguntas","text":"Consigo conduzir uma sessão de threat modeling com as quatro perguntas clássicas (o que estamos construindo, o que pode dar errado, o que faremos a respeito, se foi suficiente)."},{"key":"dfd-e-fronteiras","text":"Sei desenhar um diagrama de fluxo de dados (DFD) com ativos, atores, armazenamentos e fronteiras de confiança."},{"key":"aplicar-stride","text":"Sei aplicar STRIDE (spoofing, tampering, repudiation, information disclosure, denial of service e elevation of privilege) a cada elemento do diagrama."},{"key":"priorizar-e-mitigar","text":"Consigo priorizar ameaças por probabilidade e impacto e propor mitigações rastreáveis (reduzir, eliminar, transferir ou aceitar o risco)."},{"key":"modelo-de-sistema-real","text":"Já produzi e revisei o threat model de um sistema real e registrei os resultados como itens de backlog."},{"key":"integrar-ao-ciclo","text":"Sei integrar o threat modeling ao ciclo de desenvolvimento, revisando o modelo a cada mudança arquitetural relevante."}]},{"track":"seguranca","slug":"seg-hardening-auditoria","title":"Hardening e auditoria","description":"Reduzir a superfície de ataque de servidores, contêineres e da aplicação (TLS, cabeçalhos HTTP, configuração mínima, imagens enxutas) e manter trilhas de auditoria confiáveis para detectar e investigar incidentes. Inclui benchmarks CIS, varredura de vulnerabilidades, logs protegidos contra adulteração e noções de resposta a incidentes.","level":"senior","difficulty":4,"position":11,"prerequisites":["seg-gestao-segredos","seg-dependencias-vulneraveis","seg-threat-modeling"],"resources":[{"name":"OWASP Application Security Verification Standard (ASVS)","url":"https://owasp.org/www-project-application-security-verification-standard/"},{"name":"CIS Benchmarks","url":"https://www.cisecurity.org/cis-benchmarks"},{"name":"OWASP — Docker Security Cheat Sheet","url":"https://cheatsheetseries.owasp.org/cheatsheets/Docker_Security_Cheat_Sheet.html"},{"name":"OWASP — Logging Cheat Sheet","url":"https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html"}],"checklist":[{"key":"superficie-de-ataque","text":"Consigo inventariar a superfície de ataque de um serviço (portas, endpoints, usuários, pacotes, permissões) e reduzi-la ao mínimo necessário."},{"key":"tls-e-cabecalhos","text":"Sei configurar TLS moderno e cabeçalhos de segurança HTTP (HSTS, CSP, X-Content-Type-Options, Referrer-Policy) e validá-los com uma ferramenta de varredura."},{"key":"endurecer-conteineres","text":"Sei endurecer contêineres: imagem mínima, usuário não root, sistema de arquivos somente leitura e capabilities removidas."},{"key":"auditar-com-cis-asvs","text":"Já usei um benchmark CIS ou o OWASP ASVS como checklist para auditar um serviço e registrei as não conformidades."},{"key":"logs-de-auditoria","text":"Sei desenhar logs de auditoria (quem, o quê, quando, de onde) sem registrar dados sensíveis e protegê-los contra adulteração."},{"key":"deteccao-e-resposta","text":"Consigo descrever um plano básico de resposta a incidentes e quais alertas eu configuraria para detecção (logins anômalos, picos de 401/403, mudanças de permissão)."}]},{"track":"carreira-soft-skills","slug":"car-comunicacao-escrita","title":"Comunicação escrita","description":"Escrever mensagens, tickets, descrições de pull request e commits que outras pessoas entendem sem precisar de reunião: começar pelo ponto principal, dar contexto suficiente, ser objetivo e revisar antes de enviar. É uma das habilidades que mais diferenciam quem trabalha bem em times remotos e assíncronos.","level":"beginner","difficulty":2,"position":0,"prerequisites":[],"resources":[{"name":"Google — Technical Writing One","url":"https://developers.google.com/tech-writing/one"},{"name":"Chris Beams — How to Write a Git Commit Message","url":"https://cbea.ms/git-commit/"},{"name":"Conventional Commits (pt-BR)","url":"https://www.conventionalcommits.org/pt-br/v1.0.0/"},{"name":"Livro: On Writing Well — William Zinsser"}],"checklist":[{"key":"mensagem-direta","text":"Já reescrevi uma mensagem minha de chat ou e-mail para começar pelo ponto principal e pedir uma ação clara (decisão, revisão ou resposta) com prazo."},{"key":"commits-explicativos","text":"Já escrevi mensagens de commit que explicam o porquê da mudança (assunto curto no imperativo e corpo quando necessário) e as usei depois para entender o histórico."},{"key":"descricao-de-pr","text":"Já escrevi uma descrição de pull request com contexto, o que mudou, como testar e riscos, e recebi menos perguntas na revisão."},{"key":"relato-de-bug","text":"Já abri um relato de bug com passos para reproduzir, resultado esperado e resultado obtido, e a pessoa conseguiu reproduzi-lo sem me pedir mais informações."},{"key":"revisar-antes-de-enviar","text":"Já reli e cortei o que não era necessário em um texto importante antes de enviá-lo e pedi a alguém que o revisasse."},{"key":"texto-no-lugar-de-reuniao","text":"Já escrevi um resumo ou uma proposta que dispensou uma reunião e sei quando um texto assíncrono funciona melhor que uma chamada."}]},{"track":"carreira-soft-skills","slug":"car-pedir-ajuda-debugar-voz-alta","title":"Pedir ajuda e debugar em voz alta","description":"Saber quando e como pedir ajuda sem travar nem incomodar: tentar por um tempo definido, montar um exemplo mínimo reproduzível e formular uma pergunta específica. Inclui o 'rubber duck debugging' (explicar o problema em voz alta ou por escrito), que muitas vezes revela a causa antes de alguém responder.","level":"beginner","difficulty":1,"position":1,"prerequisites":[],"resources":[{"name":"Julia Evans — How to ask good questions","url":"https://jvns.ca/blog/good-questions/"},{"name":"Stack Overflow — How to create a Minimal, Reproducible Example (Central de Ajuda)"},{"name":"No Hello — por que não mandar só 'oi' no chat","url":"https://nohello.net/pt/"},{"name":"Livro: The Pragmatic Programmer — Andrew Hunt e David Thomas (rubber duck debugging)"}],"checklist":[{"key":"timebox-antes-de-pedir","text":"Já defini um limite de tempo para tentar sozinho (ex.: 30 a 60 minutos) antes de pedir ajuda e cumpri esse limite em uma tarefa real."},{"key":"pergunta-completa","text":"Já fiz uma pergunta a um colega ou em um fórum com contexto, o que tentei, o que esperava e o que aconteceu, incluindo a mensagem de erro e as versões usadas."},{"key":"exemplo-minimo","text":"Já reduzi um problema a um exemplo mínimo reproduzível e, nesse processo, encontrei a causa ou facilitei a ajuda."},{"key":"rubber-duck","text":"Já usei rubber duck debugging (explicar o problema em voz alta ou por escrito) e cheguei à causa sozinho."},{"key":"fechar-o-ciclo","text":"Depois de resolver um problema, já voltei à pessoa ou ao tópico com a solução e anotei o que aprendi."}]},{"track":"carreira-soft-skills","slug":"car-gestao-tempo-foco","title":"Gestão de tempo e foco","description":"Organizar o dia para ter blocos de trabalho profundo, lidar com interrupções e reuniões e planejar o que cabe na semana. Cobre time-boxing, Pomodoro, priorização diária, o custo da troca de contexto e como manter um backlog pessoal sem se perder em tarefas urgentes e pouco importantes.","level":"junior","difficulty":2,"position":2,"prerequisites":[],"resources":[{"name":"Paul Graham — Maker's Schedule, Manager's Schedule","url":"https://www.paulgraham.com/makersschedule.html"},{"name":"Livro: Deep Work — Cal Newport"},{"name":"Livro: Peopleware — Tom DeMarco e Timothy Lister"},{"name":"Livro: Getting Things Done — David Allen"}],"checklist":[{"key":"prioridades-do-dia","text":"Já planejei meus dias com no máximo 3 prioridades por pelo menos duas semanas seguidas e revisei o resultado no fim de cada dia."},{"key":"bloco-de-foco","text":"Já reservei blocos de foco na agenda (ex.: 2 horas sem notificações) e medi quanto consegui entregar neles."},{"key":"timebox-pomodoro","text":"Já testei time-boxing ou Pomodoro em tarefas reais e sei dizer o que funcionou para mim e o que não funcionou."},{"key":"troca-de-contexto","text":"Consigo explicar o custo da troca de contexto e já adotei uma prática para reduzi-lo (ex.: limitar tarefas em andamento e agrupar respostas de chat)."},{"key":"dizer-nao-ou-negociar","text":"Já negociei um prazo ou adiei um pedido, explicando o impacto nas minhas prioridades atuais."},{"key":"backlog-pessoal","text":"Mantenho um backlog pessoal (lista priorizada, por exemplo com a matriz urgente/importante) e já o usei para decidir o que fazer primeiro."}]},{"track":"carreira-soft-skills","slug":"car-documentacao-tecnica","title":"Documentação técnica","description":"Documentar código, APIs e decisões para que o próximo desenvolvedor (ou você daqui a seis meses) consiga usar e manter o sistema: README, guias de instalação, documentação de API, diagramas e runbooks. Cobre o modelo Diátaxis (tutorial, guia prático, referência e explicação) e como manter a documentação viva e perto do código.","level":"junior","difficulty":2,"position":3,"prerequisites":["car-comunicacao-escrita"],"resources":[{"name":"Diátaxis — framework de documentação","url":"https://diataxis.fr/"},{"name":"Write the Docs — Documentation Guide","url":"https://www.writethedocs.org/guide/"},{"name":"Google — Technical Writing Two","url":"https://developers.google.com/tech-writing/two"},{"name":"Make a README","url":"https://www.makeareadme.com/"}],"checklist":[{"key":"readme-completo","text":"Já escrevi um README que permite a alguém instalar, rodar e testar o projeto sem precisar me perguntar nada."},{"key":"teste-com-outra-pessoa","text":"Já pedi a alguém para seguir minha documentação do zero e corrigi os pontos em que a pessoa travou."},{"key":"tipos-diataxis","text":"Sei diferenciar tutorial, guia prático, referência e explicação (Diátaxis) e já separei esses tipos em uma documentação minha."},{"key":"documentar-api-ou-modulo","text":"Já documentei uma API ou módulo (ex.: com OpenAPI, PHPDoc ou TSDoc) incluindo exemplos de uso e de erro."},{"key":"runbook","text":"Já escrevi um runbook ou guia de resolução de problemas para uma tarefa operacional recorrente."},{"key":"doc-junto-do-codigo","text":"Mantenho a documentação no repositório e a atualizo junto com as mudanças de código, revisando-a no pull request."}]},{"track":"carreira-soft-skills","slug":"car-estimativas","title":"Estimativas","description":"Estimar esforço e prazo com honestidade: decompor o trabalho, usar referências históricas, comunicar incerteza com faixas em vez de datas exatas e revisar a estimativa quando a informação muda. Cobre o viés do planejamento (planning fallacy), story points versus tempo e o que fazer quando cobram prazo sem escopo definido.","level":"mid","difficulty":3,"position":4,"prerequisites":["car-gestao-tempo-foco","car-comunicacao-escrita"],"resources":[{"name":"Livro: Software Estimation: Demystifying the Black Art — Steve McConnell"},{"name":"Joel Spolsky — Evidence Based Scheduling","url":"https://www.joelonsoftware.com/2007/10/26/evidence-based-scheduling/"},{"name":"Livro: The Mythical Man-Month — Frederick P. Brooks Jr."},{"name":"Atlassian — What are story points and how do you estimate them?","url":"https://www.atlassian.com/agile/project-management/estimation"}],"checklist":[{"key":"decompor-antes-de-estimar","text":"Já decompus uma funcionalidade em tarefas de no máximo 1 a 2 dias antes de estimar."},{"key":"faixa-e-premissas","text":"Já apresentei uma estimativa como faixa (otimista, provável e pessimista), explicitando premissas e riscos."},{"key":"comparar-com-realizado","text":"Já comparei minhas estimativas com o tempo realmente gasto em pelo menos 5 tarefas e ajustei meu método a partir disso."},{"key":"pontos-vs-tempo","text":"Sei explicar a diferença entre story points e horas e quando cada um faz sentido."},{"key":"avisar-do-risco-cedo","text":"Já avisei com antecedência que um prazo estava em risco, levando a nova previsão e opções (escopo, prazo ou apoio)."},{"key":"vies-do-planejamento","text":"Consigo explicar o viés do planejamento (planning fallacy) e a lei de Hofstadter e dar um exemplo de quando caí neles."}]},{"track":"carreira-soft-skills","slug":"car-feedback-dar-receber","title":"Feedback (dar e receber)","description":"Dar feedback específico, oportuno e acionável (modelo Situação-Comportamento-Impacto) e receber feedback sem defensividade, transformando-o em ações. Aplica-se a code review, 1:1s, avaliações de desempenho e conversas difíceis, e é a base para mentoria e liderança.","level":"mid","difficulty":3,"position":5,"prerequisites":["car-comunicacao-escrita","car-pedir-ajuda-debugar-voz-alta"],"resources":[{"name":"Google Engineering Practices — How to write code review comments","url":"https://google.github.io/eng-practices/review/reviewer/comments.html"},{"name":"Livro: Radical Candor — Kim Scott"},{"name":"Livro: Thanks for the Feedback — Douglas Stone e Sheila Heen"},{"name":"Livro: Crucial Conversations — Patterson, Grenny, McMillan e Switzler"}],"checklist":[{"key":"feedback-sbi","text":"Já dei um feedback no modelo Situação-Comportamento-Impacto, com um exemplo concreto e observável (e não um julgamento sobre a pessoa)."},{"key":"feedback-positivo","text":"Já dei um feedback positivo específico a um colega, dizendo o que foi bom e qual foi o efeito."},{"key":"review-construtivo","text":"Já escrevi comentários de code review que explicam o porquê, fazem perguntas e separam o que é bloqueante do que é sugestão."},{"key":"pedir-feedback","text":"Já pedi feedback a alguém (colega, líder ou pessoa de outro time) com uma pergunta específica, como 'o que eu poderia ter feito melhor nessa entrega?'."},{"key":"receber-sem-defesa","text":"Já recebi um feedback difícil sem me justificar de imediato: agradeci, pedi exemplos e registrei ações."},{"key":"agir-e-voltar","text":"Já agi sobre um feedback recebido e voltei à pessoa para mostrar o resultado."}]},{"track":"carreira-soft-skills","slug":"car-metodologias-ageis","title":"Metodologias ágeis","description":"Os princípios do Manifesto Ágil e como eles aparecem na prática em Scrum (sprints, papéis e eventos), Kanban (fluxo e limite de trabalho em progresso) e XP (integração contínua, testes e programação em par). O foco é entender o propósito de cada cerimônia e adaptar a prática ao contexto do time, em vez de seguir um ritual vazio.","level":"mid","difficulty":2,"position":6,"prerequisites":["car-comunicacao-escrita","car-gestao-tempo-foco"],"resources":[{"name":"Manifesto Ágil — Princípios por trás do Manifesto","url":"https://agilemanifesto.org/iso/ptbr/principles.html"},{"name":"The Scrum Guide","url":"https://scrumguides.org/scrum-guide.html"},{"name":"The Kanban Guide","url":"https://kanbanguides.org/"},{"name":"Martin Fowler — Flaccid Scrum","url":"https://martinfowler.com/bliki/FlaccidScrum.html"}],"checklist":[{"key":"valores-e-principios","text":"Consigo explicar os 4 valores e alguns dos 12 princípios do Manifesto Ágil com exemplos do meu dia a dia."},{"key":"eventos-do-scrum","text":"Sei descrever os eventos do Scrum (planejamento, daily, revisão e retrospectiva) e o objetivo de cada um, e já participei de todos."},{"key":"kanban-com-wip","text":"Já usei um quadro Kanban com limite de trabalho em progresso (WIP) e observei o efeito no fluxo."},{"key":"retrospectiva-com-acao","text":"Já contribuí em uma retrospectiva com uma observação específica e acompanhei uma ação de melhoria até o fim."},{"key":"historia-com-criterios","text":"Já escrevi uma história de usuário com critérios de aceite claros e verificáveis."},{"key":"adaptar-ao-contexto","text":"Consigo apontar o que um ritual ágil tem de útil e de excessivo no meu time e já propus um ajuste."}]},{"track":"carreira-soft-skills","slug":"car-mentoria","title":"Mentoria","description":"Aprender com quem tem mais experiência (mentoria recebida) e, com o tempo, ajudar quem está começando (mentoria dada): combinar objetivos, preparar as conversas, fazer boas perguntas e dar autonomia em vez de respostas prontas. Também cobre pareamento, onboarding de novos colegas e como saber se a mentoria está funcionando.","level":"mid","difficulty":3,"position":7,"prerequisites":["car-feedback-dar-receber","car-pedir-ajuda-debugar-voz-alta"],"resources":[{"name":"Livro: The Manager's Path — Camille Fournier (capítulo sobre mentoria)"},{"name":"Livro: The Coaching Habit — Michael Bungay Stanier"},{"name":"Livro: Pragmatic Thinking and Learning — Andy Hunt"},{"name":"John Allspaw — On Being A Senior Engineer (inclui mentoria e patrocínio)","url":"https://www.kitchensoap.com/2012/10/25/on-being-a-senior-engineer/"}],"checklist":[{"key":"mentoria-recebida","text":"Já tive (ou busquei) um mentor e combinamos objetivos, frequência e formato dos encontros."},{"key":"pauta-de-mentoria","text":"Já preparei uma pauta para um encontro de mentoria, com temas, dúvidas e o que eu já tinha tentado."},{"key":"pair-programming","text":"Já fiz pair programming como quem aprende e como quem ensina, alternando as funções."},{"key":"ajudar-iniciante","text":"Já ajudei uma pessoa menos experiente em uma tarefa real (ex.: onboarding ou revisão de código didática)."},{"key":"perguntas-em-vez-de-respostas","text":"Já conduzi uma ajuda com perguntas que levaram a pessoa a achar a solução, em vez de entregar a resposta pronta."},{"key":"ajustar-a-mentoria","text":"Já pedi feedback à pessoa mentorada ou ao meu mentor sobre o que está funcionando e ajustei a forma de trabalharmos."}]},{"track":"carreira-soft-skills","slug":"car-priorizacao-negociacao","title":"Priorização e negociação","description":"Decidir o que fazer primeiro quando tudo parece urgente: critérios de valor, esforço e risco (RICE, MoSCoW e custo do atraso) e negociação de escopo, prazo e qualidade com produto e outras áreas. Cobre dizer 'não' com alternativas, expor trade-offs com dados e chegar a acordos em que todos saem comprometidos.","level":"mid","difficulty":3,"position":8,"prerequisites":["car-estimativas","car-metodologias-ageis"],"resources":[{"name":"Intercom — RICE: Simple prioritization for product managers","url":"https://www.intercom.com/blog/rice-simple-prioritization-for-product-managers"},{"name":"Livro: Getting to Yes — Roger Fisher, William Ury e Bruce Patton"},{"name":"Livro: Never Split the Difference — Chris Voss"}],"checklist":[{"key":"criterio-explicito","text":"Já usei um critério explícito (ex.: RICE, MoSCoW ou valor versus esforço) para ordenar um backlog ou uma lista de pedidos."},{"key":"nao-com-alternativa","text":"Já respondi a um pedido urgente com um 'não, mas' (alternativa de escopo, prazo ou ajuda) em vez de aceitar tudo."},{"key":"cortar-escopo","text":"Já negociei o corte de escopo de uma entrega para cumprir um prazo, deixando claro o que ficou de fora e o risco."},{"key":"expor-tradeoffs","text":"Já apresentei a uma pessoa de negócio os trade-offs (prazo, escopo, qualidade e custo) de uma decisão, usando dados e não opiniões."},{"key":"interesses-vs-posicoes","text":"Sei diferenciar interesses de posições em uma negociação e já usei isso para chegar a um acordo."},{"key":"custo-do-atraso","text":"Consigo explicar custo do atraso e dívida técnica em termos que uma pessoa de negócio entende."}]},{"track":"carreira-soft-skills","slug":"car-apresentacoes-tecnicas","title":"Apresentações técnicas","description":"Explicar um tema técnico para públicos diferentes (time, gestores, pessoas de outras áreas) de forma clara: definir a mensagem principal, estruturar a fala, usar slides e diagramas com economia e conduzir demonstrações ao vivo sem tropeços. Cobre também responder perguntas difíceis, controlar o tempo e coletar feedback depois.","level":"mid","difficulty":3,"position":9,"prerequisites":["car-comunicacao-escrita","car-documentacao-tecnica"],"resources":[{"name":"Zach Holman — Tips for Public Speaking (speaking.io)","url":"https://speaking.io/"},{"name":"Livro: Presentation Zen — Garr Reynolds"},{"name":"Livro: Slide:ology — Nancy Duarte"},{"name":"Livro: Storytelling com Dados — Cole Nussbaumer Knaflic"}],"checklist":[{"key":"mensagem-central","text":"Já apresentei um tema técnico a partir de uma mensagem central (uma frase) e adaptei o nível de detalhe ao público."},{"key":"estrutura-da-fala","text":"Já estruturei uma apresentação com início (problema), meio (solução e trade-offs) e fim (próximos passos ou pedido)."},{"key":"slides-enxutos","text":"Já preparei slides com pouco texto e um diagrama claro e cortei conteúdo para caber no tempo."},{"key":"demo-com-plano-b","text":"Já fiz uma demonstração ao vivo com ensaio prévio e um plano B (ex.: vídeo ou captura de tela) para o caso de algo falhar."},{"key":"perguntas-dificeis","text":"Já respondi a perguntas difíceis na hora, inclusive com 'não sei, vou verificar e retorno', e voltei com a resposta."},{"key":"feedback-da-apresentacao","text":"Já pedi feedback sobre uma apresentação minha a pelo menos duas pessoas e apliquei algo na vez seguinte."}]},{"track":"carreira-soft-skills","slug":"car-lideranca-tecnica","title":"Liderança técnica","description":"Conduzir tecnicamente um time ou projeto sem necessariamente ser gestor: definir direção técnica, desbloquear pessoas, delegar, revisar com critério e garantir qualidade e entrega. Cobre os papéis de tech lead e de engenheiro staff, o equilíbrio entre codar e liderar e como fazer o time crescer em vez de virar um gargalo.","level":"senior","difficulty":4,"position":10,"prerequisites":["car-mentoria","car-feedback-dar-receber","car-priorizacao-negociacao"],"resources":[{"name":"StaffEng — guias e histórias de engenheiros staff","url":"https://staffeng.com/"},{"name":"John Allspaw — On Being A Senior Engineer","url":"https://www.kitchensoap.com/2012/10/25/on-being-a-senior-engineer/"},{"name":"Livro: The Staff Engineer's Path — Tanya Reilly"},{"name":"Livro: The Manager's Path — Camille Fournier"}],"checklist":[{"key":"liderar-iniciativa","text":"Já liderei uma iniciativa técnica de ponta a ponta (proposta, divisão do trabalho, acompanhamento e entrega) envolvendo mais de uma pessoa."},{"key":"delegar-com-contexto","text":"Já deleguei uma tarefa relevante com contexto, critério de sucesso e prazo e acompanhei sem microgerenciar."},{"key":"desbloquear-outros","text":"Já identifiquei e removi um bloqueio de outra pessoa ou de outro time (ex.: decisão pendente, acesso ou dependência)."},{"key":"alinhar-expectativas","text":"Já alinhei expectativas com produto e outros stakeholders sobre escopo, riscos e prazo de uma entrega."},{"key":"equilibrar-codar-e-liderar","text":"Já abri mão de uma tarefa técnica interessante para dar espaço a outra pessoa crescer e sei explicar como divido meu tempo entre codar e liderar."},{"key":"padrao-do-time","text":"Já ajudei o time a adotar uma prática ou padrão (ex.: checklist de code review, ADRs ou convenções) e verifiquei que ela passou a ser seguida."}]},{"track":"carreira-soft-skills","slug":"car-tomada-decisao-influencia","title":"Tomada de decisão e influência","description":"Decidir sob incerteza e conseguir adesão sem depender de cargo: separar decisões reversíveis das irreversíveis, usar dados e pré-mortem, registrar o raciocínio e construir apoio com argumentos, relacionamento e confiança. Inclui discordar e se comprometer (disagree and commit) e comunicar decisões e seus trade-offs de forma transparente.","level":"senior","difficulty":4,"position":11,"prerequisites":["car-lideranca-tecnica","car-priorizacao-negociacao","car-apresentacoes-tecnicas"],"resources":[{"name":"Gary Klein — Performing a Project Premortem (Harvard Business Review)","url":"https://hbr.org/2007/09/performing-a-project-premortem"},{"name":"Livro: Influence: The Psychology of Persuasion — Robert Cialdini"},{"name":"Livro: Thinking, Fast and Slow — Daniel Kahneman"},{"name":"Livro: Decisive — Chip Heath e Dan Heath"}],"checklist":[{"key":"reversivel-ou-irreversivel","text":"Consigo diferenciar decisões reversíveis de irreversíveis e já decidi rapidamente nas reversíveis para não gastar tempo demais com análise."},{"key":"registrar-decisao","text":"Já registrei uma decisão relevante (ex.: em um ADR) com contexto, alternativas e critérios e a compartilhei com o time."},{"key":"premortem","text":"Já conduzi ou participei de um pré-mortem antes de um projeto e usei os riscos levantados para mudar o plano."},{"key":"influenciar-sem-cargo","text":"Já convenci outras pessoas, sem ser quem decide, a adotar uma mudança técnica usando dados, exemplos e escuta das objeções."},{"key":"discordar-e-comprometer","text":"Já discordei de uma decisão com argumentos, aceitei o resultado e me comprometi com a execução (disagree and commit)."},{"key":"revisitar-decisao-ruim","text":"Já revisitei uma decisão minha que se mostrou ruim, assumi o erro abertamente e ajustei o rumo."}]}],"projects":[{"slug":"encurtador-de-url","title":"Encurtador de URL","description":"Construa uma API em Laravel que cria links curtos com slug único, redireciona para a URL original e conta os cliques de forma atômica, com uma interface Vue simples para encurtar e listar os links. O projeto treina modelagem com índice único, concorrência em contadores, validação de entrada e testes de feature.","level":"junior","difficulty":2,"position":0,"topics":["sql-indices","sql-transacoes-e-acid","vue-composition-api-script-setup","qual-testes-integracao","php-rotas-e-controllers","php-migrations-e-eloquent-basico","php-validacao-e-form-requests"],"milestones":[{"key":"modelagem-links","title":"Modelagem e migration de links","acceptanceCriteria":["A migration cria a tabela `links` com `original_url`, `slug` único, `clicks` (inteiro com default 0) e timestamps","Inserir dois links com o mesmo slug lança erro de constraint do banco (coberto por um teste)","Existe uma factory de Link que gera dados válidos para uso nos testes"],"xp":20},{"key":"criar-link-com-slug-unico","title":"Criação de links com slug único","acceptanceCriteria":["POST /api/links com uma URL válida retorna 201 com o slug curto e a URL curta completa no corpo","Em caso de colisão, um novo slug é gerado até ser único (um teste força a colisão com um gerador falso)","URLs inválidas ou com esquema diferente de http/https (ex.: javascript:) retornam 422 com mensagens por campo"],"xp":30},{"key":"redirecionamento-e-cliques","title":"Redirecionamento e contagem atômica de cliques","acceptanceCriteria":["GET /{slug} responde 302 com o header Location da URL original (o README explica por que 301 prejudicaria a contagem)","Slug inexistente retorna 404 e não altera nenhum contador","O contador usa um único UPDATE atômico (`increment`), sem ler o valor em PHP e gravar de volta","Um teste faz 20 acessos seguidos e confirma que `clicks` vale 20"],"xp":35},{"key":"interface-vue","title":"Interface Vue para encurtar e listar","acceptanceCriteria":["O formulário valida a URL antes de enviar e mostra os erros 422 devolvidos pela API","Após encurtar, a URL curta aparece na lista com um botão que a copia para a área de transferência","A lista mostra URL original, slug e número de cliques, com estados de carregando, erro e vazio","A SPA em modo dev consome a API sem erros de CORS (proxy do Vite ou configuração do Laravel)"],"xp":30},{"key":"testes-e-entrega","title":"Testes de feature e entrega","acceptanceCriteria":["Testes de feature cobrem criação, colisão de slug, validação, redirecionamento e contagem de cliques","`php artisan test` passa em um clone limpo, usando `RefreshDatabase` e SQLite em memória","O README explica como instalar, migrar o banco, subir API e front e lista os endpoints"],"xp":25}]},{"slug":"todo-com-api-e-vue","title":"To-do com API e Vue","description":"Implemente um CRUD de tarefas em Laravel, com Form Requests para validação e API Resources para padronizar as respostas, e consuma a API em uma SPA Vue 3 com Pinia e Vue Router. O projeto treina o contrato entre back-end e front-end, o gerenciamento de estado e o tratamento dos estados de loading, erro e lista vazia.","level":"junior","difficulty":2,"position":1,"topics":["vue-pinia","vue-router","vue-formularios-e-validacao","web-fetch-e-http","php-rotas-e-controllers","php-migrations-e-eloquent-basico","php-validacao-e-form-requests","php-api-resources"],"milestones":[{"key":"api-crud-de-tarefas","title":"API CRUD de tarefas","acceptanceCriteria":["A migration cria `tasks` com `title`, `description` (opcional), `done` (boolean, default false), `due_date` (opcional) e timestamps","`Route::apiResource('tasks')` responde: GET lista, POST cria (201), GET por id, PUT/PATCH atualiza e DELETE remove (204)","Buscar, atualizar ou excluir um id inexistente retorna 404 em JSON, não uma página HTML"],"xp":25},{"key":"validacao-e-api-resources","title":"Form Requests e API Resources","acceptanceCriteria":["`StoreTaskRequest` e `UpdateTaskRequest` concentram as regras (título obrigatório com no máximo 120 caracteres) e devolvem 422 com erros por campo","`TaskResource` define o formato público da resposta (id, title, done, due_date em ISO 8601) sem expor colunas internas","A listagem é paginada via `TaskResource::collection` e aceita o filtro `?done=true` ou `?done=false`"],"xp":30},{"key":"spa-com-router-e-pinia","title":"SPA com Router e store Pinia","acceptanceCriteria":["O projeto Vite tem rotas `/` (lista), `/tasks/new`, `/tasks/:id` (edição) e uma rota curinga que mostra a página 404","Uma store Pinia guarda as tarefas e expõe as actions `fetchTasks`, `createTask`, `toggleTask` e `deleteTask`","Nenhum componente chama `fetch` diretamente: toda requisição passa por um módulo cliente da API"],"xp":35},{"key":"componentes-e-formulario","title":"Componentes e formulário de tarefas","acceptanceCriteria":["`TaskList`, `TaskItem` e `TaskForm` se comunicam por props e emits, sem alterar props diretamente","O formulário mostra, abaixo de cada campo, os erros de validação (422) devolvidos pelo Laravel","Marcar como concluída atualiza a tela e persiste na API; se a API falhar, a tela volta ao estado anterior e mostra uma mensagem"],"xp":30},{"key":"estados-de-loading-erro-e-vazio","title":"Estados de loading, erro e lista vazia","acceptanceCriteria":["Enquanto a lista carrega, a tela mostra um indicador (spinner ou skeleton) e as ações ficam desabilitadas","Com a API fora do ar, aparece uma mensagem de erro com o botão Tentar novamente, que refaz a requisição","Sem tarefas, a tela mostra um estado vazio com chamada para criar a primeira","Durante o envio do formulário o botão fica desabilitado, e um clique duplo não cria duas tarefas"],"xp":25},{"key":"testes-e-entrega","title":"Testes e entrega","acceptanceCriteria":["Testes de feature da API cobrem criar, listar, atualizar, excluir e os casos 404 e 422","`php artisan test` e `npm run build` terminam sem erros","O README explica como rodar API e SPA e traz capturas das telas de lista, erro e vazio"],"xp":20}]},{"slug":"api-rest-sanctum-e-testes","title":"API REST com Sanctum e testes","description":"Crie uma API REST em Laravel com autenticação por tokens do Sanctum (registro, login, logout e gestão de tokens) e um recurso privado de anotações protegido por policies de dono. O comportamento é coberto por uma suíte de testes com Pest. O projeto treina autenticação, autorização, respostas de erro consistentes e disciplina de testes.","level":"junior","difficulty":3,"position":2,"topics":["seg-autenticacao-sessoes","seg-autorizacao-rbac-abac","seg-hash-senhas-criptografia-basica","seg-owasp-top-10","php-autenticacao-sanctum","php-autorizacao-policies-gates","php-testes-com-pest"],"milestones":[{"key":"setup-pest-e-modelagem","title":"Setup, Pest e modelagem de anotações","acceptanceCriteria":["O projeto Laravel tem Pest instalado e `php artisan test` roda com pelo menos um teste verde","A migration cria `notes` com `user_id` (chave estrangeira com exclusão em cascata), `title` e `body`","As factories de User e Note permitem montar cenários como `Note::factory()->for($user)->create()`"],"xp":20},{"key":"registro-login-e-logout","title":"Registro, login e logout com tokens","acceptanceCriteria":["POST /api/register cria o usuário com a senha em hash (nunca em texto puro) e retorna 201 com o token de acesso","POST /api/login retorna um token para credenciais válidas; e-mail inexistente e senha errada devolvem o mesmo erro genérico (422 ou 401, de forma consistente)","POST /api/logout revoga o token atual e a mesma chamada com esse token passa a retornar 401","O login tem limite de tentativas (throttle) e responde 429 depois de exceder o limite"],"xp":35},{"key":"crud-protegido-de-anotacoes","title":"CRUD de anotações protegido","acceptanceCriteria":["Todas as rotas de `notes` ficam sob `auth:sanctum` e, sem token, retornam 401 em JSON","GET /api/notes devolve só as anotações do usuário autenticado, paginadas","Form Requests validam `title` e `body` (422 com erros por campo) e as respostas usam API Resources"],"xp":30},{"key":"tokens-com-abilities","title":"Tokens com abilities e expiração","acceptanceCriteria":["O login cria o token com abilities explícitas (ex.: `notes:read` e `notes:write`)","Um token só com `notes:read` consegue listar anotações, mas recebe 403 ao criar, editar ou excluir","GET /api/tokens lista os tokens do usuário e DELETE /api/tokens/{id} revoga um deles","Os tokens expiram (config `expiration` do Sanctum) e um token expirado recebe 401"],"xp":40},{"key":"policies-por-dono","title":"Autorização por dono com Policies","acceptanceCriteria":["`NotePolicy` permite ver, editar e excluir apenas ao dono da anotação","Acessar, editar ou excluir a anotação de outro usuário retorna 403 (ou 404, decisão registrada no README)","Enviar `user_id` de outro usuário no corpo do POST é ignorado: a anotação sempre pertence a quem está autenticado"],"xp":35},{"key":"suite-pest-e-entrega","title":"Suíte Pest e documentação","acceptanceCriteria":["Os testes de feature cobrem registro, login (sucesso e falha), logout, abilities, token expirado e policies (dono e não dono)","Há ao menos um dataset do Pest que testa várias entradas inválidas de validação em um único teste","O relatório `pest --coverage` mostra pelo menos 80% nos Controllers e nas Policies","O README lista os endpoints, mostra o fluxo de autenticação com exemplos `curl` e explica como rodar os testes"],"xp":30}]},{"slug":"blog-com-markdown-e-cache","title":"Blog com markdown e cache","description":"Construa um blog em que os posts são escritos em markdown e renderizados com sanitização contra XSS, servidos por uma API Laravel com paginação, cache de listagem e de página e invalidação precisa, com front-end em Vue. O projeto treina estratégias de cache (cache-aside e cabeçalhos HTTP), segurança de conteúdo gerado por usuários e medição do ganho de desempenho.","level":"mid","difficulty":3,"position":3,"topics":["arq-cache-e-cdn","sql-nosql-e-redis","web-http-em-profundidade","seg-xss-csrf","vue-router","php-cache","php-eventos-e-listeners"],"milestones":[{"key":"modelagem-e-crud-de-posts","title":"Modelagem e CRUD de posts","acceptanceCriteria":["A migration cria `posts` com `slug` único, `title`, `body_markdown`, `status` (draft ou published) e `published_at`, com índice composto em `status` e `published_at`","Rotas administrativas autenticadas criam, editam, publicam e excluem posts, e o slug nasce do título","Um seeder gera pelo menos 100 posts (publicados e rascunhos) para tornar paginação e cache mensuráveis"],"xp":30},{"key":"markdown-sanitizado","title":"Renderização de markdown sanitizada","acceptanceCriteria":["O servidor converte o markdown em HTML (ex.: league/commonmark) e a API devolve o campo `html` já pronto","Um post com `<script>` ou atributo `onerror` no markdown é renderizado sem esses elementos (teste automatizado de XSS)","Links `javascript:` são neutralizados e links externos recebem `rel=noopener noreferrer`"],"xp":35},{"key":"listagem-e-pagina-com-cache","title":"Listagem e página com cache","acceptanceCriteria":["GET /api/posts devolve só posts publicados, do mais recente ao mais antigo, 10 por página, com metadados de paginação","Listagem e página (GET /api/posts/{slug}) usam `Cache::remember` com chaves que incluem página, filtros ou slug, e um TTL definido","A segunda requisição idêntica não executa nenhuma query (comprovado em teste com `DB::getQueryLog()`)","A resposta do post traz `ETag` e `Cache-Control`, e `If-None-Match` igual retorna 304 sem corpo"],"xp":45},{"key":"invalidacao-de-cache","title":"Invalidação de cache","acceptanceCriteria":["Criar, editar, publicar, despublicar e excluir um post invalida a página dele e as listagens afetadas (via observer ou evento do model)","A invalidação usa tags de cache do Redis ou chaves versionadas, sem recorrer a `Cache::flush()`","Teste de feature: depois de editar o título, a listagem e a página já devolvem o título novo","Um rascunho (ou post despublicado) retorna 404 e não é servido de nenhum cache público"],"xp":45},{"key":"front-vue-do-blog","title":"Front-end Vue do blog","acceptanceCriteria":["As rotas `/` (listagem paginada) e `/posts/:slug` usam Vue Router, e a página atual fica na query string (`?page=2`)","O HTML é exibido com `v-html` somente a partir do campo `html` sanitizado da API, nunca de markdown cru","Carregamento, erro e post não encontrado (404) têm tratamento visível nas duas telas"],"xp":35},{"key":"testes-e-medicao","title":"Testes e medição do ganho de cache","acceptanceCriteria":["Os testes de feature cobrem sanitização (XSS), paginação, acerto e erro de cache e invalidação depois da edição","O README traz uma tabela de tempo de resposta e número de queries antes e depois do cache, com a metodologia usada","`php artisan test` e `npm run build` terminam sem erros"],"xp":30}]},{"slug":"painel-de-metricas-chartjs","title":"Painel de métricas com Chart.js","description":"Crie um dashboard em Vue 3 com vue-chartjs que consome uma API Laravel de agregações SQL (GROUP BY e window functions) sobre as vendas de uma loja fictícia, com filtros de período e granularidade. O projeto treina consultas analíticas, índices e leitura de EXPLAIN, composables reativos e o tratamento dos estados de carregamento, erro e vazio.","level":"mid","difficulty":3,"position":4,"topics":["sql-agregacoes-e-group-by","sql-window-functions-e-ctes","sql-indices","sql-explain-e-otimizacao","vue-composables","vue-computed-e-watch","php-n-plus-1-e-otimizacao-eloquent","php-validacao-e-form-requests"],"milestones":[{"key":"dados-de-vendas-e-seed","title":"Modelagem e carga de dados de vendas","acceptanceCriteria":["As migrations criam `products`, `orders` e `order_items` com chaves estrangeiras e valores monetários em centavos (inteiros)","O seeder gera pelo menos 50 mil pedidos em 12 meses, com status variados (`paid`, `canceled`, `refunded`) e categorias de produto","A carga é determinística (seed fixa), então duas cargas produzem os mesmos totais"],"xp":25},{"key":"endpoints-de-agregacao","title":"Endpoints de agregação com GROUP BY","acceptanceCriteria":["GET /api/metrics/revenue?from=&to=&granularity=day|week|month soma a receita dos pedidos `paid` no banco (`SUM` e `GROUP BY`), sem somar em PHP","Períodos sem vendas aparecem na série com valor 0 (série contínua)","Datas fora de ordem ou granularidade desconhecida retornam 422 via Form Request","Há também agregações por status do pedido e por categoria de produto, respeitando o mesmo filtro de período"],"xp":40},{"key":"window-functions-e-comparativos","title":"Window functions e comparativos","acceptanceCriteria":["A média móvel de 7 dias é calculada em SQL (`AVG() OVER` com `ROWS BETWEEN 6 PRECEDING AND CURRENT ROW`) sobre uma série diária contínua gerada por uma CTE de calendário","A variação percentual em relação ao período anterior da série é calculada com `LAG` e devolvida como `delta_pct`","Um endpoint devolve o top 5 de produtos por categoria usando `ROW_NUMBER() OVER (PARTITION BY ...)`","Testes comparam as respostas com valores calculados à mão sobre um dataset pequeno e fixo"],"xp":45},{"key":"performance-das-queries","title":"Índices e análise com EXPLAIN","acceptanceCriteria":["O README registra o `EXPLAIN` da query principal antes e depois de criar o índice (ex.: composto em `status` e `created_at`), mostrando a mudança no plano","Com 50 mil pedidos, a query de receita responde em menos de 200 ms (tempo medido e registrado)","O número de queries por requisição é constante, sem N+1 (verificado em teste)"],"xp":35},{"key":"dashboard-vue-com-graficos","title":"Dashboard Vue com vue-chartjs","acceptanceCriteria":["O Vue registra só os componentes do Chart.js que usa e renderiza gráfico de linha (receita), de barras (por categoria) e de rosca (por status) com vue-chartjs","Cartões de KPI mostram receita total, número de pedidos e ticket médio do período","A busca fica no composable `useMetrics`, que expõe `data`, `loading`, `error` e `refresh` e cancela a requisição anterior (`AbortController`) quando os filtros mudam","Valores monetários e datas aparecem em pt-BR (`Intl.NumberFormat` e `Intl.DateTimeFormat`) em eixos e tooltips"],"xp":40},{"key":"filtros-estados-e-entrega","title":"Filtros, estados de interface e entrega","acceptanceCriteria":["Filtros de período (7, 30 e 90 dias e intervalo personalizado) e de granularidade atualizam todos os gráficos e ficam refletidos na URL","Cada gráfico mostra skeleton ao carregar, mensagem com Tentar novamente em caso de erro e estado vazio quando não há dados","Cada gráfico tem `role=img` com `aria-label` descritivo e uma tabela de dados alternativa","O README explica como carregar os dados de exemplo e rodar API e painel, e traz capturas de tela do dashboard"],"xp":35}]},{"slug":"sistema-de-tarefas-com-filas-e-jobs","title":"Sistema de tarefas com filas e jobs","description":"Construa um sistema em que o usuário submete tarefas pesadas (como importar um CSV ou gerar um relatório) que o Laravel processa em segundo plano, com jobs, filas (Redis ou database), retries, eventos, listeners e notificações. Uma interface Vue acompanha o status e o progresso de cada tarefa. O projeto treina processamento assíncrono, idempotência, tratamento de falhas e consistência eventual.","level":"mid","difficulty":4,"position":5,"topics":["arq-filas-e-mensageria","sql-nosql-e-redis","sql-transacoes-e-acid","ops-logs-estruturados","vue-composables","php-filas-e-jobs","php-eventos-e-listeners","php-testes-com-pest"],"milestones":[{"key":"modelo-e-api-de-tarefas","title":"Modelo e API de tarefas","acceptanceCriteria":["A migration cria `tasks` com `type`, `payload` (JSON), `status` (queued, processing, completed, failed), `progress` (0 a 100), `error_message`, `started_at` e `finished_at`","POST /api/tasks valida o payload, grava a tarefa como `queued` e responde 202 com o id e o header Location","GET /api/tasks/{id} e GET /api/tasks (paginada, com filtro por status) devolvem o estado atual via API Resource"],"xp":25},{"key":"jobs-e-workers","title":"Jobs e workers em fila","acceptanceCriteria":["Um job `ProcessTask` (ShouldQueue) roda numa fila Redis ou database consumida por `php artisan queue:work`, sem bloquear a requisição HTTP","O job muda o status para `processing` e depois `completed`, e atualiza `progress` a cada lote processado","O dispatch usa `afterCommit`, para o worker nunca buscar uma tarefa que ainda não foi persistida","Com dois workers em paralelo e 20 tarefas, cada tarefa é processada uma única vez (conferido nos logs)"],"xp":40},{"key":"retries-backoff-e-falhas","title":"Retries, backoff e falhas","acceptanceCriteria":["O job define `$tries` e `backoff()` crescente; uma falha transitória é reexecutada e a tarefa termina `completed` na segunda tentativa (teste com falha simulada)","Esgotadas as tentativas, `failed()` marca a tarefa como `failed` com `error_message`, e o job aparece em `failed_jobs`","O processamento é idempotente: `php artisan queue:retry` reprocessa uma falha sem duplicar resultados","O `$timeout` do job é menor que o `retry_after` da conexão, evitando que um job lento seja reservado e executado duas vezes"],"xp":50},{"key":"eventos-listeners-e-notificacoes","title":"Eventos, listeners e notificações","acceptanceCriteria":["Ao terminar, a tarefa dispara `TaskCompleted` ou `TaskFailed`, tratados por listeners enfileirados (`ShouldQueue`)","O listener notifica o dono da tarefa por e-mail (mailer `log` ou Mailpit) e pelo canal `database`","Testes com `Event::fake` e `Notification::fake` provam que o usuário certo recebe a notificação certa, uma única vez"],"xp":40},{"key":"acompanhamento-no-front","title":"Acompanhamento de status no front","acceptanceCriteria":["A SPA lista as tarefas com badge de status e barra de progresso e permite criar uma nova","O composable `usePolling` consulta o status em intervalos e para sozinho quando a tarefa chega a `completed` ou `failed`","O polling pausa com a aba oculta e retoma ao voltar, e os timers são limpos ao sair da tela","Tarefas com falha exibem o erro, e as notificações do canal `database` aparecem em um sino com contador de não lidas"],"xp":40},{"key":"observabilidade-e-testes","title":"Observabilidade, testes e entrega","acceptanceCriteria":["Cada execução registra um log JSON com `task_id`, `attempt`, `duration_ms` e resultado","Testes cobrem o despacho (`Queue::fake`), o `handle` (status e progresso finais) e o ramo de falha (`failed()`)","O README explica como rodar o worker, como supervisioná-lo em produção e como tratar `failed_jobs`"],"xp":35}]},{"slug":"app-em-tempo-real-reverb-echo-vue","title":"App em tempo real com Reverb/Echo e Vue","description":"Construa um chat com salas e presença online usando Laravel Reverb no servidor e Laravel Echo em uma SPA Vue 3, com canais privados, canal de presença e autorização de canal. O projeto treina comunicação por WebSockets, eventos de broadcast, estados de conexão e estratégias de reconexão e ressincronização.","level":"mid","difficulty":4,"position":6,"topics":["vue-composables","seg-autenticacao-sessoes","seg-autorizacao-rbac-abac","ops-nginx-proxy-reverso","arq-escalabilidade-horizontal","php-reverb-e-broadcasting","php-autenticacao-sanctum"],"milestones":[{"key":"salas-e-mensagens-via-api","title":"Salas e mensagens via API","acceptanceCriteria":["As migrations criam `rooms`, `room_user` (membros) e `messages`, e POST /api/rooms/{room}/messages grava a mensagem e retorna 201","GET /api/rooms/{room}/messages devolve o histórico paginado e aceita `after_id` para buscar só mensagens mais novas","Somente membros da sala leem ou enviam mensagens; os demais recebem 403"],"xp":30},{"key":"reverb-e-echo-no-ar","title":"Reverb e Echo funcionando","acceptanceCriteria":["`php artisan install:broadcasting` configura o Reverb e `php artisan reverb:start` sobe o servidor WebSocket com host, porta e credenciais no `.env`","O evento `MessageSent` (`ShouldBroadcast`) é disparado ao criar a mensagem e seu payload tem apenas id, texto, autor e `created_at`","O Echo no Vue assina o canal e uma segunda aba recebe a mensagem em menos de 1 segundo, sem recarregar"],"xp":35},{"key":"canais-privados-e-autorizacao","title":"Canais privados e autorização","acceptanceCriteria":["O canal privado `rooms.{room}` é autorizado em `routes/channels.php` apenas para membros da sala","A SPA se autentica com Sanctum (cookie e CSRF) e o endpoint `/broadcasting/auth` autoriza a assinatura do canal","Um não membro que tenta assinar o canal recebe 403 (visível na aba Network e coberto por teste)","O remetente não vê a própria mensagem duplicada (`toOthers()` com o header `X-Socket-ID`, ou deduplicação por id)"],"xp":45},{"key":"presenca-e-digitando","title":"Presença online e indicador de digitação","acceptanceCriteria":["Um canal de presença por sala lista quem está online usando `here`, `joining` e `leaving`","Os dados de presença expõem apenas `id` e `name`, sem e-mail nem outros campos","O indicador de digitação usa client events (`whisper`) com throttle e some depois de 2 segundos sem digitar","Com duas abas e usuários diferentes, a entrada e a saída de cada um aparecem na outra em tempo real"],"xp":40},{"key":"reconexao-e-ressincronizacao","title":"Reconexão e ressincronização","acceptanceCriteria":["A interface mostra o estado da conexão (conectado, reconectando, offline) a partir dos eventos de conexão do Echo/Pusher","Ao derrubar e subir o Reverb, o cliente reconecta sozinho, sem recarregar a página","Depois de reconectar, o front busca as mensagens perdidas com `after_id` e as mescla sem duplicatas (deduplicação por id)","Uma mensagem enviada durante a queda aparece com o estado Enviando e, se a API falhar, é marcada com erro e botão de reenviar"],"xp":50},{"key":"producao-testes-e-entrega","title":"Produção, testes e entrega","acceptanceCriteria":["Testes de feature cobrem a autorização de canais (membro autorizado, não membro negado, presença só com `id` e `name`) e o disparo do evento com `Event::fake`","Mensagens com HTML aparecem como texto no front, sem executar","O README documenta o proxy do Nginx para WebSocket (`Upgrade` e `Connection`), TLS (wss) e `allowed_origins` do Reverb","O README explica como escalar o Reverb horizontalmente (`REVERB_SCALING_ENABLED` com Redis)"],"xp":35}]},{"slug":"api-com-ci-cd-e-docker","title":"API com CI/CD e Docker","description":"Empacote uma API Laravel (por exemplo, a do projeto com Sanctum) em uma imagem Docker multi-stage e monte um pipeline no GitHub Actions com lint, análise estática, testes, build e publicação da imagem, seguido de deploy automatizado. O projeto treina containers prontos para produção, integração e entrega contínuas, gestão de segredos e estratégias de rollback.","level":"mid","difficulty":4,"position":7,"topics":["ops-docker","ops-docker-compose","qual-ci-github-actions","qual-cd-estrategias-release","ops-deploy-php-node","seg-gestao-segredos","php-composer-e-psr","php-laravel-em-producao"],"milestones":[{"key":"dockerfile-multi-stage","title":"Dockerfile multi-stage","acceptanceCriteria":["O Dockerfile multi-stage instala dependências com `composer install --no-dev --optimize-autoloader` e a imagem final não contém Composer, `.git` nem pacotes de desenvolvimento","O container roda com usuário não root e tem `HEALTHCHECK` apontando para o endpoint `/up`","O `.dockerignore` exclui `vendor`, `node_modules`, `.env` e `.git`, e o tamanho da imagem final (abaixo de 300 MB) é registrado no README"],"xp":40},{"key":"compose-local","title":"Ambiente local com Docker Compose","acceptanceCriteria":["`docker compose up -d` sobe app (PHP-FPM), Nginx, banco (MySQL ou PostgreSQL) e Redis a partir de um clone limpo","Os serviços têm `healthcheck` e `depends_on` com `condition: service_healthy`, e a aplicação só inicia depois do banco","As migrations rodam por um serviço ou comando dedicado, e os dados do banco persistem em volume nomeado"],"xp":30},{"key":"pipeline-de-ci","title":"Pipeline de CI no GitHub Actions","acceptanceCriteria":["O workflow roda em `push` e `pull_request` com jobs separados de lint (Pint `--test`), análise estática (Larastan/PHPStan) e testes (Pest)","Os testes rodam contra um banco real em `services:` do workflow, e as dependências do Composer ficam em cache entre execuções","`composer audit` faz parte do pipeline e quebra o build quando encontra vulnerabilidade","A proteção de branch exige os checks verdes para fazer merge na `main`"],"xp":50},{"key":"build-e-publicacao-da-imagem","title":"Build e publicação da imagem","acceptanceCriteria":["O job de build usa `docker/build-push-action` com cache de camadas e só roda depois de lint, análise e testes passarem (`needs`)","A imagem vai para o GitHub Container Registry com tags `sha-<commit>` e `latest` em pushes na `main`, e com a versão semântica em tags `vX.Y.Z`","Um scan de vulnerabilidades da imagem (ex.: Trivy) roda no pipeline e falha o build para severidade CRITICAL"],"xp":40},{"key":"deploy-automatizado-e-segredos","title":"Deploy automatizado e segredos","acceptanceCriteria":["Depois da publicação, o pipeline faz deploy automático em staging (SSH com `docker compose pull` e `up -d`, ou PaaS equivalente), e produção exige aprovação manual via GitHub Environment","Segredos (chave SSH, `APP_KEY`, credenciais do banco) ficam em GitHub Secrets ou Environments; nenhum aparece no repositório, nos logs do workflow ou nas camadas da imagem (checado com `docker history` e um scanner como gitleaks)","O deploy executa as migrations e só termina com sucesso quando o health check `/up` responde 200"],"xp":55},{"key":"rollback-e-documentacao","title":"Rollback e documentação","acceptanceCriteria":["Existe um procedimento de rollback (redeploy da tag anterior via `workflow_dispatch` ou script) e ele foi exercitado ao menos uma vez","O README tem diagrama do pipeline, badge de status do CI e instruções para lançar uma versão e para reverter","A estratégia de release adotada (recreate, rolling ou blue-green) e a duração total do pipeline estão registradas no README"],"xp":30}]},{"slug":"ecommerce-modular-carrinho-pedido","title":"E-commerce modular (carrinho e pedido)","description":"Implemente um monólito modular em Laravel com DDD básico e os módulos de catálogo, carrinho, pedido e estoque, que se comunicam por contratos e eventos de domínio e expõem uma API versionada em /api/v1. O foco é a consistência do checkout: transações, locks contra venda além do estoque (overselling) e idempotência com Idempotency-Key. O projeto treina fronteiras de módulos, modelagem de agregados, concorrência no banco e registro de decisões em ADRs.","level":"senior","difficulty":5,"position":8,"topics":["arq-monolito-modular","arq-ddd-basico","sql-transacoes-e-acid","sql-isolamento-e-locks","arq-apis-rest-maduras","php-actions-services-e-arquitetura","php-eventos-e-listeners","php-testes-com-pest"],"milestones":[{"key":"modulos-e-fronteiras","title":"Módulos e fronteiras","acceptanceCriteria":["Os módulos Catalog (catálogo), Cart (carrinho), Ordering (pedidos) e Inventory (estoque) têm pasta, ServiceProvider, rotas e migrations próprios, com camadas Domain, Application e Infrastructure","Cada módulo expõe uma interface pública (contratos e DTOs), e nenhuma classe usa models Eloquent de outro módulo","Um teste de arquitetura (Pest `arch()` ou Deptrac) falha se alguém introduzir uma dependência proibida entre módulos"],"xp":50},{"key":"catalogo-e-estoque","title":"Catálogo e estoque","acceptanceCriteria":["GET /api/v1/products e GET /api/v1/products/{id} devolvem o catálogo paginado, e o preço usa um value object `Money` (centavos inteiros e moeda), sem `float`","O módulo Inventory guarda `on_hand` e `reserved` por SKU, e uma constraint `CHECK` (ou validação equivalente) impede valores negativos","`reserve`, `release` e `commit` são operações do módulo Inventory cobertas por testes de unidade e de integração"],"xp":40},{"key":"carrinho-como-agregado","title":"Carrinho como agregado","acceptanceCriteria":["O agregado `Cart` protege suas invariantes: quantidade de 1 a 10 por item, SKU único (adicionar de novo soma a quantidade) e carrinho vazio não vai ao checkout","POST, PATCH e DELETE em /api/v1/cart/items devolvem o carrinho com subtotais e total recalculados no servidor","Preços enviados pelo cliente são ignorados: o total sempre vem do catálogo no momento do cálculo (coberto por teste)"],"xp":45},{"key":"checkout-transacional-e-concorrencia","title":"Checkout transacional e concorrência","acceptanceCriteria":["O checkout cria o pedido e seus itens, reserva o estoque e esvazia o carrinho em uma única transação, e uma falha no meio desfaz tudo (teste força o erro)","A reserva usa `lockForUpdate` ou um `UPDATE ... WHERE available >= ?` atômico; um teste com requisições concorrentes pelo último item gera exatamente 1 pedido e estoque nunca negativo","Os locks são adquiridos sempre na mesma ordem (por id de SKU), e deadlocks são tratados com retry (`DB::transaction` com tentativas)"],"xp":60},{"key":"eventos-de-dominio-e-idempotencia","title":"Eventos de domínio e idempotência","acceptanceCriteria":["O módulo Ordering publica `OrderPlaced` e `OrderCancelled` somente depois do commit, e Inventory e Cart reagem por listeners, sem acoplamento direto","Cancelar um pedido libera as reservas via listener, e processar o mesmo evento duas vezes não libera o estoque em dobro","POST /api/v1/checkout exige o header `Idempotency-Key`: a mesma chave com o mesmo corpo devolve a resposta original sem criar outro pedido, e com corpo diferente retorna 422","Duas requisições simultâneas com a mesma chave criam um único pedido (índice único na tabela de chaves)"],"xp":55},{"key":"qualidade-adrs-e-entrega","title":"Qualidade, ADRs e entrega","acceptanceCriteria":["Há ao menos 3 ADRs (fronteiras dos módulos, estratégia de lock e isolamento, idempotência) com contexto, decisão, alternativas e consequências","A API tem versão no caminho (`/api/v1`), erros padronizados (Problem Details ou formato único documentado) e documentação OpenAPI","`composer test` roda a suíte completa (unidade, feature, concorrência e arquitetura), e o README traz o mapa dos módulos e o fluxo do checkout"],"xp":35}]},{"slug":"observabilidade-logs-metricas-alertas","title":"Observabilidade: logs, métricas e alertas","description":"Instrumente uma aplicação Laravel (pode ser um dos projetos anteriores) com logs estruturados em JSON, métricas no formato Prometheus, traces com OpenTelemetry e dashboards no Grafana, definindo SLIs, SLOs e alertas por burn rate. O projeto treina observabilidade de ponta a ponta, a correlação entre logs, métricas e traces e a escrita de um runbook usado em uma simulação de incidente.","level":"senior","difficulty":4,"position":9,"topics":["ops-logs-estruturados","ops-metricas-e-alertas","ops-tracing-distribuido","ops-sli-slo-incidentes","ops-docker-compose","car-documentacao-tecnica","php-laravel-em-producao"],"milestones":[{"key":"stack-local-e-logs-estruturados","title":"Stack local e logs estruturados","acceptanceCriteria":["`docker compose up` sobe a aplicação, Prometheus, Grafana, Alertmanager e Loki (com Grafana Alloy ou OpenTelemetry Collector coletando os logs), com os datasources do Grafana provisionados por arquivo","Cada requisição gera uma linha de log JSON com `request_id`, `method`, `route`, `status`, `duration_ms` e `user_id` (quando há usuário)","Senhas, tokens e outros dados sensíveis aparecem mascarados nos logs (coberto por teste automatizado)","No Grafana, é possível filtrar os logs por `request_id` e por `level=error`"],"xp":45},{"key":"metricas-red-e-de-negocio","title":"Métricas RED e de negócio","acceptanceCriteria":["O endpoint `/metrics` expõe `http_requests_total` e `http_request_duration_seconds` (histograma) com os labels `method`, `route` e `status`","O label `route` usa o padrão da rota (`/orders/{id}`), nunca a URL real, para evitar explosão de cardinalidade","Há ao menos uma métrica de negócio (ex.: `orders_created_total`) e uma de fila ou jobs (ex.: jobs com falha)","O Prometheus coleta a aplicação a cada 15 segundos e o target aparece como UP em `/targets`"],"xp":45},{"key":"traces-com-opentelemetry","title":"Traces com OpenTelemetry","acceptanceCriteria":["A aplicação envia traces por OTLP para um OpenTelemetry Collector e um backend (Tempo ou Jaeger), com spans de HTTP, queries e chamadas externas","O `trace_id` aparece nos logs, permitindo ir de um log de erro ao trace correspondente no Grafana","O contexto é propagado em ao menos uma chamada de saída (header `traceparent`) ou em um job de fila"],"xp":40},{"key":"dashboards-no-grafana","title":"Dashboards no Grafana","acceptanceCriteria":["Um dashboard versionado (JSON provisionado) mostra taxa de requisições, taxa de erros 5xx e latência p50, p95 e p99 por rota","Os percentis são calculados com `histogram_quantile` sobre o histograma de duração","Do painel de latência é possível pular para os logs e traces do mesmo intervalo (links de drilldown)"],"xp":35},{"key":"slis-slos-e-alertas","title":"SLIs, SLOs e alertas","acceptanceCriteria":["SLIs de disponibilidade e de latência estão definidos como recording rules do Prometheus, com SLO e janela de 30 dias documentados","O orçamento de erro restante aparece em um painel do dashboard","Alertas de burn rate com duas janelas (ex.: 1h e 5min para o rápido, 6h e 30min para o lento) chegam ao Alertmanager com severidade e roteamento para um receiver de teste","Cada alerta tem `summary` e `runbook_url` e foi validado disparando e resolvendo de propósito (derrubando a aplicação ou injetando erros)"],"xp":50},{"key":"runbook-e-simulacao-de-incidente","title":"Runbook e simulação de incidente","acceptanceCriteria":["Há um runbook em Markdown para cada alerta principal, com sintoma, impacto, como diagnosticar (painéis e queries), mitigação e escalonamento","Um incidente simulado (latência ou erros 500 injetados em uma rota) é detectado pelo alerta e diagnosticado seguindo métricas, traces e logs","Um post-mortem sem culpados registra linha do tempo, causa raiz, tempos de detecção e de mitigação e ações corretivas com responsáveis"],"xp":45}]},{"slug":"rate-limiter-e-cache-distribuido","title":"Rate limiter e cache distribuído","description":"Implemente em PHP/Laravel com Redis rate limiters (token bucket e sliding window) atômicos via scripts Lua, mais uma camada de cache distribuído com proteção contra cache stampede e estratégias de invalidação. Valide tudo com testes de carga em k6 e registre as decisões em ADRs. O projeto treina concorrência distribuída, trade-offs de consistência e medição de desempenho.","level":"senior","difficulty":5,"position":10,"topics":["sql-nosql-e-redis","arq-cache-e-cdn","arq-escalabilidade-horizontal","arq-cap-consistencia-eventual","arq-adrs-documentacao-decisoes","fund-complexidade-big-o","php-cache","php-rotas-e-controllers"],"milestones":[{"key":"token-bucket-atomico","title":"Token bucket atômico com Redis","acceptanceCriteria":["Uma interface `RateLimiter` e uma implementação de token bucket executam reposição e consumo em um único script Lua no Redis (EVAL ou EVALSHA), sem corrida entre ler e gravar","Testes mostram que a requisição seguinte à capacidade é negada e que os tokens voltam conforme a taxa de reposição, usando um relógio controlável em vez de `sleep`","As chaves por cliente (API key ou IP) expiram por TTL derivado da taxa de reposição, sem vazar memória no Redis"],"xp":50},{"key":"sliding-window","title":"Sliding window","acceptanceCriteria":["Há uma implementação de sliding window (log em sorted set ou contador em duas janelas), também atômica via Lua, atrás da mesma interface `RateLimiter`","Um teste reproduz a rajada na virada da janela e mostra que a janela fixa admite até o dobro do limite, enquanto a sliding window não","O README compara custo de tempo e de memória por chave (log: O(n) por requisição; contador: O(1)) e diz quando usar cada algoritmo"],"xp":45},{"key":"middleware-e-politica-de-falha","title":"Middleware HTTP e política de falha","acceptanceCriteria":["Um middleware aplica o limite por rota e por cliente e, ao excedê-lo, responde 429 com `Retry-After` e corpo JSON padronizado","As respostas trazem `X-RateLimit-Limit`, `X-RateLimit-Remaining` e `X-RateLimit-Reset` coerentes com o estado do limiter","Com o Redis indisponível, o comportamento é configurável (fail-open ou fail-closed por rota), registrado em log e coberto por teste"],"xp":40},{"key":"cache-distribuido-e-stampede","title":"Cache distribuído e proteção contra stampede","acceptanceCriteria":["Uma camada de cache-aside com Redis aplica TTL com jitter e suporta invalidação por evento e por versão de chave","Com o cache vazio, 50 requisições concorrentes pelo mesmo recurso executam a consulta cara uma única vez (lock ou single-flight), provado por um contador de execuções no teste","Consultas repetidas a um recurso inexistente chegam ao banco só uma vez dentro do TTL do cache negativo"],"xp":55},{"key":"testes-de-carga-e-medicao","title":"Testes de carga e medição","acceptanceCriteria":["Scripts k6 versionados cobrem carga constante e pico (spike), rodando contra a API com e sem cache","O relatório registra p50, p95 e p99, vazão, taxa de erro e taxa de acerto do cache, antes e depois do cache e do limiter","Com 200 usuários virtuais disputando a mesma chave, o limiter admite no máximo o limite configurado mais a tolerância documentada (contagem de respostas 2xx e 429)","Um teste de caos derruba o Redis durante a carga e confirma a política de falha definida e a recuperação quando ele volta"],"xp":55},{"key":"adrs-e-documentacao","title":"ADRs e documentação","acceptanceCriteria":["Há ao menos 3 ADRs (algoritmo de limite, política de falha do Redis, estratégia de invalidação) com contexto, decisão, alternativas e consequências","Cada ADR discute o trade-off de consistência e disponibilidade (CAP) e os limites conhecidos (ex.: Redis único versus cluster com hash tags, relógio entre nós)","O README explica como rodar os testes e os testes de carga e como interpretar os resultados"],"xp":30}]}]}$content$::jsonb);
